/* 令和4年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20220418-9","meetingId":"r04-cm04","date":"2022年4月18日","dateIso":"2022-04-18","committee":"文教委員会","time":"午後 １時００分～午後 ３時２３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"教育目標の改訂","agenda":"教育目標の改訂","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回の改訂案に関する議論が教育委員会で行われた日はいつで、何回になりますでしょうか。それで、どんな意見が出て、どんな議論があったのか、ご紹介いただければと思います。","respondent":"宮尾庶務課長","answer":"こちらの改訂につきましては、教育委員会での審議を経ての改訂ということになってあります。具体的には、教育委員会では３回、審議をさせていただきました。令和３年１２月１４日、令和４年３月２４日、令和４年３月３１日です。","voiceIndex":14,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"逆に、この間、東京都こども基本条例の制定など、子どもに直接関わる大きな社会状況の変化があったと思うのですけれども、それが入っていないのはなぜなのか、伺いたいと思います。","respondent":"宮尾庶務課長、矢部教育総合支援センター長","answer":"全ての社会状況の変化というのをつぶさに盛り込むということには必ずしもなっていない面はありますが、それでも例えば、繰り返しになりますが、長期基本計画の動向等、区の進める施策との整合性を。東京都こども基本条例につきましては、東京都から、人権教育プログラムというところに改めて記載がありまして、きちんと進めてまいりたいと考えておりますし、これまでも人権教育ということで、市民科を中心に。","voiceIndex":16,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"それで質問なのですけれども、人権教育というところで、５つの柱のうち１番に来ていて、それは大事だと思うのですけれども、具体的な方針の中身を見ますと、人権の教育の推進を教育委員会で掲げていくという中で、子どもが権利の主体であるというような記述というのがほぼないというのは、私はすごく違和感があって、やはり人権教育をいの一番に挙げるのであれば、当然。","respondent":"矢部教育総合支援センター長","answer":"ほかにも、「子どもたちが」という主語のところはありまして、教育ですので、やはり子ども中心ということは我々変えようもございませんので、これからもしっかりやってまいりたいと考えています。","voiceIndex":19,"id":"exchange-003"},{"speaker":"安藤委員","kind":"意見","question":"最後に意見だけ言いますけれども、今の（１）のところも、子ども等々に対する偏見や差別をなくしという文脈のところに使われているだけなので、やはり正面から、教育目標や基本方針をつくる上で人権教育ということを掲げるのであれば、そういうところの記述にとどまるのではなく、きちんと、しっかりと文言として、子どもは権利の主体ですというところ、子どもの権利条約というところを入れるべきだと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで、先ほど、（２）のところの「子どもたちが」とあるとおっしゃったのですけれども、（２）については、子どもたちが他者の権利についてきちんと理解しということで、繰り返しになって申し訳ありませんが、自分たちが主体であるということ、それで自分がそれを主張して、具体的には、子どもの権利、自分たちの権利には、こういうことが含まれているということを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-005"}]},{"id":"topic-02","title":"令和４年度 学級編制","agenda":"令和４年度 学級編制","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"ピンク色のところで、加配する三木小学校と荏原第六中学校なのですけれども、これは区の独自教員を充てているということでよろしいのかという確認と、そういうクラスを増やすということについて、どういう場合に、区教育委員会としては認めていらっしゃるのでしょうか。説明がありましたけれども、様々なケースというものがほかにあれば伺いたいと思います。","respondent":"勝亦学務課長","answer":"こういった固有教員や定数の中で対応できるという中で、可能な限り丁寧な対応、具体的には、発達障害のお子さんが通常クラスに複数いらっしゃるですとか、体調を崩しやすいお子さんがいるとか、そういった場合につきまして、丁寧な対応ができないかということで学校の中で検討し。","voiceIndex":28,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"一方で、芳水小学校の２年生は、去年、１年生でしたけれども、去年に引き続き学級数を増やさないまま、本当なら５クラスなわけですが、４クラスのまま、上に上がったということで、なぜこうした対応の違いが生まれたのか、両者には何の違いがあったのかということを伺いたいと思います。","respondent":"勝亦学務課長","answer":"違いという部分ですけれども、各学校のお子様や教室の状況、児童・生徒の状況等々、各学校と個別に協議・確認しながら進めておりますので、第二延山小学校と芳水小学校が、今、例えということで出てまいりましたけれども、同じ対応というような形では。","voiceIndex":30,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"法律で３５人学級という編成になっていて、芳水小学校の場合は毎学年、クラス替えもしているような状況なので、無理にそのまま４クラスにする必要はないのかと思うのですけれども、学校にもいろいろな事情があるのでしょうが、やはり物理的な問題なのかどうかというのは確認させていただきたい。物理的な問題があったのかどうか確認させてください。確かに緊張しますよね。","respondent":"勝亦学務課長","answer":"例えば縦割りの学級を組むような場合ですと、今回２年生を５クラスにしてしまいますと、それぞれまたクラスの中で分けたり、合体させたりというような縦割り編制を組むときに、大きな変更や、子どもたちの混乱が発生するということで、縦割り学級等をやりやすいように。","voiceIndex":32,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"なので、今の答弁だと、結局、区教育委員会としては、では、この５つの学校それぞれについて、どういう理由なのかというのをつかんでいないように聞こえたのですけれども、改めて、分かる範囲でいいのですけれども、結局、では全ての５つの中学校が、教員加配、学級数を増やさないでチームティーチングにしたほうが、教育活動がすばらしいものになるという判断の下で選択したという認識でよろしいでしょうか。","respondent":"勝亦学務課長","answer":"グループワーク等をやるときに細かな対応ができるように、複数指導を取りたいのだというふうにお考えの学校もあります。そういった中で、いろいろな形でのチームティーチング、それから、少人数の学級規模の縮小という形で、中１ギャップへの対応に取り組んでいるところです。","voiceIndex":34,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"様々、子どもの充実した教育のために努力されているというのは理解できるところなのですけれども、やはりまずは教育環境としては３５人というのをしっかり守った上で、その上で、チームティーチングを充実したいとか、グループワークを充実したいというのであれば、そこにきちんと別に加配するとか、そういう支援の仕方が求められているのではないかと、私は思いました。最後、質問だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後は、令和７年度までには完全な３５人学級が求められているということで、それまでは特別な事情がある場合は各自治体で対応可という説明が冒頭あったと思うのですけれども、つまり、令和７年度で法律が完全実施されると、今取っているような例外的な対応というのは、もうできないということなのでしょうか。そういう法律の立てつけになっているかどうかだけ確認させてください。","respondent":"勝亦学務課長","answer":"法律の立てつけ上、令和７年４月以降は、弾力的な運用は経過措置に入ってございませんので、全て３５人学級という形になります。","voiceIndex":40,"id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"基本的なことを伺って恥ずかしいのですけれども、弾力的運用というのは、あくまで３５人学級を目指すまでという、それを目指す前提で、できないところに弾力的運用ということなのでしょうか。","respondent":"勝亦学務課長","answer":"上限が３５人という部分につきまして、令和７年度に実施されるという形になります。","voiceIndex":43,"id":"exchange-012"},{"speaker":"吉田委員","kind":"質問","question":"３５人学級が実現したとして、そういう配慮が必要なお子さんが複数いた場合、やはりその対応というのは必要になるのではないかと思うのですけれども、それは弾力的運用が続くと理解してよろしいでしょうか。","respondent":"勝亦学務課長","answer":"先ほども申しました固有教員ですとか、教員の定数の範囲の中では、そういった柔軟な対応は可能かと考えております。","voiceIndex":45,"id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。教育テレビで放映されたものだと思うのですけれども、関西のほうの学校で、本当に多様なお子さんが１つのクラスに集まっていて、それは、例えば複数担任制とか、そういうことで、お互いの子どもたちも助け合って、だから本当に、そのクラスの中が１つの社会なのです。色々な人、色々な子がいるということで。これは、あくまでこれからの教育に向けての要望ということで終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-014"},{"speaker":"松本委員","kind":"質問","question":"学級数と児童数は書かれているのですけれども、教員の人数というところで少しお伺いしたいと思っていて、令和３年の同じ資料も拝見すると、令和３年は、中学校のほうは少し学級数が減っているのですけれども、小学校のほうは学級数が、令和３年度は２２学級増えていて、令和４年度も２１学級増えているということで、２年で４０学級以上増えているという状況だと思います。","respondent":"中谷指導課長","answer":"基本的に、学級数が増えることによって、教員の定数も増えるという形になっておりますので、今回、子どもたちが増えたことによって、教員の数が増えないということはございません。","voiceIndex":49,"id":"exchange-015"},{"speaker":"松本委員","kind":"質問","question":"増えるタイミング、例えば令和４年にばっと増えてしまったときに、人数が追いつくのかというか、配置は普通、人事は４月に行われるのかと思っていて、そうすると、それは計画的に、大体その前の段階で、このぐらい増えるだろうということで見通しを立てて、４月には間に合うように増やしているという理解でよろしいのでしょうか。","respondent":"中谷指導課長","answer":"ご指摘いただいたとおりでございまして、前年度の半年ほど前から、子どもたちの数の見込みを校長として立てながら、それに応じた、学級数に応じた教員の数ということで見込んでまいりますので、かなり時間をかけて。","voiceIndex":51,"id":"exchange-016"},{"speaker":"つる委員","kind":"質問・要望","question":"この３６％ぐらいのさらに内訳というのでしょうか、純粋に本当に私学ないし公立の中高一貫などに進学されている数字、それから転出、単純に区外の学校に行かれたということがあると思うのですけれども、この三十数％の内訳が分かれば教えていただきたいというところと、そういう傾向性、大体このぐらいの数字で推移している、なぜそれぐらいなのかという分析があれば、そのところと、さらにもう一つ加えて。","respondent":"勝亦学務課長、中谷指導課長","answer":"こちらは転出等もあります。今おっしゃったように、国立等の部分。こちらは今、集計中でございまして、５月の文教委員会で、その増減の割合については詳細を報告して、分析結果を併せてご報告したいと考えております。それで、３月の大体上旬から中旬頃に、見込みで転入してくる教員が分かってくるので、その全体像が把握できたところで、各学校で校長が人事組織を組んでいくと。","voiceIndex":55,"id":"exchange-017"},{"speaker":"つる委員","kind":"質問","question":"今日、学級編制についてという部分なのですが、１点伺っていたところが抜けているかと思ったのですが、こういう傾向性、３６％とか３３％とか、この辺で推移してきているところ。","respondent":"勝亦学務課長","answer":"私立への進学率に関しましては、年々、大体１％ずつ上昇していると考えております。小学校に関しましても１％ほど上昇しまして、まだ集計中ではありますけれども大体６％という、年々、私立への傾向がここ数年は強まっているのかという、全体の傾向は見てあります。","voiceIndex":58,"id":"exchange-018"},{"speaker":"つる委員","kind":"質問","question":"また何かの機会に、こういう文教委員会での報告事項になるかどうかはあれですけれども、そういう形で報告があるのか、もしくはなければ、何かの機会で、そういう品川区の教育の１つの成果、評価というところだと思いますので、そういったところも含めて、改めて伺っていければと思います。引き続きよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-019"}]},{"id":"topic-03","title":"令和４年度品川区立幼稚園、小・中学校、義務教育学校 園長・校長・副校長異動者名簿","agenda":"令和４年度品川区立幼稚園、小・中学校、義務教育学校 園長・校長・副校長異動者名簿","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"３点質問いたします。１つは、幼稚園の園長で欠員という表現があったのですけれども、今、兼任の方が随分いますけれども、基本的には欠員という認識で、独自に充てるという考えなのでしょうかというのを、まず伺います。それと、校長や副校長等の配置・異動の決まり方というのが現状どうなっているのか、改めて教えていただきたいと思います。それが２点目です。","respondent":"中谷指導課長","answer":"３点ご質問いただきました。１つ目の、幼稚園の欠員についてですけれども、現在、全都的に欠員しているという状況です。各自治体で同様なのですけれども、品川区といたしましても、小学校との兼任ということで進めさせていただいているところです。","voiceIndex":65,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"配置・異動の決まり方を伺ったのですけれども、漠然とし過ぎて申し訳ないのですが、基本的なことが分からないのでごめんなさい。それと、大井第一小学校では大規模校で増員ということなのですが、大井第一小学校に限らず、大規模校というのはほかにもあると思うのですけれども、２人目の副校長を置く基準というのですか、考え方があるのであれば教えてください。","respondent":"中谷指導課長","answer":"幼稚園の募集ですけれども、先ほど申し上げましたとおり、欠員状況があるというところがありますので、なかなか確保が難しいという背景があります。","voiceIndex":67,"id":"exchange-021"},{"speaker":"吉田委員","kind":"質問","question":"幼稚園の園長先生なのですけれども、小学校の校長先生の兼任ということですが、基本、幼稚園教諭というのは別の資格が必要だと思うのです。それで、園長先生だからということなのでしょうか。幼稚園教諭の資格を持っていなくてよいのでしょうか。","respondent":"中谷指導課長","answer":"今ご指摘いただいたこととしては、幼稚園の教員の採用と管理職の採用というところかと思うのですが、小学校と中学校もそうなのですが、管理職の配置と、教員の、実際に子どもたちに教えるほうの配置の採用というのは異なっておりまして、他校種でもそうなのですが。","voiceIndex":70,"id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"ただ、やはり子どもたちに接するというところで、私の身近で考えると、幼稚園教諭の資格を持った方が現場で経験を踏んで管理職にもなっていくというような考え方かと思っていたので、公立のこういうところの採用の仕方は認識がなくて申し訳ありませんでしたが、基本、やはり何か、ちょっと違うような気がしていて、先ほど幼稚園の園長先生の確保が難しいというところで。","respondent":"中島教育長","answer":"そういう状況の中で苦慮しているということです。指導課長につきましては、今月ある指導課長の会で、また実際に「そういうシステムですよ」というのをこれから説明していただくという状況にありますので、私のほうで今、代わりに、事務的な話ですが、説明をさせていただきました。","voiceIndex":72,"id":"exchange-023"},{"speaker":"吉田委員","kind":"意見","question":"事情はよく分かりました。ただ、保育園・幼稚園の現場を少しだけでも知っている、そうですね。やはり、現場の幼稚園教諭の先生方はあまり管理職のほうに回りたくないという方、現場が好き、子どもたちが好きでという方も多いのかと思います。確保の厳しさはよく理解できました。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-024"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"すみません。その他で１個だけ質問させてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"土曜授業日の変更についてです。予算特別委員会で取り上げられたのですけれども、その後、私どもも、昨年９月１４日開催の第１２回教育委員会の会議録を確認させていただきました。そこで、協議事項として話し合われたということが確認できました。私どもも早速、資料５をくださいということを伺ったのですが、この件について文教委員会への報告はなかったと認識しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。それで、生活者ネットワークとしては、土曜日授業の変更ということ自体には、今ご説明のとおり、なるほどと思うところなのですけれども、教育委員会の会議録ではそこまで出ていなかったですかね。ＰＴＡ……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-027"},{"speaker":"吉田委員","kind":"意見","question":"要するに、学校にはすぐに伝達が行ったということは分かっております。それで、地域の方やＰＴＡへの報告はどの時点でどういうふうにされたのか、その点についてもご報告を頂ければ、頂きたいと思います。","respondent":"矢部教育総合支援センター長","answer":"我々からも年間の計画を出しますので、それが本当にきちんとできるのが３月ぐらいになって、実際には学校の中では、「４月１日からがきちんとした計画ですよ」と、保護者にも地域にもご説明するというのが筋でございまして、教育委員会では協議して。","voiceIndex":84,"id":"exchange-028"},{"speaker":"吉田委員","kind":"確認","question":"分かりました。では手順をきちんと踏むと、ＰＴＡへの報告については、どうしても３月とか、実際の土曜日授業の変更が始まる直前にならざるを得ないという理解でよろしいのでしょうか。その前に、ＰＴＡのしかるべき立場の方はもう既に把握しておられて、その方たちの報告の手順も踏まえると、どうしても遅くなってしまうという理解でよろしいのでしょうか。改めて確認いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"委員会運営の話なのですが、その他で際限なく何でもかんでもやればいいとは思っていないのですが、例えば、情勢的に、緊急に委員会に関わるような事件が起きたとか、そういう際などは、やはり、ある程度、質疑というのは認められるべきだと思いますので、今後の委員会運営でも、ぜひその辺は柔軟に対応していただきたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-030"}]},{"id":"topic-05","title":"「児童相談所開設に向けた計画書」の策定","agenda":"「児童相談所開設に向けた計画書」の策定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"計画書の公開の方法はどうなっているのでしょうか。ホームページに載せるということなのでしょうか。細かいことなのですけれども、計画がどういった方々で検討されたのかというのも大事な情報だと思うのですけれども、計画検討委員会と、あと庁内の推進委員会をつくりましたけれども、メンバーをこの冊子の中に掲載すべきなのではないかと思うのですけれども、いかがでしょうか。","respondent":"長谷川児童相談所移管担当課長","answer":"２点目としまして、計画検討委員会のメンバーということですが、まず、設置に向けた計画検討委員会に関しましては、立正大学の大竹智教授をはじめ、弁護士の先生や養護関係の先生、それから母子保健関係の大学の教授にご参加いただいております。","voiceIndex":109,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"それと中身なのですけれども、冊子のほうで幾つかお伺いします。５ページですが、開所時間の件なのですけれども、現在の都の児童相談所と変わるところがあるのか、同じなのか。これに照らして、人事異動の期間なども考える必要があるのではないかと思うのですけれども、いかがでしょうか。","respondent":"長谷川児童相談所移管担当課長","answer":"様々な支援サービスを理解した児童福祉司による指導が実現可能になるという点が、区の強みであると認識しておりますので、この点は、そういった庁内での育成というところで、プラスに捉えていきたいと考えております。","voiceIndex":111,"id":"exchange-032"},{"speaker":"安藤委員","kind":"提案","question":"ですから人事異動の期間をどうするかというのは難しい問題かと思います。一つ、現場からの提案としましては、５年から１０年という、結構重い数字が出ておりますので、これも踏まえた上で考えていただきたいと思います。それが、いい意味での２３区の競争になるのではないかというか、子どもにとってもいい効果がありますし、そういう待遇面や配置の面で差をつけるということはできるのでしょうか。","respondent":"長谷川児童相談所移管担当課長","answer":"待遇の差です。児童福祉司の配置面での待遇の差ということでお答えしますと、これに関しては、所管の立場では、業務量と組織体制、業務フローの在り方などの側面から、相談・援助の円滑な実施と職員の負担軽減が図られるように検討します。","voiceIndex":113,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで、それをもとに調査に入るとあるので、結構、場合によっては緊急保護が必要なケースもあったりするので、やはり高い専門性が求められる業務なのかというところで、ここの部分だけ切り取って民間に委託というのは、果たして適切なのかという問題意識があります。ついでに最後の質問をしますが、場所についてなのですけれども、２８ページに施設について書いています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-034"},{"speaker":"安藤委員","kind":"意見","question":"結構、オブラートに包んだ意見だったので、正直、分かりづらい部分もあったのですが、目黒川があって、山手通り、幹線道路があって、その間に挟まれた場所で、思い詰めた子どもが来所するところで、それは飛び込みなどを言っているのかと私は思ったのですけれども、そういう事態にもつながりかねないという意味で、ちょっと心配だという……、まあ、心配だというレベルではない。","respondent":"あくつ委員長、長谷川児童相談所移管担当課長","answer":"所管にはお伝えしているというようなことは聞いていますけれども、お答えできる範囲でお答えいただければと思います。委託のメリットですが、専門性の高い業者に委託することで、日中、平日、職員が対応するのと同程度の対応が期待できるというところと、あと、職員の２４時間３６５日対応体制を考える上では、委託にすることで。","voiceIndex":117,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"里親になってもいいという方を増やしていくことについて、現段階で普及・啓発方法は、講演会などを開催していくということですが、それだけではなかなか里親に踏み切るのは難しいかというのも思うのですけれども、その辺の、全体、だからこの計画の実施計画になるのでしょうか、深めていくところの議論をどういうふうに進めていくのかということと、個人的には。","respondent":"長谷川児童相談所移管担当課長","answer":"いわゆる里親養育包括支援機関というフォスタリング機関のお話かと思いますが、里親の普及・啓発、あるいは里親のサポートといったところでの事業になりますので、これらに関しましては、他自治体の事例を参考にしながら。","voiceIndex":121,"id":"exchange-036"},{"speaker":"吉田委員","kind":"確認","question":"今後この計画を具体化していくために、それぞれ項目別にプロジェクトチームができるというようなイメージでいいのでしょうか。その中に、里親制度についての検討もしていくところができるとか、そのような考え、理解でいいのか、確認させてください。かなり、このフォスタリング機関の在り方というのが、里親が具体的に機能していく中では重要かと思っているのですが、その点について確認させてください。","respondent":"長谷川児童相談所移管担当課長","answer":"２点ご質問を頂きまして、１点目がプロジェクトチームの分科会の内容になりますが、委員ご指摘のとおり、まずは項目ごとに細分化しまして、それぞれの分野で、児童相談所移管担当と子ども家庭支援センターとで中身の検討をしてまいりますので、里親制度であれば。","voiceIndex":123,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひその辺について、今後も区議会へご報告いただきながら、議会としても一緒に考えていけたらと思います。取りあえず、今は、この計画に沿ってしっかりやっていただきたいという意見を申し上げて、以上としておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-038"},{"speaker":"つる委員","kind":"確認","question":"区が令和６年１０月に、晴れてという表現ではないですけれども、児童相談所のオープンとなったら、今現在ある「１８９」を区内からかけると、「最寄りの」となっていますから、品川区の児童相談所につながるという認識でいるのですけれども、まずここの確認だけ教えてください。","respondent":"長谷川児童相談所移管担当課長","answer":"通告窓口に関するお問合せです。児童相談所虐待対応ダイヤル「１８９」に関しましては、近くの児童相談所につながるダイヤルとして国が周知しているため、児童相談所に接続するのが適切と考えているところです。","voiceIndex":127,"id":"exchange-039"},{"speaker":"つる委員","kind":"質問・要望","question":"「１８９」、３つの数字だから。ただ、そこになるまでの時間がかかっていますよということで、平成３０年に質問もさせていただいたのですけれども、これは無料化したほうがいいのではないですか。だけど、今言ったように、品川区が開設すれば、最寄りの児童相談所として、「１８９」が品川区につながるので、最初に確認させていただいたのと、都のほうの施設のどちらにつながるのだろうということ。","respondent":"長谷川児童相談所移管担当課長","answer":"委員ご紹介のしながわ見守りホットラインと、それから「１８９」、それからＳＮＳといった他ツールとの併用に関しましては、まさにこれから、どこを通告の第１窓口にするかというものは、全体を通じて検討していく流れになっております。","voiceIndex":129,"id":"exchange-040"},{"speaker":"つる委員","kind":"提案","question":"分かりました。なので、そういう意味では、分かりやすい連絡・通告手段をしっかりと取っていただきたい。引き続き、しながわ見守りホットラインは児童だけではない部分があるので、所管に、この委員会を通じて、無料化について改めて、そういう提案を求めたということも含めて、これは所管でしっかりと連携して、そこに対してどう対応が必要なのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":131,"id":"exchange-041"},{"speaker":"吉田委員","kind":"質問・要望","question":"２点伺います。もう一つが、本年１月１７日の文教委員会のその他で報告された、保育士の配置基準違反で補助金返還に至った認証保育所に対するその後の経緯について伺いたいと思います。内部通報の仕組みの構築というのもご答弁があったのですけれども、それが、委員会報告の後どういうふうに確立されたかの確認を、できていたら教えていただきたいと思います。","respondent":"あくつ委員長、中元保育支援課長、立木保育課長","answer":"教育委員会所管のところでも、その他でご質問いただいたのですが、今おっしゃられたように、御会派としての様々なお考えを今述べられたのですが。園から保護者の皆さんに対してもきちんと誠意ある説明がされ、また保育士の皆さんに対しても、事業者から、処遇等についてきちんと、本部から。東京都と、区でも指導・検査しておりますけれども、今回のケースに関しましては、品川区内にある事業者のみの指導・検査の書類等の検査だけですと。","voiceIndex":134,"id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり品川区の保育について、ずっと質の向上ということを求めてきたのですが、このたびの予算では、保育の質の向上についての政策で予算がついたということを大変評価しております。配置基準の補助金返還についても同様ですので、ぜひ今後こういうことがないように、品川区としても目を光らせていただきたいと思います。以上、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5062#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":41099,"voices":141}},{"id":"r04-20220418-5","meetingId":"r04-cm04","date":"2022年4月18日","dateIso":"2022-04-18","committee":"総務委員会","time":"午後 １時００分～午後 ２時５４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"ご説明ありがとうございました。同時の竣工を要望しますというのは、限りなく不可能に近いことなのかなとは思うのだけれども、内容としては、これからどんどん考えていく内容だという部分を踏まえたら、これは特段、答弁というよりも、今進行中ということを考えると、また継続していくほかないのかなと思うのですけれども、質問する内容というよりも、そのように考えるのですが、委員の皆さんはいかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"前に出されたときも、私たちとしては、ご存じのこととは思いますが、区庁舎の建て替え自身、十四、五年もつ区庁舎ですし、もともと建て替え自体に反対ですから、ましてやアリーナなどというのは、あるいはにぎわい施設などというのは税金の無駄遣いだということで、むしろ区民から求められているのは福祉施設、特養ホームであったり、その他の福祉施設であろうと思っていますから、この陳情に関しては反対。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-002"},{"speaker":"須貝委員","kind":"意見","question":"それが第１点と、第２点として、品川区役所、まして新庁舎ができるとなれば、ここを中心に品川区の福祉、産業、それから防災拠点、医療もそうかもしれませんが、ここを中核として区民を守っていくのだという、新しい庁舎を中心とした地域が品川区のシンボルとして存在することが私は必要だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"資料の中でも、陳情の中でも、本当だったら陳情者の方に直接伺いたいのですけれども、どういうアリーナを想像しているのか、プロが使う専用のアリーナなのか、それとも区民が使うアリーナなのかなど、結構壮大です。どこに質問とかも投げられない状況ですけれども、前回に引き続き、総務委員会だけでこれをというのは、私たちは議会としてよろしくないのではないかという意見を申し述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-004"},{"speaker":"小芝委員","kind":"意見","question":"私としては継続という判断なのですが、というのも、その時々の状況を見なくてはいけないというのもありますし、今現在、先ほど課長からの説明でもありましたが、まちづくりの進捗を見ながら検討していきたいということですので、もちろん、区内在住の方も区外の方も大井町に来ていただく、にぎわいを活性化することで、まちの経済の活性化にもつながってくると思いますけれども、それを今。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-005"},{"speaker":"大倉委員","kind":"意見","question":"今のご説明にもあるように、にぎわい施設等、ここをどのように活用していくかというのが、これから検討されていくというところで、アリーナ施設を否定するものでもないかなと思いますので、品川区がよりにぎわいを持って、地域に親しまれるような場所になっていくために、こういうのも含めて今後、様々検討していくということなので、継続して。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-006"},{"speaker":"たけうち副委員長","kind":"意見","question":"ただ、その中の一つとして、アリーナも排除はしないのですけれども、今の段階では時期尚早なので、もう少し様子を見たいというところで継続がいいかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-007"},{"speaker":"渡部委員","kind":"意見","question":"けれども、その状況が違うという中での発言のように、皆さんの意見をどう取ってもそう取れて、これがある程度固まってくるまで同じ立場でいくのかなという部分に関しては、僕は今、委員長がおっしゃったような形で、ただ、考え方が違う人がいるから、決を採っていただいていいのかなと考えます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すで、不採択です。そういうことも含めて、なぜこれだけ継続審査になるのか、また、障害者福祉施設を求めるものも、すごく具体的なものに踏み込んで、大きさとか、今の新庁舎計画から大分ずれてしまうような内容になっている中で、これを継続審査にしてしまった場合に、新庁舎計画基本構想などが進んでいる中で、それをまた覆す状況を生むのではないかということを大変懸念します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"６ページの平面図を見たときに、いつもの通りの質問になってしまうのですけれども、契約の中で園庭が人工芝に変わるのかという部分と、子どもたちの保育園で行う夏場のプール、水遊びの場所というのは、どこに確保されているのかということが気になったので、お知らせください。","respondent":"小林施設整備課長","answer":"２番目のプールですが、組立て式のプールを設置すると聞いてあります。使う場所につきましては、園庭の一部に設置するです。床暖房ですが、所管からは、乳児ほふく室、それから１歳児室等、小さな子どもが使う部屋に床暖房を設置する予定と聞いてあります。","voiceIndex":62,"id":"exchange-010"},{"speaker":"田中委員","kind":"確認","question":"園庭で組立てのプールをするのでしたら、結構幅が狭いのかな、広さがないのかなと思って、そういうときには屋上広場とかを活用して遊べるのかというところも気になったのと、先ほど監視カメラが屋上にもあるというお話、児童センターは屋上につけているというお話だったのですけれども、児童センター利用者しか屋上が使えないということではないですよねというところの確認をさせてください。","respondent":"小林施設整備課長","answer":"運営の件ですので、詳しいところは所管になるかと思いますが、園庭の一部を使用してプールを組み立てますので、必然的にプールを使う期間につきましては、一部狭くなると認識しています。","voiceIndex":64,"id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"床暖房設備ですけれども、区立保育園は全体的に、１歳児だったり乳児だったり、小さい子のところには床暖房が設置されていく方針なのかという部分をお知らせいただければ。どうでしょうか。","respondent":"小林施設整備課長","answer":"分かる範囲でのご回答になりますが、基本的には、昨年度完了しました南ゆたか保育園とかにつきましても、小さなお子さんが使う部屋については床暖房を設置していますので、今後その方針であると聞いております。","voiceIndex":66,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"ただ、今回、入札価格がこのように提示されて決まってきているということで、入札価格が出ているということは、それぞれのメーカー、それぞれの設備業者がきちんと見積りを出して、入札価格を出してきているわけですから、今後資材が上がりました、設備費が上がりましたということで、また値段の改定ということが起こり得る状況になってしまうのですかというのを質問したいのです。その辺を教えてください。","respondent":"東野経理課長","answer":"特に区だけではなく、国の動き、都の動きといったところが、価格に影響がある場合も想定されますので、区としても十分その辺を認識した上で注視していきたいと考えています。","voiceIndex":69,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"各メーカー、今回はこのように建築業者なども、あらかじめ手配、発注して、値段が上がる前に注文して、それを抑えようという工夫をして、みんな値上げを防いでいるのです。そういうことも建設業界に、今回は入札ですけれども、やってもらえるのか。上がったら上がったで、１割、２割、また価格が単品スライドで上がってしまうことになるのですか。どういうものなのですか、教えてください。","respondent":"東野経理課長","answer":"ただ、先ほどもお話ししましたとおり、今後の鋼材、また資材等の値上がりの状況などが、入札価格の中で賄えないという状況がございましたらば、ご相談いただいた上で、変更契約等も視野に入れて考える必要があると考えています。","voiceIndex":71,"id":"exchange-014"},{"speaker":"須貝委員","kind":"意見","question":"意見だけですが、経理課としても、単品スライドを含めて、値上がりしてしまうということを、入札価格が上がるということを、抑えるという工夫も私は必要ではないかと思うのです。上がったら上がったでいいですよというのではなくて、極力建設業界の業者と話をして、どうすればこの値段で極力抑えられるかという努力も、私はしてほしいと思います。これは意見だけ出します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-015"}]},{"id":"topic-02","title":"品川区西五反田三丁目付近再構築その３工事請負契約","agenda":"品川区西五反田三丁目付近再構築その３工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"確かに交通上、不便にされる時期もありますが、今後こういう排水能力、それから大雨等の場合、それから地震等があったときに、改修しているということは、区民の皆さんも安心されると思いますので、できる限り、品川区はそういう力もあるのでありがたいと思いますが、進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-016"}]},{"id":"topic-03","title":"品川区東五反田一丁目付近再構築工事請負契約","agenda":"品川区東五反田一丁目付近再構築工事請負契約","exchanges":[{"speaker":"たけうち副委員長","kind":"質問","question":"２から５番の事業者が辞退となっていまして、５番は積算価格が予定価格を超過したということで、２・３・４番は配置予定技術者が配置できなくなったと。それで、４番の日本ノーディッグテクノロジー株式会社というのは、さっきのほかの事業を取っていますけれども、ほかのところも考え方としては、民間・公共事業を問わずにいろいろお仕事をやっていく中で、足りなくなってしまったということですか。","respondent":"東野経理課長","answer":"申込み時には、監理技術者、主任技術者等の技術者を配置できる予定として、入札に参加いただいているかと思われますが、その後、入札の間までに、例えばほかの工事を受注されたとかということで、技術者の配置が困難になったということで聞いておりますので。","voiceIndex":85,"id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"分かる範囲でいいのですが、東五反田一丁目の工事の範囲は、結構細々とした道だったのではないかと思うのですが、工事の際は安全性の確保というか、その部分がもし分かれば、お知らせいただきたいと思うのですけれども、いかがでしょうか。","respondent":"東野経理課長","answer":"聞いている範囲ですが、例えば通行止め等の対策ですとか、場合によっては夜間工事の場合があると聞いてあります。近隣住民につきましては、お知らせ看板やビラなどを配布して、十分な周知を図っているというところまで聞いてあります。","voiceIndex":89,"id":"exchange-018"}]},{"id":"topic-04","title":"品川区総合実施計画の策定","agenda":"品川区総合実施計画の策定","exchanges":[{"speaker":"おくの委員","kind":"確認","question":"この総合実施計画は非常に大部なもので、ざっとしか読んでいないですが、読み通すのはなかなかしんどいものでした。これに掲げられている各事業は、全部で１１５事業ということですけれども、まず、各常任委員会で審議あるいは報告されるものなのでしょうか。それで、されるとしたら、各常任委員会での審議というのは、今後担保されていくのでしょうか。お願いいたします。","respondent":"佐藤（聡）計画担当課長","answer":"今回の実施計画につきましては、本総務委員会で報告するということになっておりまして、各委員会での報告、審議等は予定しておりません。","voiceIndex":96,"id":"exchange-019"},{"speaker":"おくの委員","kind":"質問","question":"それぞれ１１５事業の１事業１事業についても、各常任委員会への報告というのは一切なくなるということでしょうか。これからも一切報告されない、これで終わり、総務委員会で全部審議しろというのは、むしろ不可能ではないかと思うのですけれども、その点、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-020"},{"speaker":"おくの委員","kind":"質問","question":"よろしいですが、その上で、これは大きな話だから、ここで聞いていいのかなというつもりで聞くのですが、この内容に関して少しだけよろしいでしょうか。４６ページ、政策の柱５というところの、まちの魅力を活かした都市型観光の推進の一つで、４８ページからは外国人観光客への観光情報発信ということになっています。外国人観光客が対象となっている事業が４８ページに書いてあったりします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-021"},{"speaker":"おくの委員","kind":"質問","question":"あるいは、後のほうになると、１５０ページでは、地域特性を活かした計画的なまちづくりで、リニア中央新幹線や羽田空港アクセス線開業によるというものが出てくるわけです。その辺を考慮された実施計画になっているのか、意外と考慮されていないのではないかと思いましたので、そこが私は気になったので、伺ってみたいと思ったのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-022"},{"speaker":"おくの委員","kind":"質問","question":"もう一つ、類似の質問でどうかなと言われるかもしれませんが、１５６ページ、武蔵小山駅周辺地区の整備促進というのがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-023"},{"speaker":"おくの委員","kind":"質問","question":"小山三丁目第１・第２地区というのは、都市計画決定までなされました。８割以上の反対意見が出てきたし、今でも反対はかなり強いものがあります。そういうものも考慮して、武蔵小山駅東Ｃ地区というのをそのまま進めていいわけはないと私は思うのですけれども、そういうことも考慮された上で、この実施計画の事業というのは考えられているのでしょうか。その点をお伺いしたいです。","respondent":"佐藤（聡）計画担当課長","answer":"ただいまの再開発に関する部分ですけれども、実施計画自体が長期基本計画の実現に向けたロードマップのような形になりますので、例えば今おっしゃっていただいた小山三丁目、２つの地区につきましては、令和３年度末の都市計画決定を経て。","voiceIndex":113,"id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"実施計画の考え方を伺いたいのですけれども、策定の目的の中で、長期基本計画の実現に向けた具体的指針とあるのですが、実際に実施計画を読んでいったときに、具体が見えてこない。８０ページの区立児童相談所の開設・運営で、「子どもの最善の利益と権利擁護に資する相談、援助、一時保護等を一貫して支援するための施設を整備する」ですけれども、この「施設を整備する」はハードではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-025"},{"speaker":"田中委員","kind":"質問","question":"分かりました。では、９９ページの社会的自立に向けた青少年の体験・交流機会の充実については、現況が子ども・若者支援施設における相談・支援が２か所、これが目標値で３か所、８年後には１か所増えるという想定ですけれども、それはどの計画に乗って、なぜ１か所しか増えないのかという部分を伺いたいのと、どういう計画に照らしてこの数なのかという部分を知りたいです。それは駄目ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"了解しました。では、１１１ページの重症心身障害者通所施設の運営充実についても、令和４年度に２施設、令和５年度に１施設増えてから、令和１１年まで増えないというのは、新しい障害児者福祉計画との整合性がどうなっているのかという部分、これが反映されているのかというところと、あとはほかの計画との、根本となっている計画と実施計画の整合性の部分を伺っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-027"},{"speaker":"田中委員","kind":"確認","question":"まだよく分からないところが多々あるのですけれども、１個だけ確認させていただきたくて、今、個々の計画で策定中のものがあるではないですか。でも長期基本計画はできていて、その長期基本計画に沿った実施計画なので、策定中の計画は、前年度というか、前の計画が反映されているという考え方でいいですか。違いますか。策定中のものなのか、それとも前回の計画のものなのかというところを知りたいです。","respondent":"佐藤（聡）計画担当課長","answer":"個別の計画と実施計画の関係ということかと思いますけれども、これは整合性を取って計画するということになっておりまして、今後、個別の計画の中で決まるものについては、その方向性まで決めるとか、あるいは。","voiceIndex":129,"id":"exchange-028"},{"speaker":"渡部委員","kind":"質問・要望","question":"逆に言うと、それを出して、実際はこの百何十ページの冊子が出来上がっているわけで、それを全員にお渡しするというよりも、詳細版は品川区の図書館でも地域センターでも、どこかへ行けば、それが何百円なのか分からないですけれども、実費でご購入いただけますという形でご案内するのがいいと思うのですが、そもそも今回お出しいただいて、私たちは１部ずつもらったけれども、何部作られているのか。","respondent":"佐藤（聡）計画担当課長","answer":"もう一つは計画期間のところでして、今回、３年を計画期間としておりますので、基本的には３年後、続くような形で、第２次の実施計画を策定する予定です。概要版の使い方です。","voiceIndex":132,"id":"exchange-029"},{"speaker":"渡部委員","kind":"質問","question":"各センターへ置いておいて、取ってくださいではなくて、積極的に、これだけ計画があって、品川区はこのように進むのだというのがあるのであれば、もう少しそのような動きをしてもらえると、僕らがどうやったら若者が興味を持ってくれるかというので、議会報告会のところにもつながっていくのかなと非常に思いますので、今回は３,０００部で、増刷してでも、品川区は市民科という授業があるわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-030"},{"speaker":"田中委員","kind":"質問","question":"１点だけ、すみません。そことコロナの状況というのは重ならないではないですか。長期基本計画の改定があったからとか、そういうことだったら分かるのですけれども、コロナが理由となってしまうと、少し違うのかなというのと、時期がずれてしまうというのを思うのですけれども、そこのスケジュール感について、もう一度伺いたいです。","respondent":"佐藤（聡）計画担当課長","answer":"それに合わせて、実施計画を策定するという作業に入りましたので、令和２年中、あるいは令和３年からの計画ということで、実施計画を策定し始めたというところです。ちょうどそのときにコロナが発生したというところがありましたので、策定作業を一旦止めたです。","voiceIndex":138,"id":"exchange-031"},{"speaker":"田中委員","kind":"意見","question":"ごめんなさい、令和２年と言われると、ぱっと出てこなくて。２０２０年ですよね。そのときに実施計画の策定が始まるのは、もう遅いのではないかと思っているのです。前回の実施計画が２０１８年までの計画だったので、２０１９年の当初から計画が。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":140,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"これまでの中で、たしか社会情勢の変化の原因も、コロナが原因の社会情勢の変化という話だったと思うのですけれども、今説明された社会情勢の変化とは、どの部分を指しているのか。２０１８年に実施計画が終わるので、２０１７年には策定作業が始まるのかなと思ったのですけれども、そうではなく、何かの社会情勢の変化がそこであったため、２０１９年にずれ込んだという考え方ですか。","respondent":"佐藤（聡）計画担当課長","answer":"前回の長期基本計画は２０１８年までの計画になっておりまして、その後の計画について策定するというところで、それまでのところから社会経済状況が大分変わっているということがありまして、自然災害が非常に多くなったとか、ＩＣＴが非常に発達したとか。","voiceIndex":143,"id":"exchange-033"}]},{"id":"topic-05","title":"ふるさと納税（寄附金）に係る体験型返礼品の追加等","agenda":"ふるさと納税（寄附金）に係る体験型返礼品の追加等","exchanges":[{"speaker":"田中委員","kind":"質問","question":"返礼品項目の選定の仕方について伺いたいのですけれども、どういう選定がされて返礼品となるのか、区のほうから、例えば今回のような屋形船乗船体験をお願いできますかという呼びかけをするのか、それとも事業者のほうから、いかがですかという声が上がってくるのか、その中でどういう選定の下で返礼品となるのか、金額も決定していくのかという部分を伺いたいのですけれども、いかがでしょうか。","respondent":"提坂税務課長","answer":"物というよりも、どちらかというと、今回新規に追加する屋形船とか釣り船体験とか、既に導入しているシミュレーター体験とか、そういう体験型によって区内の魅力を発信するというスタンスで選定を進めているわけですけれども、区の他の所管課からいろいろ情報を収集して。","voiceIndex":150,"id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"区からの打診、担当課からの打診と共に、事業者からのアピールもあるということでした。これまで返礼品にはならなかったけれども、こういうのがあったというのが、区からと事業者からもあれば、教えていただきたいのですけれども、返礼品にならなかったものでどういったものがあったのか、お知らせください。","respondent":"提坂税務課長","answer":"残念ながら返礼品としては選定させていただかなかったものということで、細かい内容は失念した部分もありますけれども、地元の企業で珍しい寝具、布団とか毛布とか、そういうのを作っているという売り込みがあったのですが。","voiceIndex":152,"id":"exchange-035"}]},{"id":"topic-06","title":"ジュネーヴ市３０周年記念公式訪問団受入れの中止","agenda":"ジュネーヴ市３０周年記念公式訪問団受入れの中止","exchanges":[{"speaker":"田中委員","kind":"意見","question":"オンライン等を利用した交流について協議中ということで、昨年もされたというご説明があったと思うのですけれども、昨年どのような対象というか、どういう方がオンラインで交流したのか、子どもたちの交流があったのかという部分を知りたくて、お知らせいただけますか。","respondent":"古巻総務課長","answer":"時差の関係がございまして、直接オンラインで動画というか、画面での交流ができるのがニュージーランドくらいで、ほかは時差が大き過ぎる関係もございまして、電子メールでの文通を、中高生の方々でご希望いただいた方それぞれの、先方とこちらの文通というか。","voiceIndex":159,"id":"exchange-036"},{"speaker":"たけうち副委員長","kind":"質問","question":"１年延期して、それで結果的にまた１年ということで、今回はここに書いてあるとおり、延期ではなく中止ということですか。","respondent":"古巻総務課長","answer":"延期の線も考えなくはなかったのですが、ジュネーヴ市との交流事業につきましては、５年ごとにやっておりまして、前回の２５周年のときに、こちらからジュネーヴに行かせていただいたということですが、５年ごとということで、２回延期をすると。","voiceIndex":162,"id":"exchange-037"},{"speaker":"たけうち副委員長","kind":"質問","question":"そうすると、３０周年はこういう形で中止になって、次は３５周年ですか。そのときは、本来だとこちらから行くのだと思うのですけれども、向こうから来るのが今回中止になったということで、向こうから来てもらうのか、それともこちらから行くのか。まだ決まっていないですか。","respondent":"古巻総務課長","answer":"順番からいくと、３５周年はこちらから伺うという形なのですが、その辺りの細かいところは、またこれからの協議の中身によってということになると思います。","voiceIndex":164,"id":"exchange-038"},{"speaker":"たけうち副委員長","kind":"質問","question":"実は私も２５周年のときに、これは２０年ぶりだったらしいのですが、当時幹事長だったものですから、向こうに行かせていただいて、今の議長も、ほかに当時の自民党の幹事長、残念ながらお亡くなりになった大沢先生と一緒に行かせていただいて、向こうでも、堀越部長も一緒に行ったと思いますが、物すごい歓迎を受けまして、公の場所でそういう建物に品川区の旗も立てていただいて。","respondent":"古巻総務課長","answer":"情報として、例えば国際友好協会にはそういったお話があったということで、昨年度、たしかジュネーヴで何か周年行事というか、ジュネーヴで独自にお祝いをする催しがあったことは聞いていますが、特段、区として何か連携してということはしておりませんが。","voiceIndex":166,"id":"exchange-039"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"向こうは国連の欧州本部とか、またＷＨＯの本部とか、公の世界的な機関もいっぱいあって、そういうところも全部見学させていただいたりしたのですけれども、子どもたちもぜひ行ければ、そういうところはすごく勉強になると思うので、とにかく、コロナの問題があるので軽々には言えないですけれども、またさらに交流が深まっていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-040"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"お聞きしたいのですが、ウクライナの難民の方を日本でも受け入れていると思うのですが、品川区として、一自治体として、そういう動き、支援といいますか、そういうものはあるのですか。それとも、東京都止まりなのでしょうか。その辺、聞かれたときに我々も回答しなければいけないので、教えてください。","respondent":"古巻総務課長","answer":"とはいっても、いろいろそういったお声もありますので、一応、相談窓口ということではないのですが、ひとまず総務課の平和・国際担当にご連絡いただければ、情報を出させていただいたりとか、何かこういうことをやりたいというところを。","voiceIndex":175,"id":"exchange-041"},{"speaker":"田中委員","kind":"確認","question":"今、平和・国際担当ということでしたけれども、区民の方にお知らせするときには、そういうご相談があった場合には総合窓口の番号を教えれば、つなげていただけるのでしょうかという確認を。","respondent":"古巻総務課長","answer":"そのように調整がつくようにはしています。","voiceIndex":178,"id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2228#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":34600,"voices":181}},{"id":"r04-20220419-14","meetingId":"r04-cm04","date":"2022年4月19日","dateIso":"2022-04-19","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時４３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"新庁舎に関すること","agenda":"新庁舎に関すること","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"これは先ほど申し上げましたけれども、最初に造る段階でやらない限りは、もう後付けは絶対にできないので、この区民アンケートの段階の時にはそういうことは一切想定していなかったと思うのですが、その辺についてご検討とか何かはされたのでしょうか、教えてください。そして、そういうことも私は必要ではないかと思うのですが、もし何かご見解がありましたら教えてください。","respondent":"山下新庁舎整備課長","answer":"その後の状況からの今の検討状況ですけれども、広域からの区民の方の避難を受け入れるというところにつきましては、十分な検討を進めてまいりたいと思いますけれども、いわゆるミサイルが直撃するようなものへの安全性というのは、なかなか現実的には難しいというところでは、今。","voiceIndex":24,"id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"本当に私自身もこのようなことは想定もしていなかったので、今なぜこの場で申し上げなくてはいけないのかと私自身もびっくりしているくらいなのですが、やはり１００年この建物を守っていく。ですから、もしそういうことも組み込めるなら、ご検討いただけるなら、せっかく新しく造るなら、そういうことも設計の段階で考えるべきではないかという意見だけは、ここで私は言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私も策定委員会のほうにも出させていただいていて、先ほどご説明があったようなことで議論があったのですけれども、これもこの委員会で話すのがふさわしいのかどうかも分からないのですが、各委員から議会のあり方等について、やはりちらほらと質問が出たり、いわゆる民間の委員とか学識経験者、有識者の方からも、多目的利用とかどうなのですかというような質問を投げかけられたりもしましたが。","respondent":"山下新庁舎整備課長","answer":"次回第８回の委員会におきましては行政や議会の機能についてというところで、素案の検討の中で項目として含めておりまして、先般議会より頂戴しております議会権能に関する部分につきまして、資料のほうに明示をする形でご説明をしてまいりたいと考えていますので。","voiceIndex":27,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"確認","question":"前段の部分で、なぜこのような質問をしたかというと、いわゆる副委員長からそこについて、議会に対してこういう発言があってもいいのではないでしょうかというご発言があったものですから、我々も発言したいのはやまやまなのですけれども、いわゆる運営側からそういう意見が出たので、これはいつやるのかなというところで確認をさせていただいたのですが、次回やられるということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません、少しずれてしまう話になるかもしれないのですが、私は予算特別委員会の総括質疑とかでいろいろ思いは言って、議会改革推進会議のほうは座長もやったので、そこはそこであれなのですが、全体的な考え方を教えていただきたい。全体的というのは、区の今の、例えば今年度も普通に発注業務をしていくこと。だからそこら辺の今のお考えをお聞かせ願いたい。","respondent":"山下新庁舎整備課長","answer":"当課としましては、新庁舎整備に向けてまず基本構想、基本計画というところから、その次の段階として基本設計ということで、今委員からご指摘があったように年度内、もしくは年度末というところが一つのスケジュール感として持っているところではありますけれども。","voiceIndex":30,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"多分、設計は、決まってくる業者も大手になるのだと思います。そこら辺の情報だけは逐一、今度決まる業者だけではなくて、いろいろな情報を取っていただいて、行政側もいろいろな方ともお会いいただいて、そういう情報を多く取ってほしい。そういうことも含めて、ぜひそれは調査をかけるなり何なりして、そういうことをやっていただきたいというのは要望だけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-006"},{"speaker":"大倉委員","kind":"意見","question":"４ページで、バイク・自転車の利用が大井町駅を利用するようになるということだったのですが、やはり歩行者デッキができて、大井町駅から役所に行くのが多少便利になるというところで増えているということは分かるのですが、例えば実際に自転車・バイクを使っている人が電車に乗り換えるという感覚がなかなかあまり分からなくて、その辺でもしこの利用が変わっていくというところで。","respondent":"大友新庁舎建設担当課長","answer":"駐輪場、またバイクの駐車場のご質問かと思いますけれども、現状、庁舎のほうの駐車場は地下１階のほうに現有駐車場の台数並みに整備する計画で、考えているところです。","voiceIndex":33,"id":"exchange-007"},{"speaker":"大倉委員","kind":"質問・要望","question":"分かりました。駐輪場またバイク駐車場は、駐輪場は、今の話だとそれなりの台数を確保して狭くならないようにということで分かりました。その辺も勘案しながら、駐輪場やバイク駐車場、なかなかバイクは駅前に停めるところがないので、停めやすいと思えば余計に区役所のほうを利用する方も増えてくるのかなという思いがありますので、その辺は考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-008"},{"speaker":"のだて副委員長","kind":"質問","question":"この保健センターは４か所になるということなのかどうか、その辺りを伺いたいと思います。議論をさらに深めていくということを行っていく必要があると私も思うのですが、ワークショップとか分科会とか、そういったことで深めていく予定はあるのか、やるべきだと思うのですが、いかがでしょうか。","respondent":"山下新庁舎整備課長","answer":"最後にございましたワンストップサービス、窓口業務の委託というところを含めて今検討しているわけではございませんが、実際にそのワンストップという形で区民の利便性向上に努めてまいりたいと考えていますので。","voiceIndex":36,"id":"exchange-009"}]},{"id":"topic-02","title":"順序を入れ替えまして、はじめに、(2)品川区ＤＸ推進基本方針の策定","agenda":"順序を入れ替えまして、はじめに、(2)品川区ＤＸ推進基本方針の策定","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"ガバメント・クラウドの件で何らかのコストが、今はまだ国から示されないのでということで、それはそのとおりで、この間、以前の質問でも同じような議論をさせていただいたと思うのですが、一応、いわゆる業務委託からサービス利用みたいな形に変わっていくということが想定されるのですけれども、そういった時に何がメリットとなり、何がデメリットになるかというのは。","respondent":"宮澤情報推進課長","answer":"いわゆるサーバーの置かれるデータセンターというのは品川区専用というわけではなく、幾つかの自治体等も複数活用されるいわゆるＩＴ会社、ベンダーがそういった形で提供しているので、そういったところで保守というのも２４時間３６５日受けられるといったメリットもありますし。","voiceIndex":46,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"提案","question":"それは今確認をしたら、一番上のほうに持ってきていただいているみたいなのですが、そういうものをこれからＤＸ推進戦略会議の中でＰＤＣＡしていくと書いてあるのですけれども、そういうところは誰がチェックをしていくのだというところです。そういうところをしっかりと誰が見ていくのか、ＰＤＣＡしてくのかというところを確認させていただきたいと思います。","respondent":"宮澤情報推進課長","answer":"そういった視点を踏まえて、ＤＸ推進戦略会議のほうで全体的に横串を刺しながらそういった取組を進めていくというのを、意識改革を含めて取り組んでいく必要があるなと感じて、今後進めていく予定です。","voiceIndex":48,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"別に意図的にやったとかそう言うつもりはないです。いわゆるＤＸの話の上っ面の部分かもしれませんけれども、ＤＸをやるのであれば、その発信も区民に分かりやすいように、併せてしっかりやっていただきたい。そこのところは先ほどのご答弁ではそういうものもしっかりやっていくと受け止めましたが、一つの例ですけれども危惧をしたので、挙げさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-012"},{"speaker":"芹澤委員","kind":"質問・要望","question":"何点かお伺いしたいのですが、まずこの重点取組項目と、あと多分それぞれの細かい項目があって、会議体がＤＸ推進戦略会議というのとテーマ別連絡会議で、ＤＸ推進戦略会議に関しては重点取組項目をメインとして、副区長が先頭に立ってやっていただけるというような認識なのですが、まずその会議の振り分けがそういう認識でいいのか。","respondent":"宮澤情報推進課長、河西情報戦略担当課長","answer":"１つ目は、ＤＸ推進戦略会議です。取り扱うテーマは、重点取組項目に限らず分野別の取組項目についても取り扱っていく、全体のデジタル・トランスフォーメーションについて進めていく予定です。テーマ別連絡会議です。先ほど委員からご指摘のありました職員の育成方法、職員が育っていけばＤＸのほうも進むのではないかと、まさにそのとおりでして、品川区ＤＸ推進基本方針は、どちらかというと国の方針に従ってトップダウンでやるものになっています。","voiceIndex":51,"id":"exchange-013"},{"speaker":"芹澤委員","kind":"質問・要望","question":"そういう意味で言うと品川区のものは、せっかく作っていただいたのは非常にうれしいのですが、もう少し何かとがったところもあっていいのかなという思いもあって、現場の調整が全部終わった上で計画に盛り込むというよりは、これが必要だという少し厳しいところも含めて計画、もしくは計画に入れなくても、これから方向性として考える時に、ぜひ前向きに取り組んでいただきたいという要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-014"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですから、区の職員の方々というのは否応なしにこれからそちらに向いて進んでいかなければならないわけで、そこはしっかりやっていただきたい。そうすれば、そこで先ほどあくつ委員に示していただいたような端末ですとか、そのほかこの４年間でいろいろなものが出てくるかもしれない。０歳の子が生まれたらその時点で番号が付与されて、ではマイナンバーカードを作るかといったら作らないわけです。","respondent":"宮澤情報推進課長","answer":"取得に対する支援という形を現状も行ってありますけれども、そこにつきましては、所管する戸籍住民課はありますが、全庁的な取組、テーマ別の取組等で必要に応じて連携しながら進めていくという形です。","voiceIndex":55,"id":"exchange-015"},{"speaker":"渡部委員","kind":"確認","question":"このように国のほうのデジタル庁から始まって、デジタル化の取組というのを令和７年度末までにやるということが決まったわけですね。ただ、これは素人考えなのでわからないですが、やはりマイナンバーカードを持っている人と持っていない人の差はつくじゃないですか。この際、差はつけていいと思います。だってそうですよね。きっと本人確認をしなければいけなかったりもするわけだから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-016"},{"speaker":"西村委員","kind":"質問・要望","question":"少し細かいのですが、１点だけお伺いさせてください。親世代はデジタル世代なのに、なかなか現場はアナログだというような現状が結構長く続いていると思っていまして、こういった区民目線での区民のニーズに応えるということであれば、こういった細かいところまで各担当課の課題をどのように抽出しながら、どのように具体的に連携していくのかというイメージがおありでしたらお聞かせいただきたいと思います。","respondent":"宮澤情報推進課長","answer":"それが分野別で各現場でというところが、どこまで浸透していくかですけれども、ただ、取組として全体的な区の目標を立てて方針を進めていきますので、その中で取組を進めていくです。","voiceIndex":58,"id":"exchange-017"},{"speaker":"西村委員","kind":"質問・要望","question":"例えば学校でお話しさせていただいたのですが、どういったところが課題なのかという区民の方々の声を抽出することにぜひとも力を入れていただきたいと思っておりまして、実際に今、遅刻・欠席連絡がオンラインで可能になっていて、まずはファーストアクションで把握できて、その後子どもに向き合える時間が生まれるというふうに、学校現場の先生方も大変便利になったというお声を聞いております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ伺いたいのですが、これを進めていく上で、もう今年度から始めるのでしょうが、未来型オフィスを模索しながら経理課はやっていくと言っていたから始まっているのだろうけれども、そうすると、会議室とかいろいろなことも踏まえながらやっていくとなると、ある企業を見に行った時は、全員共通のスマホを持って、もうそれでいろいろすべて対応するというぐらいまでやっていたけれども。","respondent":"宮澤情報推進課長","answer":"今回、基本方針の中にも盛り込ませていただきましたが、ＤＸを推進していくそれぞれの取組の成果というのは、新庁舎のほうに成果をつなげていけるように進めていきたいと考えています。","voiceIndex":61,"id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問","question":"ということは、新庁舎（建設工事）は令和７年だから、要は令和８年になるということだろうと思っているのだろうけれども、新庁舎に移転する時には、それがもうここで言う１００％も大分あるわけだから、職員の意識も変わって、その時には新庁舎計画も、会議室のあり方から何からそういうのも全部大分変ってくるのだろうから、それに見合った形で。","respondent":"宮澤情報推進課長","answer":"取組は令和７年までＤＸを進めてまいります。その認識で合っているところです。","voiceIndex":63,"id":"exchange-020"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"確認させていただきたいのですが、Ａ３判資料の２ページ目で重点取組項目のところに、行政手続きオンライン化については最終的には１,０００手続をやっていきたいということで、ＲＰＡの活用のほうは２７業務やっていきたいということで書かれているのですけれども、この手続きというのが業務とは違うということですか。この違いが何か、伺いたいと思います。","respondent":"宮澤情報推進課長","answer":"デジタル技術の進展等を踏まえまして、行政の施策にデータというのを活かしていくというのが１点と、あともう一つは、例えば区民の皆様にオープンデータという形でデータを公開していくという２側面がありますが、そういった形でデータの利活用につきましても推進していくです。","voiceIndex":65,"id":"exchange-021"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"そうすると、手続きというのは、例えば住民票を取る、その区民が１回行うのが１手続ということになるのか、それとも住民票を申請するという業務が一つの手続きということになるのかというところがちょっと分からなかったので、そこを確認させていただきたいと思います。そうした膨大な個人情報が行政の中にはため込まれていると思うのです。","respondent":"宮澤情報推進課長","answer":"２点目のデータ利活用の部分ですけれども、データ利活用は個人情報を活用するわけではなくて、いわゆる統計データであったり、そういった情報、いわゆるデータという形のものを活用するものです。","voiceIndex":67,"id":"exchange-022"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"その方向性について伺いたいと思います。標準化・共通化については、工程表の８ページにおきまして、「業務をシステムに適合させていく」と書かれているのですけれども、これがどういうことなのか、伺います。今、区が独自でやっている事業とか、あるいは標準業務でも拡大してやっている部分とかがあると思うのですけれども、そうした部分は狭めないようにしていただきたいと思うのですが、いかがでしょうか。","respondent":"宮澤情報推進課長","answer":"１点目の、デジタル化を進める際の効率化等々を図ると、生産性の向上を含めて目的のところで述べさせていただきましたけれども、得られる効果というのは、さらなる区民サービスの向上のほうに振り向けていくという考えです。","voiceIndex":69,"id":"exchange-023"}]},{"id":"topic-03","title":"東大井三丁目における都有地（都営元芝アパート跡地）を活用した特別養護老人ホーム等の整備","agenda":"東大井三丁目における都有地（都営元芝アパート跡地）を活用した特別養護老人ホーム等の整備","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"区もこれは把握をしているということは伺っているのですけれども、今回事業主体というか、その土地の所有者が東京都というところで、これはぜひそういったご意見を、特別養護老人ホームで決め打ちというか、目的がもう決まっているのですが、ゆうゆうプラザは難しいのだと思うのですが、そういうものを区の意向として、住民の意向として、地域の意向として伝えていただきたいという要望を受けているのですが。","respondent":"佐藤企画調整課長","answer":"これまでの事例なのですが、申し訳ないですが、そこまでは今手元にないところですが、都のインフラ整備事業で、地元の自治体の要望を聞きながら都が事業を進めているという認識です。","voiceIndex":75,"id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど区の意向は伝えるということだったのですが、これは特別養護老人ホームだから、所管である福祉部門から伝える、福祉計画課なのかどこか分かりませんが、そちらから伝えるということなのか、それとも今まである程度交渉をしてこられたと思うのですけれども、企画調整課からされるのか、その点について確認させていただきたいと思います。","respondent":"佐藤企画調整課長","answer":"本件に関する所管というご質問だと思います。企画調整課といたしましては、都有地等の利用の用途を所管と調整して決めるところまでで、その先は所管のほうが豊富なノウハウがありますので、所管のほうで対応するというような切り分けをしております。","voiceIndex":77,"id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"提案","question":"私は厚生委員だから、昨日まさにこれをやっていたのだけれども、少し微妙な今の発言なので、確認だけさせてください。それからショートステイを１割併設してくださいねと、自由に提案してくださいねということですよね。今の言うというのはいいのだけれども、それほど時間がないと思うというのが１つ。それから、今言った区で選定をするわけだから、それはしっかり選定をして意見を付けてほしいということ。","respondent":"佐藤企画調整課長","answer":"この事業ですが、この事業につきましては、都有地活用による地域の福祉インフラ整備事業実施要綱というもので東京都が定めて行うものです。この要綱を使って行う事業に関しましては、核となる事業、例えば今回で言えば特別養護老人ホームは必須というところ。","voiceIndex":79,"id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"まさに厚生委員である石田秀男委員のほうからも、補足というか、確認していただきましたけれども、いわゆるそういう公募が出てきてから、当然建前上はそういう話になっているということなのですけれども、当然今までのやり取りの中でも、そういう地域要望というのは都のほうには伝わっていると思いますし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"私もあまりこの内容について承知していないので、少しお聞かせ願いたいのですが。東京都のほうで公募をするという話ですが、これは民間事業者だけしか入れないのですか。例えば品川区がここに応募するということはないのですか。すみません、もし途中で説明があったら私が聞いていなかったと思うのですが、お聞かせください。","respondent":"佐藤企画調整課長","answer":"こちらのほうは都が主体となって民間事業者を公募して、よりよい事業者が定期借地権で長期間の事業を運営するというものなので、公設というのは前提にしておりません。公設というのは、品川区が手を挙げて、事業を運営するというような前提になっていないということです。","voiceIndex":82,"id":"exchange-028"},{"speaker":"須貝委員","kind":"意見","question":"それが何で区が入れないかというのは解せないのですが、やはり品川区としてはそれぞれの様々なノウハウも持っていて、様々な特別養護老人ホームもあちこちに造って、経験も本当に多様な実績もある中で、なぜ公が外されるのか。私は国民、都民、区民のことを考えたらやはり平等に公募すべきだと思うのですが、やはりそこはそういう約束事で駄目ということなのですね。こういうことになってしまうのですね。","respondent":"佐藤企画調整課長","answer":"そういった考え方になっているのだと考えております。","voiceIndex":84,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6126#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":33817,"voices":96}},{"id":"r04-20220420-19","meetingId":"r04-cm04","date":"2022年4月20日","dateIso":"2022-04-20","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時１８分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"国語的な問題ですけれども、避難計画に関することの裏のページの「防災訓練、備蓄について」というところの（６）ですが、「訓練場所や一時集合場所となる防災公園がない町会の解消に努められたい」ということで書かれているのですが、これは町会の解消という感じに受け取られるような文章になっていないかと思いましたので、「公園がない町会に対する」か、また「対して」か。","respondent":"安藤委員長","answer":"誤解のあるような表現を避けたいというご意見だと思いますので、軽微な修正かと思うのですけれども、正式には正副で後日調整して、ご主旨を活かせるように修正したいと思います。","voiceIndex":23,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これも軽微な国語的なことですけれども、（１）の区民のごみの分別やリサイクルの意識の向上についてのその後に「具体的な行動を起こしていただけるような啓発」と書かれているのですが、「起こしていただける」という表現よりも「具体的な行動につながるような啓発を」というほうが、こういうところで書かれるのは適切かなという思いをしているのですけれども、ご検討いただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-002"}]},{"id":"topic-02","title":"エコルとごし開設およびオープニング式典・イベントの開催","agenda":"エコルとごし開設およびオープニング式典・イベントの開催","exchanges":[{"speaker":"湯澤委員","kind":"質問・要望","question":"こちらのマシンガンズの滝沢さん。この方メディアなどで今かなり取り沙汰されているお笑い芸人であり、ごみ評論家というのですか、そういうので、すごくこの方が来るのも楽しみだなと思っているのですけれども、４月１日から１８日までということで抽せんをして８０名ということで締め切っていると思うのですが、大体今どのぐらい応募があったのかということを、まず分かれば教えていただきたい。","respondent":"河内環境課長","answer":"エコルとごしにつきましては、３７台分置くスペースがございまして、そういったところを活用しながら、近隣の方にご迷惑のないような運営に努めてまいりたいというふうに考えているところです。","voiceIndex":50,"id":"exchange-003"},{"speaker":"湯澤委員","kind":"意見","question":"駐輪場に関してはそういう対応をしていただいているということで、お越しいただいた方が「せっかく来たのに止めるところがなくて困ったよ」とかそういうことがないように、誘導員ももしかしたら１日のイベントだけかもしれませんけれども、万が一３７台を超えるようなことがありそうな雰囲気であったら、戸越公園だとか、文庫の森とかそちらのほうにも行けるようにとか、そういうような対策を取られたり。","respondent":"河内環境課長","answer":"こちらの抽せんで漏れた方などにつきましては、残念ながら、今回版権の関係で動画配信はというところではあるのですが、一方で５月３日にもまた元村有希子様をお呼びしました、記念講演も予定しておりまして、その他のいろんな講演を持ち。","voiceIndex":52,"id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。いよいよ待望のエコルとごしのオープンということで、私も楽しみにしています。２点、お伺いいたします。そもそも打診はしましたけれども、動画配信は駄目ですよというような回答であったのか、お知らせいただきたいと思います。それと、フードドライブについてお伺いいたします。そこら辺の取組みをお知らせいただきたいと思います。","respondent":"河内環境課長","answer":"２階３階ともなるとなかなか上がらない方もいらっしゃるので、１階におきまして、フードドライブをやっていることを皆さんにまずご認識いただけるような工夫をしながら進めてまいりたいというふうに考えているところです。","voiceIndex":55,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"ありがとうございました。要望します。フードドライブにつきましては、皆様が行きやすい場所に設置されているですので、引き続きどうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問","question":"このオープニングは、まず必要なこと、広く知っていただく。これは今日、オープニングの報告だと思うのですが、まず今年度、例えば５月にオープンして夏休みとか、あるいは秋の季節感がいいときとか、どこかで節々に盛り上げがあっていいと思うのです。１年目があれば２年目に下がっていくのではなくて、来場者にしても高水準を維持するとか、緩やかに分析しながら。この２点教えてください。","respondent":"河内環境課長","answer":"２点頂きまして、まず１点目のオープニング以降の見通しです。５月につきましては、まずはこのオープニングを打ちまして、その後、特にお子さんをターゲットにしていることもありますので、夏休みの講座なども力を入れてまいりたいというところで計画しています。","voiceIndex":59,"id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"これは理想というか、目標値はどんどん検証しながら高めていっていいと思っています。例えば、団体というよりは、最寄り駅から、あるいは戸越銀座を歩いたり最寄り駅の戸越公園から歩いた人が、お店の人に「エコルとごしどこですか」と聞いたときに、この応対がすごいポイントだと思うのです。その辺のところをどう取り組まれて、あるいは今後どのような設定をされているか教えてください。","respondent":"河内環境課長","answer":"本日ご視察いただく中で、コミュニティラウンジにつきましては、戸越地区の見どころマップというものがございまして、その際、近隣の商店街もそこに記述があるのですが、そういったところの打合せの中で盛り上げていきたい旨もお伝えしている中で、さらに今後のイベントや。","voiceIndex":61,"id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問","question":"いろいろな方法が、多分手探りであったり、これからどんどんついていく。というのは、この施設を支える人。これは職員だけではなくて地域の方のサポート体制というのですかね。ましてやこれだけ区の目玉施設なので、ここを拠点にすることが全体の底上げになるとか、少し今後幅を持って、２年目も３年目も次々企画が打ち出されるような、そんな形であってほしいと思うのですが、抱負だけお聞かせください。","respondent":"河内環境課長","answer":"皆様に一度おいでいただいた後、またさらに足を運んでいただくことも踏まえまして、こういった認証だとかポイント制度とか、そういった工夫を重ねながらやりたいということで、指定管理者とも今話合いを続けているところです。そのような形で進めたいと考えています。","voiceIndex":63,"id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"今渡辺委員から目標値という話が出たのですが、１個だけお聞きしたいのが、このエコルとごしのＬＩＮＥの友達というものが、裏にＱＲコードがあるのですけれども、これは今現在人数が７０人。友達を大体どれぐらいつくるかとか、区としての目標値があれば教えてください。","respondent":"河内環境課長","answer":"友達の目標値ですが、まだ関わる団体が様々ありますので、個別個別でいろいろ考えていきたいと思っているのですが、全体的には年間で３万人と言っていますけれども、でもそのほかの地域の関連の方とか、そういった団体のつながりの中につきましては。","voiceIndex":66,"id":"exchange-010"},{"speaker":"松澤委員","kind":"意見","question":"品川区も登録は３万人なのですよね。だから、まず７０人がどれだけ広がったとか、多分このＬＩＮＥでやり取りとか情報が来ると思うので、環境課の環境をやってくのだというその心意気をしっかり数字に表していただければと思っています。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-011"}]},{"id":"topic-03","title":"令和４年度品川区・第二消防方面合同水防訓練および自主避難施設開設訓練の実施","agenda":"令和４年度品川区・第二消防方面合同水防訓練および自主避難施設開設訓練の実施","exchanges":[{"speaker":"こんの委員","kind":"質問","question":"何か特別に参考するものがあって、この４校なのか。実際災害時に２０名もつくほど職員がいらっしゃるのでしょうかというそこら辺のところ。いわゆる本当の災害のときに、運営をする職員の数と、訓練のためだけの人数だったり体制ではなく、想定される被害に対応する方たちが訓練したほうがいいなと思うのですが、その辺のこの人数の配置だとか訓練の内容だとか、もう少し詳しく教えていただきますでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"去年も４校やっておりまして、そこは除外した残りの学校から選んだところです。２点目ですけれども、委員のおっしゃるとおり、８０名。１校につき２０名、区の職員が開設訓練のほうを実施します。実は２０名の中に視察者も入ってあります。","voiceIndex":73,"id":"exchange-012"},{"speaker":"こんの委員","kind":"確認","question":"それで、自主避難施設ですから、この水防訓練と関連して、いわゆる水害に関するそうしたところで開設する避難所ですので、職員の方が開設するというのは理解しているところですが、そうすると、今のご説明でいくと、去年やられた検証の下、１０名が妥当ではないかというところで、大体この単純計算で当日２０名ということは、あとの１０名は視察も兼ねてという形で。","respondent":"五十嵐災害対策担当課長","answer":"自主避難施設からいよいよ生活再建に移るとき、今度は区民避難所に移行していくというフェーズになってくるのですけれども、そこの訓練が現在まだできていません。今後その辺については実施していきたいというふうに考えておりますので、よろしくお願いします。","voiceIndex":75,"id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6612#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":16206,"voices":81}},{"id":"r04-20220428-10","meetingId":"r04-cm04","date":"2022年4月28日","dateIso":"2022-04-28","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"役職改選","agenda":"役職改選","exchanges":[{"speaker":"高橋（伸）委員","kind":"意見","question":"ただいま局長からご説明があったとおり、改選についてということなのですけれども、私ども自民・無所属・子ども未来会派におきましては、この議員構成について、今、議論、そして、ご意見等々をいただいているところです。それによりまして、まだ議論途中の段階なので、取りあえず今そういった、私の会派の中では、報告ということで発言をさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5458#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":3426,"voices":21}},{"id":"r04-20220513-10","meetingId":"r04-cm05","date":"2022年5月13日","dateIso":"2022-05-13","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5460#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":10724,"voices":61}},{"id":"r04-20220516-6","meetingId":"r04-cm05","date":"2022年5月16日","dateIso":"2022-05-16","committee":"区民委員会","time":"午後 １時００分～午後 ２時３４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和４年度中小企業支援策","agenda":"令和４年度中小企業支援策","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれご説明ありがとうございました。取り分け飲食店の方に話を伺うと、ラーメン屋ですけれども、製麺もそうだし、サラダ油もそうだし、とにかくあらゆるものの材料の卸価格が上がってくる。質問ですけれども、まずそういう実態を区として緊急に把握をしていただきたいということと、それに見合った支援策を講じていただきたいと思うのですけれども、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"今回、コロナで、ずっとこの間、痛んできたところに加えて、委員おっしゃるとおり、円安ができていったりとか、また、ウクライナの侵攻だとかで、いろいろなものが物価高、企業物価指数も、今日、発表がありましたけれども、１０％ぐらい、前年度比ですけれども。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後にもう１点、手続の支援なのですけれども、この間、中小企業センターで様々、手続に関わる支援はされていると思いますけれども、やはり飲食店であれ、クリーニング屋であれ、個人店であれ、規模が小さくなればなるほど、本業の仕事が終わった後に様々な事務手続をする、それも含めて仕事ですから、皆さん、正確に真面目にしっかりとやるわけですけれども、どうしても様々な手続をするのが、腰が重いし。","respondent":"遠藤商業・ものづくり課長","answer":"それでも難しいという区民の方はいらっしゃいますので、そういうときにつきましては、私ども、ビジネス・カタリストの制度だとか、そういう部分をつくりまして、ご相談いただければ、今どこが止まっている状態だとかというところで。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"意見","question":"午前中、早く来て仕込みをして、ランチして、片づけして、仕込みして、ディナーをやって、片づけしてから１日の会計を閉じて、それは仕事ですよ、仕事だから頑張るけれども、やっぱり本当に、あるメニューにつなげるということは、行政が、区として努力されていることは分かりますけれども、なかなかそこにつながっていくその時間も惜しいという実態も改めてお伝えしたいと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"横山委員","kind":"確認","question":"１の(1)中小企業の「事業継続」に向けた支援の中で、一番下の新型コロナウイルス感染症対応特別助成の販路拡大に取り組む経費の一部を助成しますというふうにあるかと思うのですけれども、パンフレットのほうの4)で、対象経費で広告費というふうにありますけれども、例えば、実際にお使いになられた企業から、アンケートなども区ではやっているのかというふうに思うのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"特にウェブ広告なども非常に取り組んでいただく方が多いので、中にはそういう電子化といいますか、いろいろなことでチャレンジされているのかなということを感じているところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"横山委員","kind":"確認","question":"アンケートは多分別のところと勘違いしていたのかと思います。確認していただいてありがとうございました。","respondent":"遠藤商業・ものづくり課長","answer":"個別支援となると、かなりの件数になるかと思いますので、今申しましたセミナーとかでいろいろな支援施設がありますので、そういうところで工夫しながら、新たに新型コロナウイルス感染症対応特別助成から得た利用者の学びなども、活かしていきたいというふうに考えてあります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。１点だけ確認します。この支援策は、やはり多くの方が知っていくということが大事だと思っていまして、たくさんの支援策があっても、知らない、使えないという方があってはいけないと思うのですが、先ほど、中小企業の方にこれをお配りいただいているということだったのですけれども、この支援策の周知の仕方について、もう少し詳しく教えていただきたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"それでもなかなか伝わらないという部分が、自分が関係ないとなかなか見ないのかなというところがありますので、そのほかの場面でも、いろいろな形で区民の方にこちらの支援策が届くよう、工夫して周知をしていきたいと考えております。","voiceIndex":17,"id":"exchange-006"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。知っている人は知っているのでしょうけれども、なかなか情報が届いていないという現状もありますので、一言こういうことにも使えるのですよということをお話を、声がけをしていただきながら、チラシ１枚でも渡していただけると違うのかなというふうに思うのですけれども、さらなる徹底した周知というところでの取組をちょっとお願いしたいのですが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"それでもなかなか届かないというところもあろうかと思いますので、今後もいろいろな形で使いながら、どういう方法がいいかということはいろいろとあろうかと思いますので、引き続き周知の方法につきましては、いろいろと工夫していきたいと考えております。","voiceIndex":19,"id":"exchange-007"}]},{"id":"topic-02","title":"エシカル消費イベントの開催","agenda":"エシカル消費イベントの開催","exchanges":[{"speaker":"西村委員","kind":"質問・要望","question":"単発イベントだけではなくて、せっかく商業・ものづくり課がやってくださるところもあって、今後、コミュニティとか、地域、商店の力を発揮できるような新たな取組もぜひご検討いただきたいなと思っていまして、この中にある女性起業家のコレクティブ・アクションは、多分武蔵小山にいらした方ではないかと思っていまして。","respondent":"遠藤商業・ものづくり課長","answer":"は今年度こちらでやってみまして、来年どうしようかという検討を進めるようと考えているところです。","voiceIndex":28,"id":"exchange-008"},{"speaker":"西村委員","kind":"質問","question":"よく分かりました。利用している８割が女性ということで、豆腐とか大豆の量り売りも、もともと日本にあるものですから、そういったことを実際に体験できるブースもあれば面白いなと思いますし、そういったエシカルを推進する、ケース持参で来店したらポイント配布とか、いろいろな取組が消費ということをメインに考えられるのではないかなと思いますので、期待をしております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-009"},{"speaker":"中塚委員","kind":"意見","question":"おっしゃるとおりだなと。例えば、視点として、このエシカル消費の普及に向けて、食べるという行為も、フードロスをどう商品化するかという工夫であったり、家庭でできるものであったり、また、農業としてつくる過程から、まず廃棄物となる物をどうしていくのかとか、やはりここの視点は、飲食もそうだし、農業、生産地もそうだし、どこまで広がっていけるのかということも１つ大事な視点かなと思うのです。","respondent":"遠藤商業・ものづくり課長","answer":"そういうものの普及啓発をまずしっかりさせていただきまして、その上で、逆に言えば、その後の展開といいますか、先ほども廃棄物はこうなるのだというところで、どうとでもつなげる、消費なので、いろいろなものにつなげられるということは非常に感じているところですので。","voiceIndex":31,"id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ご説明ありがとうございました。１点質問があるのですけれども、おもちゃの病院、午前１０時から正午までということで、先ほど課長からも好評だというご説明がありました。それで、壊れたおもちゃでも、手軽に直せるものと、やっぱりちょっと手間がかかるようなものがあるではないですか。その２時間の枠の中でやるわけだから、その辺のところはどういうふうになっているのか教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"一度センターでお預かりするのですけれども、やはり症状によって、すぐ直せないという部分もあるかと思います。いわゆる入院をしてもらいまして、こちらでお預かりして、できた段階でご案内して、こういうふうになりましたということで対応しています。","voiceIndex":34,"id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問","question":"もう１つ、ボランティア医師の方が直すということで、予算額で、ボランティアの謝礼として５万円計上されていますけれども、これは何名ぐらいのボランティアの方が具体的にいらっしゃるのですか。","respondent":"遠藤商業・ものづくり課長","answer":"登録いただいているボランティアの方は、今、８名おります。当日恐らく６人か７人ぐらいが参加いただけるというふうに、今のところ調整しています。","voiceIndex":38,"id":"exchange-012"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"今回、エコフェスティバルとは別にやるということなのですけれども、内容としては、環境課にも関わるような内容かと思うのですが、今回のこのエシカル消費イベントでの環境課の関わりというのは何かあるのか教えていただきたいのと、エシカル商品の販売も今回していただけるということで、特にフェアトレード商品、先ほど課長がおっしゃってくださった、どういう過程で物がつくられて。","respondent":"遠藤商業・ものづくり課長","answer":"それからもう１つは、いわゆるフェアトレードがどういうものかですけれども、こちらは、私どものほうでパネル設置をさせていただきたいと考えています。","voiceIndex":42,"id":"exchange-013"}]},{"id":"topic-03","title":"品川区立荏原平塚総合区民会館指定管理者候補者の公募","agenda":"品川区立荏原平塚総合区民会館指定管理者候補者の公募","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"もう１つは、選定委員会の設置ということですけれども、この間、福祉系の指定管理者公募については外部委員の採用という話を伺っているのですけれども、このスクエア荏原に至っては、まず、選定委員会の委員は誰かということと、この外部委員の採用というのは、どういうふうに考えられているのか、位置づけられているのか、その点もご説明いただきたいと思います。","respondent":"篠田文化観光課長","answer":"ですので、まだ最終的な形としては決定していないのですけれども、区の内部だけで済ますのでなく、外からの目も入れていくということは当然念頭に置いてありますので、その辺も踏まえた上で、今、検討しています。","voiceIndex":49,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"選定委員の設置のことですけれども、まだ確定していない、今、検討中ということですけれども、始まった当初から、随分、この選定委員というのは、区の部長と課長と、区の内部でやっていたものが、徐々に変わり始めているのかなというふうに思っているのですけれども、このスクエア荏原の業務についても、内部だけではなく、外部の視点も加えるとしたその理由、期待するものということでもいいのですけれども。","respondent":"篠田文化観光課長","answer":"外部委員の入れ方については、先ほど申し上げたとおり、検討中ではあるのですけれども、考え方として、１つは、施設管理などにつきましては、やはりその専門家というのは当然いらっしゃいますから、区の中の運営の視点ではなく。","voiceIndex":51,"id":"exchange-015"},{"speaker":"くにば委員","kind":"意見","question":"私は、令和２年度の総括シートを拝見しながらお話をしております。スクエア荏原に関して、令和元年度、令和２年度と、コロナの影響で非常に利用率が落ち込み、収支も悪化をしております。具体的に、令和元年度が８２.６％だったものが、令和２年度に６４.４％。こちらが令和３年度、共に収支がどのように改善されたのか、稼働率、稼働状況が現在どのようになっているか。はこの２点をお聞かせください。","respondent":"篠田文化観光課長","answer":"今お尋ねいただきました点につきましては、実は今、決算の整理中ですので、細かい数字は今まだこちらの手元には届いていないのですけれども、基本的には、かなり利用率等は回復しているということで、指定管理料として、当初、指定管理者に渡していた部分も。","voiceIndex":53,"id":"exchange-016"},{"speaker":"くにば委員","kind":"質問","question":"この次の指定管理者、第３期を選定するにおいて、やはりこの改善という部分、どのようにしたらスクエア荏原の運営をよりよいものにしていくか、そして、今の第２期までの運営に、さらにプラスアルファをして、どのような改善の視点であるとか、独自の独創的な工夫をしていける、そのような指定管理者を選定するということも大事な視点だと思うのですけれども、令和３年度において、改善が必要な事項。","respondent":"篠田文化観光課長","answer":"ですので、令和３年度の課題としては、いかに元に戻すかということでやってきたですけれども、一方で、まだ完全にコロナの影響から脱却できていませんから、様々な形で利用の制限等もありますので、そういったものが完全に外れていけば。","voiceIndex":55,"id":"exchange-017"},{"speaker":"くにば委員","kind":"提案","question":"このスクエア荏原に関して、実際に改善が必要とされた対応方針という中で記されている動画配信など、この部分に関して、今どの程度、実際に施設の設備が整いつつあるのか、さらにこの部分に関して、次の第３期の指定管理者に創意工夫をどのように求めていくのか、その２点、お聞かせください。","respondent":"篠田文化観光課長","answer":"事前にそういった公表をされる主催者の方との打合せをきちんとしていきながら、環境として新たに整備するものが必要なのかどうかというのは見極めていきたいというふうに考えているところではあります。","voiceIndex":57,"id":"exchange-018"},{"speaker":"くにば委員","kind":"質問・要望","question":"これで令和５年４月１日からの指定管理者候補者を公募するということで、引き続きお願いすることになるのかもしれませんけれども、私が１点やはり安定的な施設の運営というものも重要だと思いますけれども、この利用率の改善であったりとか、今後、魅力的な施設にするための創意工夫、この事業運営に関してプラスアルファの能力を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-019"}]},{"id":"topic-04","title":"品川歴史館の大規模改修に伴う休館","agenda":"品川歴史館の大規模改修に伴う休館","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"あれは残してほしい。あれはやっぱり大森貝塚は品川区ですから、私、小さい頃から貝塚を見ていましたけれども。でも、それもなくすというのだったら、残念だとしか言いようがないのですけれども、旧東海道のあれもすごくいいし、そのようなことを言ったら何も変わらなくなってしまうのですけれども、展示内容のリニューアル、貝塚がどうなるのか伺いたいのですけれども、いかがでしょうか。","respondent":"篠田文化観光課長","answer":"貝塚自体の展示につきましては、当初からずっとあるものですので、かなり古くなっているということもあって、新たなものに造り替えをしていくということで、当然、委員からご指摘のあったとおり、大森貝塚というのは、やはりどうしても品川の顔になっている部分ですので。","voiceIndex":64,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ確認で、外にある庭園、どれだけ文化財的に重要なものか、品川歴史館を造る過程において、どれだけ大事にしてきたかということは、もう皆さんもよくご存じだと思うのですけれども、今、ばらして組み直すということですけれども、宮大工というか、茶室の専門知識はないですけれども、専門的にばらして、専門的に組み立てるという、そういうことでいいのか。","respondent":"篠田文化観光課長","answer":"そういうことも含めて、１回、そのままでは造り直しができませんので、当初は、なかなか維持するのは難しいのではないかという意見もあったのですが、やはり価値を考えれば、引き続き後世に残していきたいということもあって、全てばらして、きちんと土台を造って組み直す。","voiceIndex":66,"id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"５番の事務室移転等について伺いたいのですけれども、まず初めに、今いる事務室の方々の人数です。区から何人、事務員が何人、あと学芸員が何人、具体的に教えてください。","respondent":"篠田文化観光課長","answer":"区の常勤の職員としましては、副館長と、それから事務員が２名という形ですので、合計で３名の職員がおります。それから、常勤の学芸員が１名いまして、それから会計年度の学芸員が３名いるという状況です。","voiceIndex":68,"id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"人数的には、多くもないけれども少なくもないと思うのですけれども、まず、特に学芸員の方たちの雇用は、約２年間閉じる中で守られるのかということが質問と、それと、区内各地での巡回展とか、各種講座等を行うとなっていますけれども、これは具体的にどういうふうにするのでしょうか。","respondent":"篠田文化観光課長","answer":"巡回展示等に関しては、現在、具体的に、どういった形で、どのタイミングでやろうかというのは整理中なのですけれども、前回のリニューアルのときにも３か所ぐらい回っているはずですので、そのことを踏まえまして、休館の間に、大体、区内の四、五か所ぐらい。","voiceIndex":70,"id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"しかし、品川の歴史というのは、当たり前ですけれども維持していかないといけないし、これは物すごく大事なことだと思うし、ぜひ副区長から、２年間閉めるということで、なおかつ、各地で巡回展とか、各種講座をしてくれると、そして学芸員はそのまま維持していただけるという思いがある中で、品川の歴史館および品川の歴史を守ると言ったらちょっと言い過ぎかもしれませんけれども。","respondent":"和氣副区長","answer":"一応、これに関しても私のほうにいろいろご相談があるので、いろいろと意見は言わせていただく立場でありまして、私なりの考えがありますので、少しは反映していただきたいというふうに思っているところです。","voiceIndex":72,"id":"exchange-024"},{"speaker":"くにば委員","kind":"質問","question":"品川歴史館においても、せっかくこのタイミングでリニューアルオープンをするのであれば、何かしらそのようなコンテンツを含めて、目玉となる、集客が魅力的になるような設備であるとか取組を実施してはいかがかなと思うのですけれども、その点、今、ちょうど副区長のほうからも、体験であるとか、わくわくといった部分で、何かその新たな取組というものを、私もぜひ期待をしているのですけれども。","respondent":"篠田文化観光課長","answer":"私どもでも、今までの歴史館のきちんと、いわゆる一般的な展示物をつくって、それを見ていただいてという形のものから、今回は、正直、ＶＲ等も検討したのですけれども、今の時点で、要は。","voiceIndex":76,"id":"exchange-025"},{"speaker":"くにば委員","kind":"質問・要望","question":"もちろん民間の施設、民間の博物館、美術館とは違い、やはり区営ならではというか、行政が実施している施設ならではということで、もちろん重厚なコンテンツというか、重みがある歴史館という、旧来ならではのスタイルももちろん非常に重要だと思いますけれども、ぜひとも２年後の春という大分先のことですので、さらに一歩踏み込んで、その点、いわゆるＸＲの活用、デジタル技術の活用に関して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-026"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"２点お伺いします。","respondent":"篠田文化観光課長","answer":"特に外装に関しましては、最終的な判断はもう少し先になるものですから、どの時点でどういう形で表示ができるかというのは、ちょっとまだ検討の余地があるのですけれども、できるだけ対外的にもＰＲになるような形でそういう表示ができればと考えていますので。","voiceIndex":79,"id":"exchange-027"},{"speaker":"横山委員","kind":"質問・要望","question":"２点お伺いいたします。２点目が、資料の保管についてなのですけれども、資料については、こみぷらのほうではなくて、例えば温度ですとか湿度管理のきちんとされているところに保管されるのかと思うのですけれども、この１年間の保管の状況について、どのように行われていくのかというところを確認させてください。","respondent":"篠田文化観光課長","answer":"もともと歴史館での講座というのは、中に講堂がございまして、そこで実施をしていくですけれども、今回、その講堂が使えないということがありますので、会場等の確保をしながら。","voiceIndex":82,"id":"exchange-028"}]},{"id":"topic-05","title":"大井ホッケー競技場再開業イベント","agenda":"大井ホッケー競技場再開業イベント","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"主催が東京都ということですけれども、開催場所、つまり、施設の名称が「大井ふ頭中央海浜公園大井ホッケー競技場」ということなのですけれども、この先もここがオリンピックの会場だったという名前だったり、見て分かるものだったり、そういうものはないのですか。","respondent":"辻スポーツ推進課長","answer":"品川区でも、中央公園のところに、聖火リレーのイベントをやりましたので、そういったものをつけたりですとか、ここの近くのこみゅにてぃぷらざでは、コロンビアの事前合宿をしていましたので、そういった銘板をつけたりというようなことはしておりますので。","voiceIndex":89,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2926#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":33587,"voices":98}},{"id":"r04-20220516-7","meetingId":"r04-cm05","date":"2022年5月16日","dateIso":"2022-05-16","committee":"厚生委員会","time":"午後 １時００分～午後 ３時１３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"小山台住宅等跡地複合施設整備","agenda":"小山台住宅等跡地複合施設整備","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"それで、この施設は複合施設ということで、大規模になってくるかと思うのですけれども、これは建物としては階高というのはどのぐらいなのかというのと、あと、区で建てて指定管理にしていくという考えでいるのかを教えてください。","respondent":"寺嶋福祉計画課長","answer":"３年前に行った説明会の資料では、３階建てから４階建てということになっていまして、今のところ、内容で見直しをしたのは、保育園から特別養護老人ホームを大規模にというところだけですので、今の段階では、そこまでの情報となっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"指定管理という形で考えているということです。これはそれぞれに管理運営されていくのか、それとも一体で考えているのか、その辺がもしあれば教えてください。","respondent":"寺嶋福祉計画課長","answer":"障害者のほうの施設につきましては、今のところ、まだ指定管理かどうかも含めて検討しているところなので、先ほどの答弁の補足としましては、特別養護老人ホームの部分については、今、指定管理を第一の案として考えているです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。用地取得がこれからだということですけれども、これは、国有地の取得には幾らぐらいかかるのでしたか。当初、説明があったのかもしれないのですけれども、改めて伺いたいのと、あと建設費の総額としては、まだ基本計画、基本設計というところもこれからというところで、でも今年の８月なので、その辺もおよそあれば教えていただきたい。","respondent":"寺嶋福祉計画課長","answer":"用地取得につきましては、これはまだ見込みということなので、既に取得した都有地につきましては、約１０億円ということで取得しております。今後、国有地につきましては、恐らく３０億円以上はかかるのかと試算しています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これから土地取得ということなのですけれども、これがスムーズにいったとして、見通しとして、いつ頃開設か、スムーズにいくとこれぐらいかというのがあれば教えていただきたいです。","respondent":"寺嶋福祉計画課長","answer":"全てが順調にいったらということで、全く不確定要素が多いのであれなのですけれども、恐らく令和８年、９年辺りぐらいでいけばいいかと考えてはいるところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、障害者施設のところも伺いたいのですけれども、生活介護が新規で追加されたということで、ここ（資料）に説明が書いてあるのですけれども、ほかにも要望の多い障害者施設というのは、グループホームなりがあると思うのですけれども、ここが生活介護になったというのは、経緯というのですか、そこを教えていただきたい。","respondent":"川崎障害者施策推進課長","answer":"今回、生活介護が追加になったという経緯ですけれども、こちら（資料）に書かれていますように、常時介護を要する方が増加しているという点はもちろんのこと、今回、解体工事が延期になる中で、改めて現場の声もお伺いしまして。","voiceIndex":13,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"現場の声というのは、今、運営している施設ということで、利用者団体とか、そういったところには、特に要望の聞き取りなどは、この小山台住宅等跡地複合施設についてのところでは特にされなかったということですか。","respondent":"川崎障害者施策推進課長","answer":"現場の声というのは、生活介護の事業者になります。","voiceIndex":15,"id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"東京都の住宅跡地と、峰友寮のところと、それから小山台住宅というものの、３か所の土地に分かれていると思うのですけれども、この３か所の土地というのはそれぞれ、事前にもうどこかの委員会で報告があったのかどうか分からないのですけれども、例えば東京都の住宅跡地には何を造って、峰友寮の跡には何を造ってみたいな、そういうふうに施設を。","respondent":"寺嶋福祉計画課長","answer":"３年前にやった、地域の説明会のときの資料ということになるのですけれども、いわゆる都有地のところが恐らく従来保育園であったという説明になっていたと思います。","voiceIndex":18,"id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、東京都の住宅跡地というところと峰友寮を合わせたところで高齢者施設ができると考えていいのでしょうか。障害者の２０名、２０名、２０名で、３つの機能が入った障害者施設ができるようになると思うのですけれども、そこのところは合わせて何平米ぐらいのところに造られることになるのか、その点も伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"都有地にあった住宅のほうは、たしか９棟あったはずなのですけれども、全て２階建てだったと聞いておりますので、やはり地元の方のお考えに配慮すると、その辺は１つの目安にはなってくるのではないかということで、今、基本計画（案）を進めているところです。","voiceIndex":20,"id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"障害者施設が建てられる土地の面積というのは何平米かというのは、分かったら教えていただきたいのと、それから先ほど、区立施設として建設して指定管理というのは特別養護老人ホームのことを指しているということで言われたのですけれども、障害者施設のほうは、区立施設として造って指定管理ということの方向ではないのか、障害者施設の運営と、公的な施設、公立であるのかどうなのかというところも。","respondent":"寺嶋福祉計画課長","answer":"運営につきまして、これは障害者施設も高齢者施設もそうなのですけれども、高齢者施設のほうで指定管理をといったのは、今の段階で考え得る方向性として、指定管理でいくのがいいのかというところで、検討案の候補にはなってはいるのですけれども。","voiceIndex":22,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"私は、こういう公有地を区が取得して建設するということなので、区立で指定管理者ということでいくのが当然のことなのかという思いがしていたのですけれども、そうではないやり方も今後検討していくという、そういうこともあり得るという。例えば障害者施設なども、区が土地を購入するけれども、民設で民営みたいなことの検討というのもあり得るということで、検討の中に入っていくということなのでしょうか。","respondent":"寺嶋福祉計画課長","answer":"ただし、こういう用地を購入するときには、一定程度、国に、例えば区立でやるのかとか、民間事業者を誘致するのかといったあたりは、用地取得のときには１つの大きなポイントになってくると思いますので、その辺りまでには区の方針を決めて。","voiceIndex":24,"id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは国有地・都有地を区が購入して、障害者施設・高齢者施設を建設していくということですので、ぜひ公立、区立で建設していただきたいということで、要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけお願いだけしておきます。やっと、私も一般質問等でしたので、ある程度あれですけれども、３年前に住民説明会をされて、大体こういう感じだ、今度は変更して、もう一回説明会をされるということでありますけれども、先ほど、２階、３階、５階という既存の建物があったわけでありますので、以前の説明は説明として、せっかくこういう計画をつくって、こういう方向でいこうと。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ですから、今２０名ですけれども、スペースの関係もあると思いますけれども、できるだけ、平米数、幅を広げるような形、あるいは相談体制等をきちんとしていただきたいというところなのですが、その辺りはいかがでしょうか。","respondent":"川崎障害者施策推進課長","answer":"今、委員がおっしゃったように、児童発達支援センターの件も、私どもでセンターとして療育拠点としての機能を有しておりますので、どのような形で支援体制の充実を図れるかということも含め、今後検討してまいります。","voiceIndex":30,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"特に近隣の方、３年前、陳情が出されて、委員会でも当然、審査をして、区の対応も確認しているわけですが、その後、参考までに、今回こういう形でまた改めてと、リセットという形ですので、その辺の近隣等のその後のご要望、今般の住民説明会、地域への説明に当たっての、区の考え方、姿勢を確認させていただきたいのが１つ。それから、児童発達支援センターについては、よろしくお願いしますということです。","respondent":"寺嶋福祉計画課長、松山障害者支援課長","answer":"区の姿勢ということですけれども、まずは３年前に説明会があったときのご意見、いろいろあると思うのですけれども、そういったお声も聞きながら、一方で区全体の行政需要としては。委員お尋ねの生活介護と就労継続支援Ｂ型施設の箇所数および考え方についてです。箇所数は、１０か所の生活介護のうち、就労継続支援Ｂ型施設を併設しているところは２か所です。障害児者総合支援施設と西大井福祉園の２か所です。","voiceIndex":33,"id":"exchange-014"},{"speaker":"せお委員","kind":"質問・要望","question":"２点お聞かせいただきたいのですけれども、今後の予定で、ちょっと細かい話になるのですけれども、令和４年８月以降に基本計画策定とあって、結構すぐだと思っているのですけれども、こちらを利用するかもしれない方々のご要望などを、この基本計画策定までに聞けるというか、お伝えする機会があるのかどうかということと、あと、今、種別で言うと、地域、防災、高齢、障害とあって。","respondent":"寺嶋福祉計画課長","answer":"８月以降に基本計画策定というのは、まず１つは、３年前に１度、もともとの案があって、それに対して今回、行政需要の見直しをかけたということで、変更がかかっているということなので、当然、地元の方にお話しするときは、もともとの計画が変わったということと。","voiceIndex":37,"id":"exchange-015"},{"speaker":"せお委員","kind":"質問・要望","question":"コンセプトに関しては、やはり、せっかく隣に東京都の林試の森公園がありまして、先ほど、緑というお話もあったのですけれども、そこの拡張した部分などと連携できる部分があるのではないかと思いましたので、ここは要望なのですけれども、ぜひ東京都と一緒に考えていただいて、連携して、林試の森公園も一緒にうまく活用できるような方向も入れていただきたいと、そちらは要望します。","respondent":"川崎障害者施策推進課長","answer":"先ほど委員におっしゃっていただいた、障害者の方がここを使うかもしれない、当事者の声を聞く機会ということですけれども、その辺りについては、今後どう機会を得て聞けるかどうかも含めて検討いたします。","voiceIndex":39,"id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"確認","question":"これはお願いしておきます。それから、これは解体工事が始まっていますよね。これは更地で引渡しを受けますよね。それで、こういうものは、いつもこういうものを引き渡してもらうときに、地中埋設物がないなどというのは、国側は「ないですよ」と言うのだろうけれども、その確認というのは、区だったら誰がやるのか。分からなければいいけれど。","respondent":"寺嶋福祉計画課長","answer":"ただ、期間が結構かかって、解体工事自体、かなりかかって、今、１年ぐらいかかっているのですけれども、その中には当然、土壌調査等々は含まれているということも聞いておりますので、その結果をきちんと説明を受けた上で購入するという段取りになるとは理解しております。","voiceIndex":43,"id":"exchange-017"}]},{"id":"topic-02","title":"認知症検診推進事業（もの忘れ検診）の実施","agenda":"認知症検診推進事業（もの忘れ検診）の実施","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"２の受診期間が、６月１日から８月３１日という、短い期間かと思ったのですけれども、何でこの期間なのかということ。これを見ると、表紙を開いた１ページ目の一番下に、早期発見・早期治療のために年に１回のもの忘れ検診を活用しましょうと書いてあるので、毎年この時期になれば受けられるというものになるのか、今後どういうふうに検診が行われていくのかというのを、ちょっと伺いたいのです。","respondent":"川原高齢者地域支援課長","answer":"受診期間につきましては、委員がおっしゃるとおり、今年度は６月１日から８月３１日までの３か月ということで、非常に短くなってありますのは理由がございまして、まず初年度は検証する期間であるということと、あとは実際に検査機関で受診していただいた患者様のデータを。","voiceIndex":49,"id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、９月から３月は、要は検討委員会を開いて検査結果を評価してというふうに、それで次年度の計画も検討していくということなのですけれども、検討委員会というのはどういうメンバーでされるのでしょうか。その次の丸のところの、「区より、受診者に向けて個別支援を実施」という記載なのですけれども、これは受診者に向けて区が個別に支援していくということでいいのかということを伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"アフターフォローの個別支援を実施というところにつきましては、検診を受けていただいて、その後の認知症と診断された方につきましては、個別の医療機関で引き続きケアをしていくことができるのですけれども、その後、１回目、検診を受けて要支援になったにもかかわらず。","voiceIndex":51,"id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"意見","question":"そうすると、検討委員会は荏原医師会から３名、品川区医師会から３名、そして事務局、そして品川区で、医療機関の先生方もと聞こえたのですけれども、そうすると、合計で何人ぐらいの検討委員会になるのか、聞かせてください。","respondent":"川原高齢者地域支援課長","answer":"現在のところでは、医師の方が６名、事務局が２名から３名、あと区の私ども職員が２名から３名の予定です。","voiceIndex":53,"id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。それで、今まで認知症対策というのは高齢者福祉課だったと思うのですけれども、今回、高齢者地域支援課に、認知症サポート係という形で移ったと思うのですけれども、何か理由があるのか。何でかなと素朴に思ったもので、伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"令和４年度に向けての組織改正の中で、理由は様々なのですけれども、１つはやはり、認知症に関しては予防という観点が非常に強いということから、そういった意味では、介護予防等をやっている高齢者地域支援課の業務とするということで、組織改正を行わせていただいたところです。","voiceIndex":55,"id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今の、高齢者福祉課から高齢者地域支援課に移った件なのですけれども、認知症サポート係の体制はどれぐらいでされているのかを伺いたいのと、これまで「品川“くるみ”認知症ガイド」など、いろいろつくられてきたのも高齢者福祉課で、それでそのときに、たしか認知症初期集中支援チームとか、そういう取組もされていたと思うのです。その辺の体制と現状と実績も併せて教えていただけたらと思います。","respondent":"寺嶋福祉計画課長、川原高齢者地域支援課長","answer":"職員、係長を含め、５名でやっていますけれども、人事異動もあるのでメンバーも異動はありますが、基本的には同じメンバーはそのままスライドして高齢者地域支援課に入っていて、それぞれの業務も、認知症初期集中支援チーム、それから。ご質問いただきました認知症初期集中支援チームにつきましては、一昨年度の実績として、１回、会議を開催しています。引き続き検討に当たっているところです。今年度も私どもの課で実施する予定になってあります。","voiceIndex":58,"id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"よく聞こえなかったので、そこをはっきりと、もう一回、申し訳ないのですけれどもお願いしたいのと、あと続けてなのですけれども、これはもの忘れ検診のご案内のところで、検診内容というのが、問診と認知機能検査とあるのですけれども、具体的に問診と認知機能検査というのは、どういう中身になっていくのか、検診の内容について具体的に教えていただきたいのと、検診費用というのは。","respondent":"川原高齢者地域支援課長","answer":"５,０００人を対象に郵送物を配らせていただいて、予算額の見込みというところをご質問いただいていたと思うのですけれども、受診率約７％を想定して、３８０人ほどの方に受診は頂ける見込みを考えてあります。検査方法につきましては３点です。","voiceIndex":61,"id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この中で、この１５か所というのは、先ほどいろいろとドクターも、認知症サポート医だったりもの忘れ相談医、認知症の専門医とか認定医とか、いろいろあると思うのですけれども、そういうところで、この検診をしていただく医療機関というのは、その中のドクターの資格というのですか、そういうものは、どういう方が、この１５か所のドクターなのかというのを教えていただきたいのと。","respondent":"川原高齢者地域支援課長","answer":"品川区には、令和４年２月現在で５４人、同じように研修を受けた認知症サポート医の先生がいらっしゃいますので、今年度は１５機関という形で、今、申し上げられることです。","voiceIndex":63,"id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"認知症はどういうものなのか、どう対応したらいいのか、区の早期発見・早期治療だったり対策が重要だということの啓発もすごく大事だと思うのですけれども、検診の大事さを分かってもらう取組についてはどう考えられているのかということを教えていただきたいのと、それからあと、高齢者クラブなどで認知症の学習会をしたいと思っているのだけれどというご相談を受けたりしたこともあったのです。","respondent":"川原高齢者地域支援課長","answer":"２点目の、高齢者クラブからのご要望があった件ですが、組織改正を経て、私どもの高齢者クラブの管轄の課に、認知症の一式の係が統合いたしましたので、これからどのような形で連携していくかというところは考えて、いいような形で実施していきたいとは考えてあります。","voiceIndex":65,"id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"本当に高齢者クラブの担当の高齢者地域支援課が認知症の担当になったというところでは、そういうふうに連携しながら進めていけるというところで、ぜひ期待したいと思います。センターという形になっているのは、どのような役割で、具体的にどういうことをされているのか、その点について教えていただけたらと思います。","respondent":"川原高齢者地域支援課長","answer":"副委員長ご指摘の荏原中延クリニックと荏原病院につきまして、地域連携型と地域拠点型の病院をそれぞれ挙げさせていただいているところではあるのですけれども、特別、病院に対して区が委託を図っているという形ではなくて。","voiceIndex":67,"id":"exchange-026"},{"speaker":"若林委員","kind":"質問・要望","question":"今回、５,０００通を郵送しているということなのですが、この５,０００人にはそういう方は入っていないということなのかという確認がもう一つと、認知症サポート医の先生方との議論の様子を聞きたいのですが、予防だからそうかとは思うのですけれども、何でしょう、認知症と診断するもしないも、お医者さんにかかるかどうかの違いだけであって、非常に、言葉遣いが適切かどうか、認知症というのは。","respondent":"川原高齢者地域支援課長","answer":"ご質問いただきました検査方法についての３点のご説明です。１点目が、アルファベットでＨＤＳ－Ｒという形で、長谷川式簡易知能評価スケールという内容で、長谷川先生という方が考案された簡易的な知能検査です。","voiceIndex":70,"id":"exchange-027"},{"speaker":"若林委員","kind":"確認","question":"「薬を使用した場合」について、こういう表現は、医師会の先生との議論は特になかったという、ご意見はなかったと。別に議論になっていいのだけれど、そういう感想を持ちましたので、もう一回それをお聞きします。あえて先生が、あなたは違いますと現場でするのか、そこを確認します。そうすると米印自体が、何か意味があるのかという議論にもなってしまうのですけれども。","respondent":"川原高齢者地域支援課長","answer":"説明の仕方が分かりづらくて申し訳ありませんでした。こちらのチラシは全て、医師会の先生方に監修していただいたものでございまして、確かに、薬という表記がどうなのかというところは、今後の検討委員会でも、ご意見があったということを上げさせていただきたいと思います。","voiceIndex":72,"id":"exchange-028"},{"speaker":"若林委員","kind":"意見","question":"こういうグラフは少し気をつけていただいたほうがいいかと。軽度・中等度・重度があって、薬を使用した場合は、中等度のちょっと上、みたいな。例といえば例なのですけれども、今はいつも、エビデンスがとか、根拠は何というご時世なのでという疑問です。米印の扱いについては、これはもう届けられているということなので、柔軟なというところで、今後、また表現等にご配慮いただければいいかと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"質問","question":"その辺りについて、区から、この辺りもお願いしますみたいな、地域的なバランスでしょうか、そういうものも当然にお話しされたと思うのですけれども、その辺りのことと、今回はこの１５か所で、医師会の先生方のお骨折りで実現するのですけれども、今後のことについてはどのようにお考えになっているでしょうか。","respondent":"川原高齢者地域支援課長","answer":"私どもも、当然、地区に、均等とはいかなくても、どこの方でも区民の方が受けられるようにということでお願いはしたところですけれども、最終的な調整で１５医療機関と、当初の予定より少し減ってしまったところですので、来年度以降につきましては、より。","voiceIndex":76,"id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"せっかく、例えばご家族の方やご本人が、では行こうというふうに、ご家族に説得していただいたときに、「ちょっと遠いね」みたいになってしまったときに機会を失うと思うので、せっかくよい施策ですので、多くの方がサービスを受けられるように、今後、医師会の方のご協力を何とか求めてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-031"}]},{"id":"topic-03","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"コロナウイルス、先週あたりには、東京都の新規感染者が２,０００人台になっていて、今のままですと、３,０００人、４,０００人ということで、また感染者数が増えてきていると思うのです。ですので、まだまだ感染者もこれから増えるのかという、今、そういう段階なので、ぜひ東京都に引き続き延長を求めていただきたいと思うのですけれども、いかがでしょうか。","respondent":"坂野保健予防課長","answer":"東京都の制度に再延長があるのか、ないのかということかと思うのですけれども、今のところ、まだ情報がないです。ご要望があったことはお伝えいたしたいとは思います。すみません。よろしくお願いします。","voiceIndex":89,"id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"お伝えいただきたいのと同時に、区として求めていただきたいと思うのですけれども、そういった考えはないということでしょうか。","respondent":"坂野保健予防課長","answer":"区として独自に延長をという趣旨でございましょうか。それは現在、考えているところではございません。","voiceIndex":91,"id":"exchange-033"},{"speaker":"若林委員","kind":"確認","question":"こことは違うのかもしれないのですが、日本に、ウクライナからの避難民の方が東京都の中にいらっしゃって、こういう方のワクチンはどういう考え方なのか、何か方針が出ているのか、これからどうするのか、全く情報がないか、それだけ確認を。","respondent":"坂野保健予防課長","answer":"ウクライナからの人ということなのですけれども、基本的に一般論で申し上げますと、日本の水際対策では、接種しているか、していないかで、隔離期間を変えているというのはございまして、具体的にウクライナから来た人に接種歴を確認して、どうこうしているかというのは。","voiceIndex":94,"id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"この品川区の感染状況というのが、１日どれぐらいの、百数十人というのが結構、過去、ＮＨＫのまとめ等で出ているのは見ているのですけれども、感染状況がどのような状況になっているのかと、これがまた、入院患者がこれだけ減ってきていないというのはどういう状況と捉えられているのか、その点についても伺いたいと思います。その辺の区の見解と品川区の感染状況について教えていただけたらと思います。","respondent":"坂野保健予防課長","answer":"多分、検査が必要な人が検査にアクセスできない状態、それは足りていない状態だと思いますが、今は検査が必要な人を全て受け入れていますので、そういう点においては、足りている。","voiceIndex":97,"id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう点では、やはり検査というのは本当に大事なことですので、予防という点からも、区は検査を延長してほしいということを、東京都に区として要請するという、そういう考え方はないということなのですけれども、私たちは検査の重要性ということをずっと訴え続けてきましたけれど、そういうところでは、区が、東京都が５月２２日で終了するということにならないようにということでは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-036"}]},{"id":"topic-04","title":"品川区新型コロナウイルスワクチン追加接種","agenda":"品川区新型コロナウイルスワクチン追加接種","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"ワクチン接種の接種率のところで、先ほどもワクチンを廃棄しなくてはいけないという説明もありましたけれども、全体的に３回目の接種が、６０歳以上の方でも２回目接種より低い接種率というところでは、これはなぜなのかというのは、区としてはどう考えられているのかというのをお聞きしたいのです。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"もともとの試算から言うと１.数％の低い数字ではあるのですが、その辺も誤差と考えることもできなくはないのと、あと、６か月経っていない方も一部いらっしゃいますので、その辺り、ある程度、もう少し数字は増えていくのではなかろうかとは考えているのですが。","voiceIndex":105,"id":"exchange-037"},{"speaker":"鈴木（博）委員長","kind":"質問","question":"ほかにご発言はありませんか。では私から少し質問。１つは、今度、ノババックスのヌバキソビッドというワクチンが始まるのですけれども、その対象というか、どういう方を対象にして、どういう形で製造するのでしょう。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"広報については、ホームページ、それから広報しながわを使ってやっていくことになりますが、基本的には６０歳未満の方で、もしかしたら若い方が食いつくのではないかとは考えておりますので、ＳＮＳ、ホームページ。","voiceIndex":107,"id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"いらっしゃったら、そういう方にも行くということになっているのか、伺いたいと思います。それから、裏のページに基礎疾患の例というのが挙がっているのですけれども、２のＢＭＩが３０以上の肥満の方というのがありますけれど、これも基礎疾患のある方の１万３,０００人の中に入っているということなのか、その点も伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"３点目、医師が重症化リスクが高いと認めるケースですが、これも本当にケース・バイ・ケースで、こちらで把握できるものではありませんのと、あと国からも、この文言のみの説明で、これ以上の説明は現時点ではまだありません。","voiceIndex":114,"id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうすると、ＢＭＩ３０以上の方は自ら手を挙げれば、ドクターが認める方ということではなくても対象になるということで考えていいということですよね。自ら手を挙げないと、こういう方には発送されないわけではないですか。そうすると、これを広報しないと手を挙げることができないと思うのですけれども、その広報というのはどういうふうにされようとしているのかも伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"それで、広報の方法ですが、基本的に６０歳未満の方になりますので、もちろん広報しながわ６月１日号で、詳しく基礎疾患がどうとか、こういった方には券が発送されますが、それ以外の方はというものはもちろん載せしますが、逆に言うと、広報しながわは。","voiceIndex":116,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3626#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":36966,"voices":120}},{"id":"r04-20220516-8","meetingId":"r04-cm05","date":"2022年5月16日","dateIso":"2022-05-16","committee":"建設委員会","time":"午後 １時００分～午後 ２時１７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"八潮五丁目地区まちづくりワークショップの実施状況","agenda":"八潮五丁目地区まちづくりワークショップの実施状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"そして今回ワークショップ、既に３回やられているということですけれども、このメンバー、先ほど少しご説明ありましたが、以前にこのワークショップを実施するという説明があった際に、総勢３４名というような、そのくらいだったと思うのですけれども、回答がありまして、この自治会・管理組合の推薦の方が１４名で、子育て世代の方が五、六名ということで今示されておりますが、あとの方ですとか。","respondent":"鈴木都市計画課長","answer":"これから２回程度会を予定していますが、基本的にはこのお集まりいただいた方、お声がけの中で当然増えれば、２回目、３回目は、その中ですることになりますけれども、改めて公募という形では今考えてございませんが、最終的には八潮全体にこのガイドラインの案をお示しして。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、ガイドラインをつくっていくためにこのワークショップをやられているということですけれども、庁内での検討の体制というのですか、そういったところは、このガイドランの位置づけなども含めてどのようになっているのか伺いたいと思います。今度、今月５月に骨子案が示されるということなのですけれども、どういったものなのか、今、ご説明できるということがあればご説明いただきたいと思います。","respondent":"鈴木都市計画課長","answer":"それから骨子案、今は５月という形で資料を提示していますが、いろいろちょっと調整が遅れておりまして、今のところ６月、次回の開催が、資料と異なり申し訳ございませんけれども、６月中旬ぐらいに実施をしていきたいというところで、中身については、やはり八潮、魅力や課題。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"これからまちづくり懇談会をつくっていくということでしたので、そういったところも、ぜひ多くの方が参加をして、住民の意見を反映できるようにしていっていただきたいと思いますが、いかがでしょうか。意見募集を、この素案ができたときにするということで、今予定では９月になっておりますが、この意見募集というものはパブリックコメントとは違うのか、そこの位置づけというのですか、その辺りも伺いたい。","respondent":"鈴木都市計画課長","answer":"まちづくり、八潮の懇談会のほうは、所管が地域活動課というところ、その中の八潮まちづくり担当ということになりますが、その中では地域の自治会ですとか、あるいは学校も含めて様々な地域の団体に、より多くの方に入っていただいて。まさにパブコメと同じ内容ですが、八潮のガイドラインということになりますので、通常の、一般的な計画といいますか、パブコメということになりますと、パブコメの実施条例に基づいて、例えば全地域で。","voiceIndex":9,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったことですとか、地域センターでできることを増やしていくということが１つあるのかなと思うのですが、いかがでしょうか。飲み屋がないという話も聞きまして、そういったところで住民の方たちがコミュニケーションを取って絆を深めていくということも必要なのかなと思うのですが、そういったさらなる充実をしていっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"そうした中で課題も洗い出しされて、いろいろな、様々な検討をされながら進めていくのではないかというところで考えてございまして、今いただいたご意見は、私も、その都市計画課のほうも、恐らくそのメンバーの中には入って、恐らくといいますか、入っておりますので。","voiceIndex":12,"id":"exchange-004"},{"speaker":"のだて委員","kind":"提案","question":"１つ住民の方から伺ったのは、大変な貧困家庭もいらっしゃるということで、そうした家庭への支援も、八潮地区として強めていく必要があるのではないかという声をいただきまして、児童センターやすまいるスクールとも連携したり、職員がお話を聞くなどして、子どもとその家庭を支えていく施策なども必要ではないかと思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"１点目の家賃補助的なお話ですが、今日住宅の所管の課長もおりますけれども、今マスタープランのほうで、マスタープラン、住宅マスタープランも兼ねる形で、いろいろな取組をこれから検討して改定を進めていきたいというふうに考えてありますが。","voiceIndex":14,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ若い人たち、新しい人たちが住みやすいようにしていくということも、自治体の１つの取組として取り組んでいっていただきたいと思います。ですから、住み替えをするような仕組みというものがあると住み続けられるのかなと思うのですが、そういったお考えはいかがでしょうか。","respondent":"鈴木都市計画課長","answer":"八潮団地内、家賃ということになりますので、賃貸ということになろうかと思うのですが、ご紹介いただいたように、別の場所に住みたいという方が家賃が高いからというところでお答えいただいている方もいらっしゃるということは事実でございまして。","voiceIndex":16,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"新たな部署をつくったというのだけれども、その部署の人たちはどのようなやり方をしていくのでしょうか。これ、かなり次元の違う話をしていかないと、八潮地区は救えないのではないですか、と私は思っています。特化すべきことは何でしょう。そうではなくて、これからのことを聞きたいのですけれども、八潮地区をどうしたいのですか。民間の力を借りていくのか、どのような方向で持っていくのでしょうか。","respondent":"鈴木都市計画課長","answer":"おっしゃるとおり、その団地、次回の団地の更新というものに向かって進んでいくときは、非常に大きな、例えば品川区内の一定の面積の建物の共同化、再開発を超えた、やはりある意味１つのまちをどうしていくかということになりますので、ただ、いろいろな他自治体の団地再生。","voiceIndex":19,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"やはりまちづくりというものは、５年などではないです。ですから、民間の方を入れるのかどうか分からないのですけれども、そういうコンサルのようなものを入れてなどと考えているのかどうか分かりませんが、そのような力がないと、恐らく大きな目で見ていかないと、小さい目で見たらまちづくりは難しいと思うのです。細かいところなどと、そのような話ではないと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"まさに私も平成３０年に地域に入って、ご説明してご意見をいただいたときに、賃貸でお住まいになって、２０年、３０年先のことを、何を話せばいいのだという話は非常に厳しくお話しいただいたのですが、一方で。","voiceIndex":21,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろありがとうあります。それも今住んでいる方々だけではなくて、ほかの地域の方とか、それこそ品川区ではないところからとか、八潮地区をどう思いますかでもいいし、このような地域があったらいいよねなどということを、そういう要望でいろいろな立場の人、住んでいる方だけではなくて、外から見るときの意見というものも大切だと思うのです。これは意見にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"},{"speaker":"塚本委員","kind":"確認","question":"最初に、八潮は昭和５８年、第１回の入居が開始ということで、ほぼ４０年前ですか。要するにもう建物の寿命が来て、築５０年ぐらいになったらもう住めませんよというような話とか、いやいや、大規模改修なり何なりしていけば、まだまだずっと住んでいけるのですということなのか、その辺、もちろん東京都の所管だと思うのですが、そのところをまず確認させていただければと思います。","respondent":"鈴木都市計画課長","answer":"このまちづくり検討経費、平成３０年、平成２９年、予算立てして、自治会の方々、地域の方々とともに、この建物を管理しています、所有しています東京都、ＵＲですとか、そうした東京都、それから事業者のほうともいろいろ意見交換をしていく中で、それぞれの建物所有者の方々は。","voiceIndex":25,"id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"分かりました。そうすると、今度住み続けたいですかというアンケートで、先ほどもちょっと議論になっていましたけれども、高齢の方は比較的にというか、当然と言えば当然かもしれませんが、住み続けたいと。","respondent":"鈴木都市計画課長","answer":"そうした細かいところの把握というものはできていないのですが、割合とすると、例えば２年から１１年というところで一定程度、例えば１０年とか、それ以上の年数になりますと今度は１２年から２１年というくくりになりますから。","voiceIndex":27,"id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"１回住んだ方には、今度はなるべくずっと長く住んでいただきたいというのが、多分考え方としてはあるのかなと。いずれにしてもそういったところを、どのような方々が今後入居していただいて、住み続けていただくかという視点での検討ということなのかなとざっくり思うのですけれども、最後に、その視点についてどのようなお考え、議論等があるかということを教えてください。","respondent":"鈴木都市計画課長","answer":"特に住み続けたいという視点でありますと、やはり賃貸の方々にどれだけ長く、長く住みたいと思って住み続けていただくということは、それだけ地域に愛着も持っていただいて、あるいは地域コミュニティへの参加意欲ですとか、そうしたことも芽生えていて、地域の活性化だとか。","voiceIndex":29,"id":"exchange-012"}]},{"id":"topic-02","title":"品川区立区民住宅（ファミーユ西五反田西館・東館）指定管理者候補者の公募","agenda":"品川区立区民住宅（ファミーユ西五反田西館・東館）指定管理者候補者の公募","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"指定管理者候補者の選定基準のところですけれども、ここで管理に係る経費の縮減を図るものということで書かれておりますが、以前から公的な施設で株式会社の事業者が管理をするということはなじまないということを言ってきましたけれども、管理に関わる経費を縮減ということで、無駄なものを省くということは必要だとは思うのですが、質ですか、環境というものはやはり落としてはいけない。","respondent":"竹田住宅課長","answer":"指定管理者との契約の中で、やはり金額的に一番ボリュームがありますのはランニングコストですので、いかにランニングコストを抑えていくかということが指定管理の課題だと思っています。そういった点で、新しい提案を出していただけるように求めていきたいと考えております。","voiceIndex":35,"id":"exchange-013"}]},{"id":"topic-03","title":"の２のその他","agenda":"の２のその他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"継続審査になっている件なのですけれども、羽田空港関連の、かなり数があると思うのですが、これは前々回審査はしたという経緯は分かるのですけれども、ここの、今期の委員会としての継続審査に対しての考え方というか、それはどのように捉えたらいいのでしょう。継続という議論はしているのですけれども、今期どうするかという話はしていないのですが、それはどのように考えたらよろしいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-014"},{"speaker":"西本委員","kind":"確認","question":"その第１回定例会のときに話をしたときに、私の認識では、最後にどうするかという議論があるのかなと思っていました。ですから、ここで議題がないということは、では、この建設委員会、今年度、令和３年度の建設委員会の継続審査になっている案件というものはどうされるのか。ですから、今日はその話があるのかなと思ったのですが、それはもうなしということなのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-015"},{"speaker":"西本委員","kind":"確認","question":"以前というか、その申し送りがどう、ちょっと確認してきていないのですけれども、継続審査の、前は、昔ですよ。ですから、ただ申し送りのほうが、ちょっと確認していないので、そのような決まりはないのでしょうね。このようにやるということは。ですから、私は確認したかったのですけれども。だからどのような扱いになっているのですか。そのような決まりはない。","respondent":"こんの委員長","answer":"結論から申し上げると、先ほども申し上げましたけれども、皆さんに諮ってこれをするというよりは、もう継続ということなので、今期についてはしません。","voiceIndex":45,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"すみません。これは本会議にあるのかどうか、どうなのかなと思うのですけれども、継続審査というものが次年度への継続審査という形で出さないとおかしいのではないですか。これは最終的には出てくる話なのですけれども、最終的には出てくるのですが、ただ委員会としての仕切りはしなければいけないのではないですかというように指摘をさせていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4348#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":24945,"voices":50}},{"id":"r04-20220516-9","meetingId":"r04-cm05","date":"2022年5月16日","dateIso":"2022-05-16","committee":"文教委員会","time":"午後 １時００分～午後 ３時４６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和４年度学校別新入学者の増減要因","agenda":"令和４年度学校別新入学者の増減要因","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、これは学校選択制をやっている以上は当然必要な報告だと思うのですけれども、こういったことを報告するということの区としての目的というのは、改めてどのように考えているのか伺いたいと思います。","respondent":"勝亦学務課長","answer":"こちらの増減要因の分析・報告をさせていただいている目的ですけれども、こういった学校選択ですとか、また国公立や私立にお進みになる様々な選択肢がある中、区民の方が学区の中、学区の外をどのような判断といいますか、お考えの中で、それぞれ入学を決めているのか。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"それと、選択しても入れないという方が大分多いということも分かりましたし、伺いたいのですけれども、指定校変更というところも、去年も聞いたのですが、結構いらっしゃると思うのですけれども、去年質問すると、学校教育法の施行令第８条にある制度なのですと。伺いたいのは、品川区として指定校変更を認める場合の基準について教えてほしいと。その辺を伺いたい。","respondent":"勝亦学務課長","answer":"指定校変更ですけれども、今、委員にご説明いただきました中で、指定校変更の申請をいただいた中で、大体一月ぐらいお時間を下さいませということで受付をしています。そういった中で、教育委員会の中で要綱の基準に照らしまして審査を行いまして、決定しているものです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"それと、指定校変更ですけれども、要綱、基準もあるということなので、後で取り寄せたいと思いますが、どんな感じなのか、ざっとどういう内容なのかというのを伺いたいし、数字も詳しい数字までいかなくてもいいので、大体半分ぐらいが認められていますとか、感触、割合とかがあるのではないか。ほとんど受け入れていますという話なのか、その辺だけもう少し伺いたいのですが。","respondent":"勝亦学務課長","answer":"そういった部分につきましては、基準に合致しないものは指定の変更が認められないということで申請を却下していますので、数としましては、正確には分からないですが、半分程度は認めているのではないかと感触ではつかんでいるところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"なので、それは必要な大事な制度だと思うのですけれども、１点だけ最後に伺いたいのは、時期は選択制が先ではないですか。半分ぐらいということだったので、なぜ半分も切られるのか、よく分からないのですけれども、中には選択制で選択できなかったから、指定校変更を希望している人もいるのかなと思ったりとか、その辺が少し不安なのですけれども、どうなのでしょうか。","respondent":"勝亦学務課長","answer":"そういった意味でも、学校選択制につきましても、学校のキャパシティーの中で選択を行っていただいているものでございまして、こちらにつきましては、学校を教育委員会が指定するに当たりまして、保護者の意見を聞くことができるという制度の上で学校選択をやっておりまして。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"結果的にキャパシティーという話がありましたが、限られたキャパシティーの中で先に選択制のほうをやっているわけですから、そういう配慮が必要な方が後回しになっているのではないですか、そういう実態はないのですか、キャパシティーというものが選択制をやることで狭まってしまい、必要な教育上の配慮ができないようになっていないですかということだったので、もう一度お伺いします。","respondent":"勝亦学務課長","answer":"キャパシティーの問題はありますけれども、指定校変更に関しましては、あくまでも学校を指定した後に行うものでございまして、学校選択に関しましては、就学の指定をする前に参考としてやるものという形の制度の違いで、順番につきましては前後するものです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"つる委員","kind":"質問","question":"もし過去の質疑とか、今日の説明の中にあったら大変申し訳なかったのですが、増要因・減要因とか、それぞれの項目でのその他、（ｅ）とあると思うのですが、その他というのはどういう項目か、改めて教えてください。","respondent":"勝亦学務課長","answer":"その他につきましては、主なものとしましては、就学の猶予ですとか免除をされている方になります。外国籍で区立の学校に入ってこないという方ですとか、そういった方がその他という形になってあります。","voiceIndex":16,"id":"exchange-006"},{"speaker":"つる委員","kind":"質問・要望","question":"主なという割合というか、この数字に対する割合は、基本、ほとんどがそういう方という受け止め、理解をしましたので、もし違えば後で加えていただきたいのと、先ほど安藤委員の質疑の中であった指定校変更について、そもそも品川区が取っている学校選択の取組みとは別のものというのは、ずっと確認できていることなのですが、品川区は学校選択をやっているから。","respondent":"勝亦学務課長","answer":"ただ、品川区の新入学に関しましては、先ほど申し上げましたように、学校選択は、保護者の意見を聞いた上で１２月に学校を指定していますので、学校の指定をした後から入学までの期間に指定校変更の申請をいただいているものです。","voiceIndex":18,"id":"exchange-007"},{"speaker":"つる委員","kind":"確認","question":"すみません、前半のその他のところの認識の確認なのですが、何か補足があればお聞かせください。","respondent":"勝亦学務課長","answer":"失礼いたしました。多くが外国人ですとか、就学の猶予をされた方という認識です。","voiceIndex":20,"id":"exchange-008"}]},{"id":"topic-02","title":"令和４年度（５年度採用）品川区立学校教育職員採用候補者選考日程","agenda":"令和４年度（５年度採用）品川区立学校教育職員採用候補者選考日程","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回、４名程度の採用ということで、昨年の時点で２７名、区の固有教員がいらっしゃるということで、昨年は３名採用しますということだったのですけれども、単純に考えれば、目標としている３０名になったと思うのですが、今回の採用数がなぜ４名になるのでしょうか。","respondent":"中谷指導課長","answer":"昨年度、３名程度の募集をさせていただきまして、予定どおり最終合格者の３名を確保したところですが、実際に採用した人数につきましては１名ということで、途中、辞退者が出たという経緯があります。","voiceIndex":26,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"最終的な採用は１名になって、退職の方が２名いたということになると、４名採用しなくてはいけないということになるかと思うのですが、そういうことでよろしいのかということと、複数名退職者が出てしまったというのは、いろいろケースがあるから何とも言えないのですが、退職者が出ないように、多分教育委員会としては心がけていらっしゃると思うのですけれども、退職者が出てしまったというのは。","respondent":"中谷指導課長","answer":"退職者についてですけれども、基本的には個別的な事情と捉えておりまして、これまでの１０年間を見たところによっても、多少の一、二名程度の退職者が出ているものですので、こういったことも含めて、毎年採用をしていくように考えております。","voiceIndex":28,"id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"品川区の職員の採用にも影響すると思うのですけれども、全体的な傾向として、なかなか教員の希望者が少ないと。例えば、対策が可能なのかどうかも私はよく分からないのですけれども、何か対策みたいなことを考えておられることがあったら伺いたいと思うのですが、いかがでしょうか。","respondent":"中谷指導課長","answer":"教員の確保というところになろうかと思うのですが、今回ご案内させていただいているのは品川区の固有教員ということで、こちらについては平成２１年度から始めておりまして、３０名というところを目標にずっとやってきておりましたので。","voiceIndex":31,"id":"exchange-011"},{"speaker":"吉田委員","kind":"確認","question":"すごく興味深いというか、いわゆる教育実習というものとはまた別に、大学時代に、カリキュラムとは違うのでしょうか、何かそういうことがあるということなのでしょうか。すみません、もう一回確認させてください。","respondent":"中谷指導課長","answer":"プログラムになっておりまして、例えば東京教師養成塾というものが東京都に事業としてございまして、こちらを活用しながら、１年間授業の体験をしたりとか、実際に管理職や教員から話をして、研修のような体制で１年間を過ごすというものになっておりまして。","voiceIndex":33,"id":"exchange-012"},{"speaker":"吉田委員","kind":"質問","question":"整理をすると、そういう制度は東京都が持っていて、そこに名のりを上げる品川区の小学校が複数あって、教育委員会としてもその制度を積極的に活用しながら、固有教員を育てるという言い方は変ですが、そちらへの応募者を増やすような取組をしているという理解でいいでしょうか。ごめんなさい、もう一回。","respondent":"中谷指導課長","answer":"品川区の固有教員の確保については、それとは別になってきますので、区独自のことでやっていくものですので、採用の日程ですとか、案内をしっかり大学にしていきたいと考えていますので、そちらを並行しながらやっていくというものです。","voiceIndex":35,"id":"exchange-013"}]},{"id":"topic-03","title":"品川区立図書館第三期指定管理者選定","agenda":"品川区立図書館第三期指定管理者選定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"委託契約上はどうなっているのでしょうか、伺いたいのと、（１）に戻ってしまいますが、図書館資料の選定や整理等も業務内容に入っていますけれども、図書館の核となる業務だと思うのですが、ここを指定管理に任せるというのは、もはや公の施設というより業者丸投げとなるのではないかと思うのですけれども、区として区民の声を踏まえた公共性の施設というのをどのように担保するのか、伺いたいと思います。","respondent":"吉田品川図書館長","answer":"そのような結果を経まして、実際には書籍の購入という形となります。３番目の資格者の配置ですけれども、募集要項の中で、司書資格を持っている者を５０％確保するように努力することという形でうたっております。","voiceIndex":41,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"そのように理解しました。ですから、（３）の3)というのは、持続的に従事させようと思ったら、賃金を継続的にきちんと向上させていかないと、当然持続的に従事できないわけですから、それと4)、もっと効率的に、なるべくお金をかけないで管理運営するということを求めるのは、どう見ても矛盾なのではないかと思うのですけれども、そこについてはどうでしょうか。","respondent":"吉田品川図書館長","answer":"施設の効用を最大限に発揮するとともに、財政的にも効率的な運営をするというところで、その辺りのところが金銭的な見合いが取れるかというところなのですけれども、そちらにつきましても、その見合いが取れるような形で指定管理を進めていただければと考えているところです。","voiceIndex":43,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"だから今、見合いが取れる範囲で進めてほしいということをやると、結果的に、２番目の質問にも重なってくるのですけれども、もうけを上げる施設ではないわけです。窓口の業務委託も含め、直営で行って、しっかりと区民サービスの向上を図っていただきたいと私は意見を述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-016"},{"speaker":"吉田委員","kind":"提案","question":"施設の効用という辺りは、建物は大体決まっているわけで、それをプロポーザルの提案の中で、「うちだったらこのように活用して、図書館利用者に最大限のサービスが提供できます」とか、何かあるのではないかと思うのですけれども、その辺について事例があったら伺いたいと思います。","respondent":"吉田品川図書館長","answer":"そういう中で、プロポーザルなりにおいては業者から、この施設においては、例えばすぐ思い出すのは、大崎図書館につきましてはリハビリテーションパークとの連携で、そちらのお医者さんからご紹介いただいた本の特集の書架をつくってみたりと、そういう提案をされてみたり。","voiceIndex":47,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうことが伺いたかったのです。それぞれ違うのは当然だと思いますし、違わないといけないのだろうと。だから、それが施設の効用を最大限に発揮ということになるかと思います。この辺については要望です。ただ、満足度の高いサービスみたいなところで、これはまさにこれに当たるという事例があったら、それについても、ごめんなさい、難しい質問かもしれませんけれども、伺いたいと思います。","respondent":"吉田品川図書館長","answer":"この中でも、最終的にはモニタリング調査のところでご報告する内容になりますけれども、各館でも、例えば７割から８割以上のその図書館についての満足度が出ておりますので、それなりの一定の評価は受けているものと考えているところです。","voiceIndex":49,"id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"すみません、難しい質問をいたしました。いろいろ難しいことはあれですけれども、私たちも区民に対しての説明責任というものがありますので、ぜひその辺については、難しいのは承知ですが、具体的なご報告を今後いただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-019"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"ここで、そもそもになるかもしれないのですけれども、民間事業者のノウハウを活用というところがありますが、ここはどういったことに期待して、あとはどういった成果を求められているのかというのが１点と、それから、第二期に入りますと新型コロナウイルスが発生しましたので、図書館運営にも大きな影響があったのではないかと思います。","respondent":"吉田品川図書館長","answer":"コロナ対応につきましては、費用的な面で言いますと、指定管理業務の中に一定程度、毎年の指定管理料を算定する中で、令和３年度以降につきましては、費用として含めているところです。","voiceIndex":53,"id":"exchange-020"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"区民からの声、要望といったものを、さらに指定管理者に投げて、それで、そういうのがあるから、そういうのを叶えてくれないかというのも、今後されていくのだと思いますので、ぜひ第三期の指定管理者を募集する際には、ただこれをやってほしい、管理をしてほしいというところ、もちろんそれも大事だと思うのですけれども、そういった要望というのもしっかりと叶えられるところもお願いしたいと思いますし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-021"},{"speaker":"つる委員","kind":"提案","question":"当然、指定管理者になるに際しても、先ほど来確認のあった選定基準の中にもいろいろ項目があって、大きなイメージだとか、そういったものは、選考のときに事業者からいろいろ提案等があるとは思うのですが、ただ、今伺っている取組だとか、先ほどのご答弁の中で、品川区ではこれまでやってこなかったビブリオバトルとかというのは、全国で見てもやられて久しいということとか、あとは、逆に言うと。","respondent":"吉田品川図書館長","answer":"ＳＤＧｓの７館のところの質問につきましては、確かにＢグループのところは受託業者が違う関係があって、今は分かれた感じになっておりますけれども、そこのところは今後調整してまいります。","voiceIndex":56,"id":"exchange-022"},{"speaker":"つる委員","kind":"質問・要望","question":"品川区が求める、こういうものをやってほしいという、先ほど副委員長からもあったのですけれども、また地域の声も、まさに利用していただいている方々の声というのは一番大事かもしれませんが、よく片仮名４文字でノウハウと使われる部分の民間委託をしているからこそ、もっと魅力的な部分を活かし切っていくという意味で、もっと積極的な、いろいろなアイデアが全国にあると思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-023"}]},{"id":"topic-04","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"今、子育て応援課として取り組んでいる内容について伺いました。例えば姿勢として、具体的に実際そういう事例が起きたときには、こういうことがあるということなのですけれども、制度として、相談体制として、もし万が一こういうことがあったら、ここに相談に来てくださいなどという制度としての相談窓口とか、具体的に、そういうときにはこの制度が使えますというご案内というのは、何かあるのでしょうか。","respondent":"飛田子育て応援課長","answer":"その場合、養育費とかは取れるのかとか、そういう相談から入ってきています。そういう家庭相談というところで、こちらで受け付けていますというアピールというか、周知をしているところです。","voiceIndex":67,"id":"exchange-024"},{"speaker":"吉田委員","kind":"確認","question":"そうすると、制度として示されているのは、ざっくりとした家庭相談で、その中に、具体的にこういうことも相談の対象になっていますというところまで、制度として示されているのか、もう一回確認させてください。","respondent":"飛田子育て応援課長","answer":"そうです。はスタートのところから、相談内容によっていろいろ、この人にとって何が必要なのか、何を聞きたいかということに合わせて、こちらで相談に応じているところです。","voiceIndex":69,"id":"exchange-025"},{"speaker":"吉田委員","kind":"質問","question":"残念ながら、最終的には離婚ということになって、それぞれ具体的に、子どものための最善の仕組みということで相談を進められて、今度はその先の制度で、陳情の理由の中に示されている、これは事例だと思うのですけれども、明石市の事例として、合意書とか、養育プランとか、これも具体的な制度というのでしょうか、そういうものが品川区の中でも。","respondent":"飛田子育て応援課長","answer":"公正証書の作成支援ということで、公正証書の作成費用の補助ということも令和３年度から開始したところです。","voiceIndex":71,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"この方の場合、面会交流について、もっと支援を充実してほしいというのが大きな柱の一つだと思うので、そういう点からすると、私はもっと踏み込む必要があるのではないかと思っています。子どもが、離婚したといえども、２人の親ときちんと絆を保っていくということについての重要性というのは、品川区としてはどのようにお考えなのかということも、２つ目として伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"そういうところを考えると、子どもにとって何が一番幸せなのか、そういうところはしっかり考えていかないといけないことだと思います。","voiceIndex":74,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"そうなりますと、この方にとっては、そういう制度が実現するまで待っているしかないとなると、冷たいのではないかというか、もう少し具体的に、品川区の中でそういう声が出ているわけですから、実態があるわけですから、私はそういうのではなくて、きちんと何ができるかというところから、研究、支援を強めていくということが、すごく大事なのではないかと思いますが、いかがでしょうか。","respondent":"飛田子育て応援課長","answer":"品川区としても、取りあえずこちらで支援を令和３年度から始めていますが、そういうところでは丁寧に、まずはお子さんのこと、またご両親、ご夫婦、家庭内のことですので、まずその中でしっかり話し合って、お子さんにとって、また今後２人の生活にとって何がいいのか。","voiceIndex":76,"id":"exchange-028"},{"speaker":"松本委員","kind":"質問","question":"逆に、親からの相談ではなくて、子どもから、離れている親に会いたいという相談を受けるような体制というのは、何かしら品川区内にあるのか、伺いたいと思います。子どもの権利を考えるのだったら、子どもが会いたいと言ったときに対応できるかどうかという体制は重要だと思うので、そちらのご答弁をお願いします。","respondent":"飛田子育て応援課長","answer":"子育て応援課としましては、まず大人の話合いのところで相談業務をやっているところです。子育てについて、子どものところから、保護施設とか、そういうところでまた話が上がってくることだろうと考えております。","voiceIndex":79,"id":"exchange-029"},{"speaker":"松本委員","kind":"質問・要望","question":"子育て関係なので、あくまで子どもの意見は、また別のところからというご見解なのだと思うのですけれども、そうはいっても親子問題なので、できればほかに学校とか、所管が教育委員会とかになってしまうのかもしれないですけれども、そういうところと連携はしていただきたいと思うのですが、そこはいかがでしょうか。","respondent":"飛田子育て応援課長","answer":"もちろん、お子さんを取り巻く環境というのは様々で、お子さんなりの考えもあると思いますので、そういうところは関係機関とも相談しながら、丁寧に応じていきたいと考えております。","voiceIndex":81,"id":"exchange-030"},{"speaker":"松本委員","kind":"質問・要望","question":"ただ、それが難しいのも理解していて、一方でこの陳情者が一番訴えている点というのは、面会交流のコーディネートをやってほしいというところだと思います。なので、そこの辺りを何とか区としても、東京都がやっているからというところではなく、区としても研究して、少しでも進めていただきたいと思いますが、いかがでしょうか。","respondent":"飛田子育て応援課長","answer":"ですので、そういうところも鑑みながら、また様子を見て検討していきたいと考えております。","voiceIndex":83,"id":"exchange-031"},{"speaker":"松本委員","kind":"質問・要望","question":"なので、今のご答弁は必ずしもそこは当てはまらないかと思うのですけれども、いずれにしろ、親子の面会ができない、親子だけではなくて、実は日本の法律上は、祖父母は調停とか審判すら申し立てられないというか、祖父母については面会を請求する権利さえ一切ないというのが我が国の法制になっておりますので、何とか地方自治の段階から少しコーディネートできるようにお願いいたしまして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-032"},{"speaker":"松澤委員","kind":"質問","question":"私もこの陳情を伺ったときに、港区や明石市の情報を収集、調べておりました。先ほどよくお話がありました面会交流については、面会交流の援助に取組むために、ＦＰＩＣ（家庭問題情報センター）を必要に応じてご案内しているというお話を聞きましたが、現段階で品川区からここに相談を依頼したとか、そういった件数が分かりましたら教えてください。","respondent":"飛田子育て応援課長","answer":"こちらでご案内というか、こういう相談事業がありますということでご紹介しますが、その後、その家庭で話し合われて、そこを利用するかしないか、そこまではこちらで把握できていない状況です。","voiceIndex":87,"id":"exchange-033"},{"speaker":"つる委員","kind":"質問","question":"先ほど松本委員の質疑を伺っていて、今回の場合は、それぞれの方が相談をする場というのがあるのですけれども、子どもの相談というのはまた別である。そうなってくると、今、子ども応援課というのをつくったほうがいいのかと思ったら、子ども家庭支援センターです。そこだけではなくて、いろいろな悩み相談、いじめとかとはまた違うのでしょうけれども、いろいろな相談、悩み事、家の中でこうだと。","respondent":"染谷子ども家庭支援センター長","answer":"現状において、委員がおっしゃられた夫婦間の不和という部分についての具体的な数字については持ち合わせておりませんけれども、実際にこういったケースを受け持つ中で、お子さん、それから各ご夫婦に関しましても、それぞれ面談をさせていただきまして。","voiceIndex":92,"id":"exchange-034"},{"speaker":"つる委員","kind":"質問","question":"そこで受けた情報とか話とか相談内容を、後ろで連携するというのは、要保護児童対策地域協議会とか、そういうところの課題とはまた違ったりするのかと思ったり、先ほど申し上げたように、子どもに対するベクトルというのは、あふれんばかりの愛情で、ただ単純に夫婦間だけの課題というところでも、家庭環境が壊れるのが嫌だと思っている子どもがいてとか、それを何とかつなぎ止めたいという。","respondent":"飛田子育て応援課長","answer":"やはり子どもにとって一番いいのは、そういう時間を与えて、子どもが会いたいときに会える環境というように、話がスムーズにいくところがほとんどだと聞いております。","voiceIndex":94,"id":"exchange-035"},{"speaker":"つる委員","kind":"確認","question":"現状、この陳情のところで確認すると、内容としては、面会交流コーディネート事業というものも、よいところはあるわけですが、今ご答弁いただいたいろいろなやり方で、夫婦それぞれの判断というのがあるのでしょうけれども、子どものという視点と、父親、それから母親、それぞれのというところで、この間、私も６年前、品川区の取組について質問させていただいたこともあったのですけれども。","respondent":"飛田子育て応援課長","answer":"実績は、令和２年度は３件、令和３年度は２件、コーディネートの申込みがあったと伺っております。そして、文京区は令和３年度よりということで、文京区の実績は１件のみと報告を聞いております。","voiceIndex":96,"id":"exchange-036"},{"speaker":"つる委員","kind":"確認","question":"そういう部分で、今、先行して取り組んでいるところの実績だとかも、一つ参考になるかと思いながら、先ほど確認させていただいた子どもの相談事に対する体制の在り方というのは、親のことだからというのでなかなか相談しづらいお子さんもいるのではないかと思うのですけれども、ただ一つ、現状が、積極的なアナウンス、こういうことがあったらいいのだよという、相談をいつも下さいねというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-037"},{"speaker":"安藤委員","kind":"意見","question":"それは別に正しいことでも悪いことでもなくて、そういう事実なのです。夫婦の多様性とか、家族の在り方といった観点からもそうですし、何よりも子どもの権利が大切にされている姿なのではないかと思いますので、面会交流支援というのは、そういったところに重要な支援になるということで、ぜひ研究、検討を進めて、実施できるところは実施していくべきだと思いますので、採択を主張いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"子育て応援課が、すごく相談とかについては頑張っていらっしゃることは伺いました。この陳情者は具体的な支援策と整備体制の充実を求めておられますので、子ども家庭支援センターとか子育て応援課が進められていることを、議会として共に同じ方向を目指して促進するという意味でも、採択は妥当ではないかと思って、採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-039"},{"speaker":"松本委員","kind":"質問・要望","question":"国でも今、議論は少しずつやっていますけれども、なかなか遅々として進まない中で、最も区民に身近な自治体として、こういったところ、ほかの自治体がまだまだできていないのは、もちろん認識しますけれども、ぜひ品川区においては進めていただきたいと思いますし、なかなか難しいということであれば、議会としてこの陳情を採択と、議会の対応としてやっていくことが重要ではないかと思い、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-040"}]},{"id":"topic-05","title":"を改めて聴取いたします。 (4)法改正に伴う児童手当事業の変更点","agenda":"を改めて聴取いたします。 (4)法改正に伴う児童手当事業の変更点","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"今回の変更の理由をどのように聞かれているのかというのを伺いたいのが一つと、資料の１の（２）の届出義務の廃止のところなのですが、２行目の「公簿のみでは現況を確認することができない」と書いてある公簿というのは、具体的には何を指しているのか伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"国からの通知につきましては、今回上限を０円というところでは、その分、消費者対策にお金を回すように国は考えていると伺っております。","voiceIndex":110,"id":"exchange-041"},{"speaker":"松本委員","kind":"質問","question":"この制度については、国の制度なので、あまり言ってもあれなのですけれども、収入が高い人で子どもが５人いるパターンとかというのは、今回１,２７６万円ですけれども、子どもが１人で低い人で、もらえる人との整合性で考えたときに、国の少子化対策の面で考えたときに、これが本当にいいのかと思ったり、国のほうでは高齢者の方に５,０００円みたいなアイデアがあったり、どうなのかと思うのですけれども。","respondent":"飛田子育て応援課長","answer":"こちらは前年度の収入が適用されますので、お子さんがその後、生まれた場合ということになりますので、扶養家族が増えたとか、そういうところで０人と記載をしています。","voiceIndex":113,"id":"exchange-042"}]},{"id":"topic-06","title":"令和４年４月入園申請状況等","agenda":"令和４年４月入園申請状況等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"私が勘違いしていたのかと思って、一本橋保育園を例に挙げてご説明いただきましたけれども、１歳児の最大指数が４０というのは、入れた方で最低の方は点数が４０で、階層Ｄ２５と私は認識していたのですけれども、だから逆に言うと、４０点であっても入れない人がいるという認識だったのですが、今の説明だと、４０点のＤ２５の方は全て入れていますと聞こえたのですが、そこは私の勘違いだったのでしょうか。","respondent":"立木保育課長","answer":"最下指数の表の見方ですけれども、先ほどの一本橋保育園の例ですと、指数が４０点で、税の階層がＤの２５の方までが入園したという形になりますので、例えばＤの２６階層の方は入れなかったということになります。","voiceIndex":119,"id":"exchange-043"},{"speaker":"安藤委員","kind":"確認","question":"最下指数のことでもう一度確認なのですが、４０のＤ２５と表記されている場合は、とはいっても、４０でＤ２５の人が複数いた場合もあるのではないですか。その方も確実に入れたという意味なのですか。私の認識の中では、そういうことです。それの確認だけ、後でお願いします。","respondent":"立木保育課長、中元保育支援課長","answer":"大変失礼いたしました。指数が４０点で、税の階層がＤの２５のところに複数の方がいらっしゃった場合、その中でも優先順位というものがついてまいります。不足しているところは、そちらの海沿いの地区と、あと一つは、五反田のほうに大きなタワーマンションが都市計画をされておりまして、そちらにつきましては、一度に世帯数が多く入られる。","voiceIndex":121,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"続けて質問なのですが、昨年も質問したのですが、不承諾数の内訳について、もう少し伺いたいのですが、厚労省が毎年、区に報告を求めて公表しています様々な数値があるのですけれども、だから品川区としても報告しているわけですが、不承諾通知のうち、求職活動を休止している者ですとか、地方単独事業を利用している者、その中には、いわゆる定期保育事業というのが品川区にはあります。","respondent":"中元保育支援課長","answer":"２点、ご質問ございました。東大井、東品川地区につきましては、厳しい状況があるというところは認識しています。","voiceIndex":124,"id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう少し国の内容確認をしてからということなのですが、最後に要望を含んで質問したいのですが、それはいつぐらいになったら確定するのかというのを伺いたいのと、国基準にとどまらず、それが実態なわけではないですか。国基準にとどまらず、いわゆる隠れ待機児童を含めた、今おっしゃっていただいたような数字の議会への報告、あと、国への公表を改めて求めたいと思いますけれども、いかがでしょうか。","respondent":"中元保育支援課長","answer":"区におきましては、従来からご報告申し上げてありますが、待機児童というのはあくまで国の基準での考え方で取ってありますので、これが全てということで考えているところです。","voiceIndex":126,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5064#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":45117,"voices":134}},{"id":"r04-20220516-5","meetingId":"r04-cm05","date":"2022年5月16日","dateIso":"2022-05-16","committee":"総務委員会","time":"午後 １時００分～午後 １時３９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"冒頭で申し上げたとおり、取り上げる順番を変更し、まず、(2)参議院議員選挙における執行要領","agenda":"冒頭で申し上げたとおり、取り上げる順番を変更し、まず、(2)参議院議員選挙における執行要領","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"期日前投票所一覧、この件でお伺いしたいことが２点ほどあります。アトレ大井町がこの一覧の中にないので、それがなぜかということを１点お伺いしたいと思います。これを何とかしていただきたいというふうに思うのですけれども、この点、いかがでしょうか。この２点をまずお伺いしたいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"ただ、今回に関しましては、一番大きな理由としては、様々な集客のためのイベントなどを予定を組んで実施するということで、３か月前には期日前投票として使用する期間を決定してほしいというご要望があったのですが、国政選挙につきましては。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"あるいは地域センター以外で何か利用できるものがないかも考えていただきたい。やっぱり区役所１か所だけしか最初から投票できる期日前投票が、この期間、２週間ずっとできるところがないというのは、ちょっと限定し過ぎではないかというふうに思うのですけれども、その点、もう少し考える余地があるのではないかと私は思うのですが、いかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"ただ、ご指摘のありましたほかの施設や、一部のみの地域センターというようなことが可能かどうか、また、そのときの住民の方の公平性等の担保も含めて、検討の余地はあるのではないかと考えているところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"検討していただければと思います。要望をします。それからもう１点。ですから、そうやって政治に参加していくハードルを引き下げていくことを考える。あるいは、考えるべきだと私は思います。品川区としても、これは国法の問題でもありますけれども、こういう側面からの働きかけもやっていくとよいのではないかと思うのですが、そのようには考えておられないのでしょうか。この点、伺いたいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"理由としましては、自治体によりまして、年齢構成や地域の成り立ち、それから地域の広さ、距離なども変わりますので、一概に決められるものではないというところもあり、その中で、今、検討されて定められた年齢要件なり供託金ですので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"確かにいろいろ要素があって決められるものだとは思います。ものだとは思うのですが、やはり大きく政治参加を促していくという角度から、いま一度考えていただければと思います。これは要望ということで言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"幾つか質問させていただきたいのですけれども、まず、選挙公報についてですけれども、配布期間について伺いたいのですけれども、配布期間が７月８日までということで、投票日の２日前までということですが、これは、２日前までというのは、何かルールとか、法律とかで定めがあるのか、もうちょっと前倒しにできないのかということを、やっぱり選挙公報を見て選ぶという方は多いと思うので。","respondent":"鈴木選挙管理委員会事務局長","answer":"区のホームページにおける投票所移動の支援についてのお知らせですが、これは区のホームページや広報しながわの選挙特集号、こちらのほうでもしっかりとお知らせをして、ご利用いただけるようにしたいというふうに予定をして準備しております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"今回の選挙の投票率向上に向けた啓発というのは、特にはないのかという、そこを確認したいのと、あと、投票済証について、ぜひ「ありますよ」というお知らせをお願いしたいと思います。選挙公報についても、なるべく早めに、８日までということですけれども、なるべく早く配布ができるようにということは要望したいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"すみません、啓発についての詳細な予定ですが、先ほど申し上げました広報しながわの選挙特集号のほかに、ホームページ、それから、今回はコロナ対策ということで、通常行っている街頭の啓発は自粛をする予定ですが、そのほかに、ＦＭしながわ、それから、ケーブルテレビ品川で。","voiceIndex":15,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"先ほど、投票率の低さ云々という話があったのですが、それは我々議員の、また、いろいろ皆さんに対する、やっぱり我々が逆に投票を呼びかけるという、また、我々の活動に対する魅力ですか、それが少ないせいもあるのかなと思うので、供託金、それから選挙権の年齢等ありましたが、実際そういうことならば、所管事務調査でまたしっかり委員会で検討すればいいのではないかと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"そういう中で、区の施設の敷地であったり、公共機関に準じるような場所は、できるだけお願いをして受けていただいているのですが、それ以外の場所については、特に私有地の場合は、なかなか場所の確保が難しいということがあります。","voiceIndex":18,"id":"exchange-007"},{"speaker":"田中委員","kind":"意見","question":"すみません、ちょっと聞き忘れてしまいました。感染症が広がったときの対応は、そういうお知らせも、もし感染した場合の投票のやり方も、ぜひ広く広報してほしいなということを思っています。そのことについてもぜひお知らせいただければ……。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご指摘のありました感染症等で事情があって特例等郵便を使う方に関しては、今回も事前の選挙特集の広報しながわで欄を１つつくりまして、該当する要件であるとか、それから、郵便投票でできる制度があるということはお知らせをしておりますので、ただ。","voiceIndex":21,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"今ご答弁いただいたような内容を、ぜひホームページ等でもお知らせしていただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"}]},{"id":"topic-02","title":"品川区・早川町ふるさと交流３０周年記念事業","agenda":"品川区・早川町ふるさと交流３０周年記念事業","exchanges":[{"speaker":"田中委員","kind":"質問","question":"予算はどのくらいなのですかということと、あと、鐘を新しく設置するということですよね。これは小さな、これで合っているのか分からないですけれども、ホームページで見ると、標高４８２ｍの丸山というのですか、その山の上に鐘を設置するのですか。それとも下に設置するのですか。ごめんなさい、ちょっと……。お知らせいただければと思います。","respondent":"古巻総務課長","answer":"予算といたしましては、当日の宿泊費でありますとか、交通費というか、バスの借り上げです、これは先ほどちょっとお話のありました鐘の設置のための費用を含めまして、１３９万３,０００円ということで予定をしております。","voiceIndex":28,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"今回、こういう事業をやるのですが、区のほうでも交流事業ということで支援等もされていると思うのですが、実際今、品川区民は、分かる範囲でいいのですが、何人ぐらいの方がここに行かれて、そして、自然と親しむような利用をされているのですか。もし分かれば教えてください。","respondent":"古巻総務課長","answer":"とはいっても、一時期、移動ができる時期とかもありましたので、数十人程度は、去年、一昨年と利用しているのかなということと、あと、マウントしながわの里山再生事業のほうも、定員は大体２５人ぐらいで、年間四、五回やっているのですけれども、大体毎回。","voiceIndex":31,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"今、大体の人数で明確には言われなかったですが、実際、今どうなのかなと思うのは、品川区民の方も、趣味というのは、やっぱり自然と親しむということも、やはりそれぞれ多様化している現在だと思うのです。見直し等も検討されているのでしょうか。もし何かそういうものがありましたら教えてください。","respondent":"古巻総務課長","answer":"例えば、早川町で言いますと、早川町の食材を使った給食をやってみたりとか、あと、先頃オープンしたエコルとごしの建築の木材には早川町の杉が使われているとか、そういったこともありましたし、また、早川町には川沿いのところがありますので、水害とか。","voiceIndex":33,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"場所的にも、なかなか交通の便云々ということもあるかと思いますし、先ほど申し上げました交流事業という、自然と親しむということはいいのでしょうけれども、やっぱり区民の皆さんも、私の聞き入る限りでは、様々な多様性、いろいろなところ、別のところへ行っているのだよとか、そういうお話も聞きますので、もし事業云々ということで今後も続けるようならば、やっぱり区民にとって、より利用しやすい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2230#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":12817,"voices":38}},{"id":"r04-20220517-14","meetingId":"r04-cm05","date":"2022年5月17日","dateIso":"2022-05-17","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時０３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6128#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":1628,"voices":11}},{"id":"r04-20220518-19","meetingId":"r04-cm05","date":"2022年5月18日","dateIso":"2022-05-18","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 １時３５分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"フードドライブの実施","agenda":"フードドライブの実施","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"こういう機会が増えるのは大変いいことだと思うのですけれども、一方で、周知されて皆さんの意識が高まると、集まってくるものも多くなるかと思います。それで少し気になるのが、その保存のことです。もちろん生ものはないでしょうけれど、やはり保存というのは、その先のことを考えると気を遣うべきことだと思うのです。その保存のことはどのようにお考えか、伺いたいと思います。","respondent":"河内環境課長","answer":"この取組みにおきましては、賞味期限まで４か月以上あるということで、社会福祉協議会を経由して子ども食堂などで活用されますが、その間、それがまた無駄になりませんように、一定の期間を設けまして保存し、活用いただくような想定で進めているものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"吉田委員","kind":"質問","question":"ということは、集まってきたものは速やかに次の段階まで持っていって、適正な賞味期限で必要な人の手元に届くようにお願いする、ということでしょうか。子ども食堂ネットワーク事務局が、その辺はうまく配分してくださると思うのですけれど、その辺だけ気になったので教えてください。","respondent":"河内環境課長","answer":"したがいまして、既に傷んでいるものは渡らないと同時に、種類なども確認しながらやっておりますので、その際、それらを役立てる献立といったものも想定しながらやることによりまして、さらに無駄が生じないような工夫をもとに進めているものです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"私が今まで出していたところは、基本、新しいものがいいに決まっているのですけれども、搗精から２年以内はお受けしますというところだったのです。そういうものはそこの能力によるので、その団体は集まってきたお米を、不公平がないように全部混ぜて配るという作業をしていらしたので、とても大変だなと思いつつ、やはりあまり古い搗精のものは、と思うので、その辺どのようにお考えか伺いたいと思います。","respondent":"河内環境課長","answer":"米ですが、きちんと袋に入った状態でまいりまして、精米の日付が入っております。その精米の日付によりまして活用される方にご判断いただき、お引取りいただく形で進めてあります。バラで量を測って仕分けるということは、傷みますのでやっておりません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。本当にごもっともだと思うのですけれど、そうすると、やはり寄附していただいたお米の精米日、たまたま私が寄附していたところは搗精日から２年以内ということだったのですが、品川区の場合は、そういう分け方だと、例えばもっと短くするとか、そういうことをお考えなのか、伺いたいと思います。","respondent":"河内環境課長","answer":"中身につきましては、いつまでのもの、というふうな仕切りでは進めておりません。あくまで現場主義で進めているものです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"吉田委員","kind":"意見","question":"ただ、やはり調理してみれば分かるのですけれど、あまり古い精米日のものはなかなか食味的には、ただ一方で、食べられないわけではないので、もったいないなとは思うのですけれども、やはりお使いになる方と提供する方の保存の能力、例えば冷蔵庫も、お米まで入れられるところがあれば大分違ってくるかと思うのですけれども、そういうこともぜひ、現場主義と今おっしゃいましたけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。冒頭に一つ確認させていただきたいのですが、エコルとごしがオープンいたしまして、そのオープンの日にフードドライブを実施していただいたかと思うのですが、その時の状況を、数とか分かりましたらお知らせください。","respondent":"河内環境課長","answer":"平成３０年から取り組んでいる事業でありますが、そういったところでも割と浸透してきたかなという感触の中で、持込み点数も最多を記録したというところで、量が多いことを目的としてはいないですが、いざ声をかけると、こういったところでもやはり。","voiceIndex":15,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"私も、エコルとごしのオープンの日、フードドライブのところに寄らせていただいて、少し状況をお伺いしまして、大変好評だったなという印象は持っておりました。それが１点。それと、受付窓口はこの３か所ですけれども、子ども食堂ネットワークを通じて活用されるのですが、社会福祉協議会での受付というのは、あえてこの中に入れていないのでしょうか。こちらとの関連も教えていただきたいと思います。","respondent":"河内環境課長","answer":"フードドライブの取組み自体は環境省の取組みになっておりますが、その辺りの考え方は今後変化していく可能性もありますので、検討しながら進めてまいりたいと考えているところです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"１点だけ。名称のことです。そうすると多分、これは一過性ではなく、ますます区民の方のニーズ、意識も上がっていくだろうから、単年度というよりは３年後、５年後どうするか、というようなビジョンがあっていいかなと。その言葉を知っていただく、認知度を上げる。イコール、その成果物、成果が見えるような事業計画があってもいいかと思うのですが、現状と今後というところで教えてください。","respondent":"河内環境課長","answer":"３年、５年ではなかなか落ち着かないと思いますが、極端な話、このフードドライブ事業が全く必要のない世の中になったほうがいいと思いますが、とは言いながら、やはり食料自給率とか、あるいは食料の余力率とか、非常に難しい問題がありますので、こういった社会構造ですので。","voiceIndex":21,"id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問・要望","question":"これは多分、次年度以降のリクエストというか要望になると思うのですが、少し中長期の目標設定をしてもらいたいと思います。それと、いいことだけれども、押しつけてしまうのも、よくありがちではないですか。環境なども啓発は難しいところで。それはどこかへ委託でも何でもいいですから、面白み、遊び心を持ってやられたらいいかなと思うので、その辺をお願いしますとともに、ご答弁お願いします。","respondent":"河内環境課長","answer":"行政だけではなく、多様な団体との連携ですが、多くの切り口で、この事業にご参加いただけるよう、そういったきっかけづくりも含めまして、連携につきましては今後も検討を進めてまいりたいし、また拡大してまいりたいと考えているところです。","voiceIndex":23,"id":"exchange-009"},{"speaker":"こんの委員","kind":"質問","question":"１点お伺いしたいと思います。実際に区民の方がこの３つの受付にお持ちいただいたとき、少し気になるのが、まず、曜日が日曜日までになっていて、例えば環境課は、日曜開庁はあるものの開いている窓口は限られているはずですから、そこがどうなっているのか。実際に持ち込もうとしたとき、そこがどうなっているのか。","respondent":"河内環境課長","answer":"そういったことにつきましては、チラシなどでしっかりと宣伝申し上げまして、紙の媒体と、今おっしゃられた電子媒体と含めまして周知するとともに、のぼりなどにつきましては、また検討していきたいと考えているところです。","voiceIndex":26,"id":"exchange-010"},{"speaker":"こんの委員","kind":"意見","question":"致し方ないだろうとは思うのですが、庁舎は、日曜開庁はしているけれども上がれないというのが、大体周知されてきていると思うのですけれど、消費者センターは、今まで大井一丁目の社会福祉協議会がある建物の中だったのが、そこから移転されて、大分周知されてきているのかどうか分かりませんが、また、確かに４階まで上がる方というのは必要のある方だけで、４階に上がってみても。","respondent":"河内環境課長","answer":"今、委員からご指摘いただきましたとおりです。区民の方が実際にご活用、ご利用いただくときに混乱がありませんように、周知、ご案内につきましても工夫をして進めてまいりたいと考えているところです。","voiceIndex":28,"id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"目的のところで、「家庭や事業所にて」ということですけれども、先ほど提供者２１名ということですけれど、事業所はどれくらいあるのか、また、企業も含めているのか。先ほどもビジョンを持つべきだというお話がありましたけれど、そういう点ではどう考えられているのか、伺いたいと思います。","respondent":"河内環境課長","answer":"そういった幅を広げる努力をしながら、広げられればというところで、長期的なビジョンではないですけれども、受け取る側も工夫をしながら、また区民の方、事業者の方の知恵も拝借しながら、そういったところの検討を進めていきたいということで、今も進めているところです。","voiceIndex":32,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"フードロスというのは本当に大事なことだと思いますし、何か大量に廃棄されているというものもたくさんあると思うのです。企業も、ちょっとした不備でこんなに廃棄してしまうのか、ということもたくさんあると思いますので、有効に活用していけるといいと思いました。フードロス削減というのは本当にいい取組みだと思いますし、そういうところにもつなげていっていただけたらと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-014"}]},{"id":"topic-02","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"たけうち委員","kind":"意見","question":"この間、気づいていたら言っていたのですけれど、表面の４番で、「消防機関と連携しつつ管轄区域の被災状況や町場の声」とあるのですけれど、「町場の声」というのはあまり、話し言葉では使うのでしょうけれど、こういう文章にするときには「地域の声」などにしたほうがいいのではないかと。内容的な問題ではなく、一応どうかなということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6614#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":12358,"voices":53}},{"id":"r04-20220520-10","meetingId":"r04-cm05","date":"2022年5月20日","dateIso":"2022-05-20","committee":"議会運営委員会","time":"午前１１時００分～午前１１時１４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議会構成等","agenda":"議会構成等","exchanges":[{"speaker":"須貝委員","kind":"確認","question":"これは何か事情があってこのように変わったのか、その意見、考え方だけお聞かせください。ちょっと前回は、私もそのまま前の考え方を踏襲されたと思って、総務委員会に無所属が入るということを意識して確認しなかったので、ちょっとご見解だけお聞かせください。","respondent":"石田（秀）委員長","answer":"欠員等が今回は３名あるということでありまして、無所属の議員の方が５名いらっしゃるということで、総合的に勘案をしようということにいたしまして、どこを７名にするのかというような検討もさせていただいて、正副でも議論をさせていただいて、最終的にはこのような形で。","voiceIndex":10,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5462#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":4686,"voices":21}},{"id":"r04-20220526-10","meetingId":"r04-cm05","date":"2022年5月26日","dateIso":"2022-05-26","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議事日程（１）、追加議事日程および追加議事日程（２）","agenda":"議事日程（１）、追加議事日程および追加議事日程（２）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"両方反対です。長い間、品川区議会は第１会派、第３会派で監査委員を選任してきました。改めて原点に戻って、監査委員は第１会派および第３会派から選任されることを要望したいと思います。したがって、今回の選任同意についてですが、監査委員は第１、第３会派からセットで選任すべきだと考えていますので、少し先になってしまうのですけれども、どちらにも反対ということを表明します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-001"},{"speaker":"須貝委員","kind":"意見","question":"私も賛成しますが、今、安藤委員からもありましたけれども、きちんとしたルールづくりを議運の委員長、また議長に対して、その時々、このように誤解を与えるようなことではなくて、こういう形で選任しますというルールづくりはしておいたほうがいいのではないかと思います。今回は両名とも賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-002"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"提案","question":"そこら辺を、このデジタル社会で今、品川区もＩＣＴ化を推進している中なので、返却するときに、ネット銀行でもいいし、２４時間対応できるような仕組みづくりを議会でも検討してほしいし、また会計管理室のほうでもそういうことに対応できるような仕組みをつくってもらえないかという要望と、議運に対して皆さんに問いかけているということなのですが、皆さん。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ただ、これは恐らく全国的にそうなってしまったのかなというところもあって、事務局の工夫でどうにかなることではないということは、理解はしているのですけれども、私のほうも担当者が、今おっしゃっていたところまで行って、時間をかけて予約してやっているという実態もありますので、何か改善はしていただきたいというのは前々から申し上げているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"お金を持っていって、窓口に行って、１０分ないし１５分で済んで、さっと帰れるかと思ったら、そうはいかなかったということで、ショックを受けたということがありまして、それで向こうにも聞いた。私は１年に１回のことなのですが、あくつ委員はもっと回数が多いかもしれないですが、一応ここの場で申し上げておきたいと思います。ご検討をよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"一言申し上げます。いいよというか、これも一応、言っておきますけれども、これは銀行の問題なのです。電子送金するとかしないとか、そもそもはそこではないのです。だから、電子送金云々というのは、その後の話であって、そこは議会として共通認識を持っておかないと、話がおかしな方向に進んでしまうと思うので、そこだけご確認をいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5464#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":10731,"voices":53}},{"id":"r04-20220527-6","meetingId":"r04-cm05","date":"2022年5月27日","dateIso":"2022-05-27","committee":"区民委員会","time":"午前１０時０７分～午前１０時４８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第３９号議案 令和４年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第３９号議案 令和４年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"原油価格・物価高騰対応ということで補正を組んでいただきました。幾つか伺いたいのですけれども、まず、経営に様々な影響が懸念されるとありますけれども、具体的に、どういった問題が中小企業の中で起きているのか、区の認識を伺いたいと思います。そして、区内中小企業の資金調達を支援するということですけれども、財源は一般財源ということなのか、お伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの財源ですが、一般財源ということで、財政のほうで、国から頂ける臨時交付金ですか、そちらの充当について考えているような形になっておりますが、今回は一応、一般財源でということで聞いているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"様々物価が上昇して、中小企業の経営が悪化しているということだと思います。先の見通しも立たない中、一体どうしたらいいのだろうかというところが、様々、店長、オーナーの悩みだと思います。このハードルの高さはどのように考えているのかを伺いたいと思います。私はやはり、融資あっ旋にとどまらず、事業所への直接支援、補助制度をしっかり充実させていくことが必要だと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"別の手段での支援というお話だと考えています。支援策は様々なところをいろいろ検討させていただいていたところです。その中で一番、融資あっ旋を選択させていただいたのですけれども、要はどうしても企業からすると、いわゆる現金を持っておきたいというところがあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に対象要件なのですけれども、影響を受けていることの説明を受けるということと、粗利が５％減っているということですけれども、もう少し詳しくご説明いただきたいと思いまして、つまり、材料費は上がっているけれども価格に転嫁できない場合というのは、売上げは見た目は同じであっても、利益が上がっていないということになるわけで。","respondent":"遠藤商業・ものづくり課長","answer":"当然、企業ですと、売上げなど管理されている部分があろうかと思いますので、あと、実際にはこちらで審査していただくときに、比較的分かりやすいフォームをご用意していまして、そこに入力して、実際、何月はこの金額で売り上げました。","voiceIndex":9,"id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"それで、あえて５％とつけたのはなぜでしょうかということと、影響を受けているのだから、そこにお金を融資してというふうに、窓口を少し広げてもらいたかったという思いがあるのです。だから、そういう意味において、この数字を決めてもらいたくないということと、なぜ５％に決めたかという根拠を教えてください。その方たちも、この制度を使えるのか教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"この数字が、見えない部分ではあるのですけれども、２７５件あれば十分対応できるだろうという形で試算させていただいたです。これまで使っていただいている方々には、こちらも併せてお使いいただくことができるようになっているところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"これは文章の書き方かと思うのですけれども、１と２と分けるから分からなかったのですけれども、物価高騰の影響を受けていることによって、直近の３か月の売上げ等が落ちているなどとしていればいいのだけれども、それでは物価高騰の影響を受けていないところなど、あまりないですよね。そう思うんです。だから、ここが具体的に分からないのです。ちょっと細かいけれど、その辺はいかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"すみません。資料が大変分かりづらくて申し訳ございません。対象要件につきましては、（１）、（２）のいずれの要件にも該当しているということで対象になっておりますので、原油価格高騰の影響を受けていて、なおかつ売上高がというような形で考えていただければです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"最後に、１社に具体的には２００万円ぐらい助成するのと同じだというお話を先ほどしていましたよね。だから、今日は融資の話ですけれども、融資という意味ではなくて、いずれ直接企業に対して給付する方法もあるのかというのは、これからの課題だと思うので、そこも押さえておきたいとは思うのですけど、方法としてあるのかという思いがあるので、その辺についてはいかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"新規事業に改革するとか、今の仕事を別に変えていくとか、そういうものをいろいろ組み合わせた形で、回答させていただこうと思っているところです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"所管が違ったらあれなのですけれども、特に、区内の建設の４団体の組合の方、組合を通して組合員の方に、何かしら告知を、何かしら手当てをしたほうが私はいいのではないのかと思うのですけれども、広報・告知のことに関して、今回のことで区切っていくと、どういうふうな広報の仕方をするのか教えていただきたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"今回のこちらにつきましても、考えられる全ての方法で周知はしたいと考えていますけれども、また特に団体には個別にご説明したりというところもあります。","voiceIndex":18,"id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ所管と連携していただいて、私は特に特化はしていますけれど、建設に従事されている方たちに対しても、ぜひ周知していただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"くにば委員","kind":"質問","question":"これは、クライアントが影響を受けて出稿を絞るので、間接的に、結局、間違いなく物価高騰や円安の影響というのは受けているとは思うのです。それで、そういったところが対象になるのか、ならないのかという部分を、まず１点伺います。","respondent":"遠藤商業・ものづくり課長","answer":"その辺については広く解釈しまして、間接的であれ影響が出ているということを、当然ご説明いただく形になろうかと思いますけれども、そういう部分では広く対応したいと考えております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"くにば委員","kind":"質問","question":"今のご説明だと、やはり、先ほど藤原委員が指摘したのと同じように、例えばコロナの経営変化対策資金２０２２とか、その辺りは、コロナの影響を受けたということで、本当に幅広だったと思うのです。その両方の概念があると思うのですけれども、その辺りについての見解をお伺いしたいです。","respondent":"遠藤商業・ものづくり課長","answer":"実際、資金が必要だといった方は多分、こちらの窓口にお見えになる形になりますので、その中で、例えば「経営変化対策資金２０２２なのだけど」という形で来たときに、「実際どうですか」と、当然いろいろ話を伺うところだと思うのですけれども、その中で、「もしあれでしたら。","voiceIndex":23,"id":"exchange-010"},{"speaker":"くにば委員","kind":"意見","question":"これは両方、上乗せで使えるのかどうか、お聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"こちらは併用していただいて結構です。","voiceIndex":25,"id":"exchange-011"},{"speaker":"くにば委員","kind":"質問","question":"先日の委員会でご説明いただいた、例の、あっ旋限度額３,０００万円、３年間無利子の借換え専用資金とも併用できるということでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"恐らく、経営変化対策資金２０２１や経営変化対策資金２０２２を借りていらっしゃる方が借換え専用資金という形になろうかと思います。そちらの併用も可能です。","voiceIndex":27,"id":"exchange-012"},{"speaker":"くにば委員","kind":"確認","question":"トータルで１企業が、区の融資あっ旋という形で信用保証料の補助などを受けられるのは、マックスで６,０００万円、同時並行で受けられるということでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"借換え融資につきまして、３,０００万円が限度額ではありますけれども、それまでに借りていた額が最大となりますので、その範囲内でということであれば、同時に併用するということはできるようになっております。","voiceIndex":29,"id":"exchange-013"},{"speaker":"くにば委員","kind":"質問","question":"それで、こちらは例えば一般的な枠組みでの融資で捉えると、最初にＡ社で３,０００万円借りました。それで、Ｂ社で、３,０００万借りているというのを前提に、さらに２,０００万円を、今回のメニューで貸しました。例えば、２７５件の企業が、かなりリスクが上がってしまう。その手前で３,０００万円なり融資あっ旋を、借換え専用資金で受けている。そこのスキームに関してお伺いします。","respondent":"遠藤商業・ものづくり課長","answer":"ただ、一方、保証協会のほうで否決というのが何件か出てきているというところを考えておりますので、もちろん銀行と保証協会のそれぞれ考えがあるので、それで否決になった場合には、別のメニューということで、経営改善計画策定支援という。","voiceIndex":31,"id":"exchange-014"},{"speaker":"くにば委員","kind":"質問・要望","question":"今後も、もちろん物価高、円安の影響以外にも、様々また社会情勢のリスクで、ウクライナ侵攻によって、さらに別の社会不安が訪れて、企業がまたさらに困るといった中、発生した際には、ぜひとも引き続き、様々なご判断基準で、区で支えていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-015"},{"speaker":"西村委員","kind":"質問","question":"委員の皆様のご意見を聞いて大分理解が深まったのですけれども、円安が進行しているという、いろいろな企業からのご相談を受けていて、何か、今回ご提示いただいたこと以外の周りの緊急的なサポートは、ご検討されていたり、この後されるのかというのを伺いたくて、例えば特別な相談窓口の設置や、あとは専門家の派遣や、あとは下請事業者の方へのしわ寄せの防止に向けたような企業への巡回など。","respondent":"遠藤商業・ものづくり課長","answer":"今後いろいろ変わってくるかと思いますので、その辺の枠を増やしたところということは、今後検討していければと思っているところです。","voiceIndex":34,"id":"exchange-016"},{"speaker":"横山委員","kind":"確認","question":"少し細かいところなのですが、確認させてください。周知の方法や、あと申請の方法は一部オンライン等も取り入れていくのか、書類の簡素化などというのは実施されていくのか。全体のスケジュールを確認させてください。","respondent":"遠藤商業・ものづくり課長","answer":"こちらはオンラインでできる形を取っておりますので、そちらで、今ですと、三日、四日、直近の一日、二日は今、埋まってしまうような状況がありますので、ただ１週間はかからずにご案内できるかと考えています。","voiceIndex":36,"id":"exchange-017"},{"speaker":"横山委員","kind":"質問","question":"大変スピード感を持って、今、対応の準備をしていただいているということで、安心いたしました。もう一点、２７５件の申請を想定しているということで、こちらの受入態勢といいますか、今、直近、一日、二日ぐらいは埋まってしまうということで、三、四日ぐらいで対応できるということだったのですけれども、体制について、どのように整えているのかというところも教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"２７５件という形で組んでおりますけれども、当然、経営変化対策資金２０２２を借りる方が流れてくるということもありますので、今のところ、それほどブースを増やすなどということは大丈夫かと思っているところですけれども、今後どのような形になるかは分かりませんので、今。","voiceIndex":38,"id":"exchange-018"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"会社の経営相談も含めて、しっかり相談に乗って、それがビジネスカタリストというところで対応されているかと思うのですけれども、事業者はやはり経営を維持していくのにいっぱいになっているわけで、今も影響が出ている、秋口にはもっと影響が出るのではないかと言われている、これからの流れの中で、総合的に、１事業者の経営状態をしっかり見ていただく、また事業者に対しても、今いっときではなくて。","respondent":"遠藤商業・ものづくり課長","answer":"実際、事業者が来て、細かく経理のお話を聞きまして、場合によっては、二回、三回とおいでいただいて、いろいろ考えて一緒になって、事業者と進められればと考えているところです。","voiceIndex":40,"id":"exchange-019"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"丁寧に対応していただきたいと思います。細かいところですが、返済期間の協議の仕方なのですけれども、３０日に、中小企業支援サイトホームページにこの内容を公開いただけるということなのですが、返済期間１０年以内ということで、１年間据え置いて、実質９年での返済ということになると思うのですが、ホームページへの返済期間の案内というのが、「うち据置１２月」という表記になるのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"返済期間につきましては、１０年で、据置１２月という表現が、企業が一般的に分かるかというところがありますので、今、委員がおっしゃったような書き方で掲載する形になるかと思っているところです。","voiceIndex":42,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"一言、より一層の支援の充実を求めて、賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2928#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":14233,"voices":53}},{"id":"r04-20220527-7","meetingId":"r04-cm05","date":"2022年5月27日","dateIso":"2022-05-27","committee":"厚生委員会","time":"午前１０時０６分～午前１０時５６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第３９号議案、令和４年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第３９号議案、令和４年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"総合支援資金は、初回貸付分、延長分、再貸付分ということで、３回にわたってやれていたのですけれども、再貸付というのは、今はもうやっていないわけですよね。これ以降、再貸付はやっていないので、再貸付の件数は３,１３５件という件数でいいのかというのを確認させていただきたいのです。今どれぐらいになっているのかを、まず実績を教えてください。","respondent":"櫻木生活福祉課長","answer":"再支給が３９２名の方という実績となっております。これは、令和３年７月から令和４年４月末までの実績です。大変恐縮ですが、総合支援資金につきましては、社会福祉協議会の事業になりまして、私のほうで現時点の数値というものは把握しておりません。","voiceIndex":7,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、生活困窮者自立支援金のほうで、初回が７４９件、再支給が３９２件と、結構増えているのですね。それだけ困られている方がいるということだと思うのですけれども、それで再支給になったときに半分になってしまうのです。再支給のところで、ぐっと数が減っていく理由というのを、区はどう考えられているのか、教えてください。","respondent":"櫻木生活福祉課長","answer":"初回を受領されたときの要件と、再支給のときの要件は同じですので、３ヶ月受けられた後に、３ヶ月後に状況が変わって受給要件を満たさないという方が一定いらっしゃると認識しております。","voiceIndex":9,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。そこから生活保護に移られている方は１８人ということなのですね。単身世帯ですけれども、やはり６万円ではやり切れないから、多くが生活保護に移っているのかと思ったのですが、そうすると、では改善してきているという方のほうが多いということなのでしょうか。この予算額というのは、そして推計対象者数の１００世帯というところは、どういうふうに出されているのでしょうか。","respondent":"櫻木生活福祉課長","answer":"それを、それぞれ過去の実績を基に、実際に初回申請の方の見込み数、それから、現在、初回申請を受けていて、再支給につながるであろう方の見込み数を積み上げた金額に、先ほどの比率を掛けると、この数値となるものです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"単身世帯の方が多いということなのですね。それで、この対象者数の推計値が上回っていった場合というのは、どういう対応をされるのでしょうか。","respondent":"櫻木生活福祉課長","answer":"ある程度、予算の中でカバーできる範囲であれば対応いたしますが、大きく増えるということがあれば、また補正予算をお願いすることになると考えております。","voiceIndex":13,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり家計急変世帯のところが、また同じ厚生委員会の議会報告会での資料で言うと、４,０００世帯に対して２４０世帯という実績、申請があったということなのですけれども、今の段階ではどれぐらいになっているのかというのと、４,０００世帯と想定されていたと思うのですけれども、今回、令和４年度の非課税世帯等に対する臨時特別給付金は、令和３年度の給付金を受けた方は対象外なわけなので。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"予算上の想定と違うのではないかというお話だと思うのですが、私どもも周知等も含めてやってきたところですが、近隣区の状況を確認させていただいたところ、やはりどの区も予算の１割程度の区がほとんどということでございまして。","voiceIndex":15,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"確認","question":"５月中と言っていたのが、５月６日が確認書返送受付期限となっているので、そうすると、家計急変世帯は９月３０日までなのですけれども、要は非課税世帯等の皆さんは５月６日で受付が終わったという認識でいいのか。それで、まだ受け取られていない方というのは、前回受け取れていないので、今回、対象になってくると思うのですけれども、それがどれぐらいなのかというのを教えてください。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"未申請の方につきましては、今回、令和４年度の非課税給付金を大々的に広報しますので、併せて未申請の方への周知・注意喚起等を同じようにやっていきたいと考えています。申請期限は過ぎておりますが、申請期限を過ぎても申請できますという旨も添えて周知します。","voiceIndex":17,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"確認","question":"そうすると、令和４年度に新たに非課税世帯になった方には当然、申請書が送られると思うのですけれども、令和３年度の対象者には、未申請の６,６２５件には、新たに送付するというよりは、注意喚起、申請してくださいというやり方でやっていくということでいいかという確認と、前回、主に申請サポートとして、高齢者や障害者の方への周知・申請サポートについて。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"それと、要配慮者への申請サポートです。高齢者に関しては２０か所の在宅介護支援センター、障害者の方につきましては５か所の地域拠点相談支援センターに、協力依頼等を含めてお願いしておりまして、周知と、あとご相談があった場合の申請のサポートをお願いしています。","voiceIndex":19,"id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"意見","question":"分かりました。どちらにしても、生活困窮者自立支援金は申請期限が延長されたということと、あと令和４年度にまた非課税世帯等に臨時特別給付金が出るというのはよかったと思っているのですが、やはり対象になられていない方、非課税世帯のところで言うと、非課税世帯になる手前というのも相当厳しいです。５万９,０００世帯ということで、約６万世帯、６０億円の予算をつけているということも聞いたのです。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"今、お話のあった給付金の拡大等を区独自にというお話です。個人向けの経済的な支援や助成につきましては、区全体の観点で、都や国の動向を踏まえながら検討していくものと考えております。","voiceIndex":21,"id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ区民の実態というものをもう少し見ていただいて、非課税世帯のみならず、コロナで本当に大変な世帯、そして物価高騰で大変になっている世帯や事業者がありますので、ぜひ区独自の対策としても、今後検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"生活困窮者自立支援金のことについて伺いたいのですけれども、これまでの実績で、先ほど、単身世帯、２人世帯と３人以上世帯というもののパーセンテージをおっしゃっていただいたのですけれども、聞き取れなくて、もう一度お願いしたいと思います。","respondent":"櫻木生活福祉課長","answer":"単身世帯が６６％、２人世帯が１７％、３人以上世帯が１７％という比率です。","voiceIndex":25,"id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"その辺のところはどういうことで、これだけの額になっているのか、伺いたいのが１つです。この差というのは、区として分析などをされているのか。そういうふうに、一人ひとりに対して、どういうことになっているのか、手続きができなくてされていないなどということはないのか、その辺のところはどう考えられているのかについても伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"それと、再支給の案内ですが、初回が終わった時点で皆様にご通知申し上げて、申請を促させていただいていますので、受給者の方がご判断で申請されないということが多いのかと考えています。","voiceIndex":27,"id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこのところは、一人ひとりのところも含めて、こういう差だったり、どういう状況になっているのかというのは、私は区としても把握して分析して、つかんでいただきたいと思いますが、いかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"基本的に、ご申請されてきて、例えば収入超過や資産超過で却下です分は、ある程度、こちらでも把握できるところですが、本人から申請が来ないということですと、なかなか把握しづらいところではあります。","voiceIndex":29,"id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"それなので、すごく困窮して暮らしが大変であるにもかかわらず、そういういろいろな方もいらっしゃいますので、その辺のところは、本当にこの１０万円が、そういう方にとっては救いになる部分というのがあると思いますので、漏れている方に対してのきめ細やかな配慮で受給できるようにということで、お願いしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"ファイザー、モデルナ、あとノババックスが承認されたと思うのです。その辺、３回目と４回目があると思うのですが、概略、ワクチンの種類についてお知らせいただきたい。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"新たに承認されましたノババックスにつきましては、１回目・２回目ないし３回目接種にのみ接種が可能でございまして、４回目の対象とは現在なっておりません。","voiceIndex":33,"id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"そうすると、４回目にはノババックスは使われないということですか。全くの素人なので、３回目まではよくて、４回目が駄目だという公式見解というのは、どんなものなのですか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"薬事承認が下りていないというところで、国から通知が出ておりますので、それ以上のことは、申し訳ありませんが、現在は私では分からないです。","voiceIndex":35,"id":"exchange-015"},{"speaker":"若林委員","kind":"質問・要望","question":"国から示されているということだと思うのですが、推計値の中身というのを教えていただきたいと思います。それはもう必ず毎年、一定の世帯の方々がいて、そこに加えて、今回、いわゆる生活困窮といいますか、住民税非課税ということも、当然コロナ禍でありますというところの推計なのだろうと思いますので、どこまで明確なご答弁か分かりませんけれども、その辺の内容を教えていただきたい。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"それに、こちらは令和３年度の非課税者ということで人数になりますので、今回、世帯に引き直さなければいけません。世帯割合を掛けますと８６.７％でございましたので、そちらを非課税世帯数に掛けて算出したものです。","voiceIndex":37,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3628#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":13428,"voices":51}},{"id":"r04-20220527-9","meetingId":"r04-cm05","date":"2022年5月27日","dateIso":"2022-05-27","committee":"文教委員会","time":"午前１０時０６分～午前１０時５９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第３９号議案、令和４年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第３９号議案、令和４年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"つる委員","kind":"質問・要望","question":"細かい点の確認などもさせていただきたいと思います。低所得の子育て世帯に対する子育て世帯生活支援特別給付金なのですが、冒頭のところに、食費等の物価高騰等に直面する低所得の子育て世帯ということで、この食費というのはいわゆる家庭での食事に関わるもの等ということになるのだと思うのですが、そもそもここに充てられた部分というのは、そういう認識でよいかということをまず教えてください。","respondent":"飛田子育て応援課長","answer":"低所得の子育て世帯の給付の件ですが、政府からはやはり世界情勢、社会情勢や物価の高騰の急な対策ということで、支給が出ております。そちらには、やはり食費のところが出ております。","voiceIndex":7,"id":"exchange-001"},{"speaker":"つる委員","kind":"質問","question":"細かいことですが、いわゆる家庭での食事、食費という考え方でいいですか。色がついていなくて、何にというのは当然、給付された後というのは分からないのですけれども、そもそも今回はそういうふうに給付の設計に際しても、想定としてはそういう認識なのかというところを教えてください。","respondent":"飛田子育て応援課長","answer":"政府のほうですと、「物価の高騰等で生活に困る子育て世帯」、生活に困るというふうに書いてあります。決して食事だけとは限らないと考えられるかと思います。","voiceIndex":9,"id":"exchange-002"},{"speaker":"つる委員","kind":"確認","question":"分かりました。当然、家庭における家計のやりくりというのは食費だけではなくて、いろいろないわゆる消耗品費等もあろうかという中で、当然それは「等」とありますから、政府の想定としてもそうしたことを鑑みての、今回の児童１人当たり一律５万円ということを改めて確認させていただきました。","respondent":"飛田子育て応援課長","answer":"今回の国のほうからですと、新型コロナウイルス感染症による受給ということとなっております。すみません、今資料がありませんでしたけれども、新型コロナに対する支給ということにはなるかと。","voiceIndex":11,"id":"exchange-003"},{"speaker":"つる委員","kind":"確認","question":"財源のところの確認だったので、分かればということで。一般的な報道や国の資料等によると、これは先月の政府の総合緊急対策で、その財源がいわゆる今年度の一般予備費、それから新型コロナウイルス対策の予備費、それから予算の留保分、これを充ててそれぞれの交付金等にブランチでそれぞれ目的別に交付していくと理解しているのですが、それでよいか教えてください。","respondent":"飛田子育て応援課長","answer":"厚生労働省からは、今回これは低所得の子育て世帯に対する子育て世帯生活支援特別給付金というところで、こちらのほうが出ております。","voiceIndex":13,"id":"exchange-004"},{"speaker":"つる委員","kind":"質問・要望","question":"細かい確認なので、また実際においては、支給のほうがすごくウエートとしては大切なのかなと思いながら、要は国から１０分の１０で下りてきているというお金について、確実に品川区の対象世帯にしっかりと届くということが大切かと思いますので、ぜひそこはミスなく、最近はいろいろな自治体で送金に当たってのいろいろな報道がありましたから、そうしたこともしっかりと注意しながら。","respondent":"初貝保育教育運営担当課長、中元保育支援課長","answer":"この物価高騰のところで、事業者からそういった声が届いているかですけれども、現在のところ、委託している公設民営の事業者から、食材高騰で措置をというのは届いていない状況です。私立保育園等につきましても、特に業者から物価高騰による影響等のご相談というのは、まだ現段階では届いていないです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"つる委員","kind":"質問・要望","question":"ありがとうございました。今ご答弁ありましたけれども、ただ当然無償化の中で見ていける部分と、そうではない部分がある。結果として保護者負担増にならない手立てという視点で、財源はどこに求めるかというのは先ほど申し上げたとおりでありますけれども、しっかりと負担増にならないような手立て、手当をしっかりとその時においてはやっていただきことを改めて要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"特別給付金についてなのですが、対象者のうち直近で収入が減少している子育て世帯という言葉がありますけれども、この判断基準を教えていただきたいのと、それと保育園のコロナ対策等の補正予算についてなのですが、現在の保育園・幼稚園での感染状況がどうなっているか、改めて伺いたいと思います。","respondent":"飛田子育て応援課長、初貝保育教育運営担当課長、中元保育支援課長","answer":"家庭の子育てのほうの給付、生活困窮というところでは、こちらのほうは令和２年の２月以降、新型コロナウイルスがはやり出した以降から。５月は、区立保育園が３３名と幼稚園が１名、合計３４名ということで、こちらが５月１９日現在の数字になっております。４月の合計が２７０人です。５月は、５月１９日時点の数字につきまして、私立保育園が６３人、私立幼稚園が１５人、合計７８人という数字となっています。","voiceIndex":20,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"減ってきているとは言え、まだまだたくさんいらっしゃるということで、今回の補正予算は重要かと思います。それと認証保育園については、臨時休園等に伴う支援事業ということでありますけれども、それ以外の施設はどのような感じかというのをお伺いしたいのですが、認可保育園等はどのような感じなのかというのを教えていただきたいというのが１点です。","respondent":"中元保育支援課長、飛田子育て応援課長","answer":"今回の補助事業の対象ですが、私立の認可保育所のほかに、地域型保育事業ですとか認可外保育施設、オアシスルームなどもそれぞれ対象となっているところです。もちろんそういう税情報が分かって、ちょうど今回実態調査がなくなります。そういう通知がありますので、そういうところと併せて、対象の方にも周知はしていきたいと考えております。","voiceIndex":24,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"学校給食関連三団体協議会というところが、５月２０日に政府に対して、先ほどもありましたコロナの対応、地方創生臨時交付金の活用で学校給食費の負担軽減をしてほしいというような要望もされたという報道もありますし、首相も昨日か何かの記者会見でそういう措置をしてほしいというようなことも述べたということも報道されていましたので。","respondent":"初貝保育教育運営担当課長","answer":"今、ご指摘いただいたところ、そういったご意見があったということは伝えさせていただきたいと思います。","voiceIndex":27,"id":"exchange-009"},{"speaker":"吉田委員","kind":"確認","question":"今の質疑の中でも直近の収入が減少した方とか、申請が必要な方にぜひきちんとご案内が行くようにという内容のものでしたけれども、同様の趣旨の質問になるのですが、これまでもひとり親世帯についても、やはり急にどうしてもいろいろな事情でひとり親になったとか、それから必ずこういう時には確認させていただいているのですけれども、ＤＶの被害者で、厳密に言えばひとり親ではないのかもしれないけれども。","respondent":"飛田子育て応援課長","answer":"実際、子育て応援課にも相談があります。場合によっては家庭には書類を発送せず、直接お会いして書類等を渡して、対応しています。","voiceIndex":30,"id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。だからなかなか相談に行けない。もし加害者が来た時にも、この人には情報を出さないというようにしっかり対応がされていると思うのです。だからその辺の情報というのは、同じ区の中でも共有というのは難しいのでしょうか。できたら、そういうのはもう戸籍住民課のほうでは把握しているわけだから、そういう方たちへのご案内は何か別の手段はないのかと思って、現状どうなのか教えてください。","respondent":"飛田子育て応援課長","answer":"実際、戸籍住民課のほうにもご相談とかそういう書類があります。その時には戸籍住民課のほうにもご協力いただきまして、子育て応援課のチラシを配布してもらうようにお願いしています。","voiceIndex":32,"id":"exchange-011"},{"speaker":"吉田委員","kind":"確認","question":"では中で情報共有というより、戸籍住民課にそういう相談が来た時には、こういう制度もありますよという形ですよね。そうなると、既に戸籍住民課で把握している人たちへは、そういうお知らせが皆行っていると理解してもいいのでしょうか。確認させてください。","respondent":"飛田子育て応援課長","answer":"戸籍住民課のほうでも、やはりちょっと怪しいというか心配なケース等の申し出があった場合は、直接戸籍住民課の職員が子育て応援課に連れてきてくれまして、そこでお話を受けるということもしております。","voiceIndex":34,"id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから戸籍住民課のほうがアンテナを高く立てて、そういうふうにこの方は子育て応援課に行ったほうがいいということであれば、場合によっては付き添ってみたいな感じなのでしょうか。どういう形か具体的に言いにくいのですけれども、特別にそういう方たちをひとり親とみなして、いろいろな支援をその方たちに既にしているという人数をもし差支えなければ教えていただきたいのですが、いかがでしょうか。","respondent":"飛田子育て応援課長","answer":"やはりそういういろいろな心配がある方、また今回この給付というのはこの何年か続いております。ですので、受けている家庭環境等にいろいろ問題がある方は、そういう意味では逆に国のほうも別に周知をしておりますので、少しは相談しやすくなっている状況かと考えられます。","voiceIndex":36,"id":"exchange-013"},{"speaker":"吉田委員","kind":"確認","question":"先ほどおっしゃった数字が、今ひとり親家庭、ＤＶ被害者としてのひとり親家庭ではなくて、ひとり親家庭全体として把握している数でよいのですか。すみません、もう一回確認させてください。","respondent":"飛田子育て応援課長","answer":"今言ったのは児童扶養手当の受給者数としまして、今回ひとり親世帯分としましては、２,３３９名の１,６５７世帯というところです。ＤＶ等ですが、そちらのほうは相談件数としましては、現在夫婦関係などの相談内容からいきますと、令和３年度ですと１２３名の相談がありました。","voiceIndex":38,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。先ほどご相談は戸籍住民課のほうから子育て応援課のほうに意識的にやっているということですけれども、そういうことが例えばシステムとしてもう確立しているような自治体というのはないのでしょうか。もし把握していらっしゃるようだったら教えていただきたいし、そういうのは調べたことがないということであればそういうことでお答えいただきたいのですけれども、その辺はいかがでしょうか。","respondent":"飛田子育て応援課長","answer":"システム上でというところでは、まだ調べておりませんし、今の段階ではなかなか難しいのかとは考えております。","voiceIndex":40,"id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"難しいのは承知の上で、でもそういう仕組みができたらいいかなと思って質問をさせていただきました。同じ区の中でも、そういうかなりセンシティブな情報については共有しにくいというのは承知なのですけれども、こういう問題はこれからも必ず出てきます。最後は要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"周知がやはり大事になってくると思うのですけれども、ここでの周知方法は、送付。送付はもう別居したりとか、逃げてしまった場合というのは受け取れないと思うのです。ここに周知方法で、ＴｗｉｔｔｅｒとかＬＩＮＥとかＦａｃｅｂｏｏｋもいいと思いますけれども、それが挙がっていないのがちょっともったいないなと思うのですが、そこはぜひ改善していただければと思いますが、いかがでしょうか。","respondent":"飛田子育て応援課長","answer":"すみません、そちらのほうは漏らしました。昨年度も区がやっていますパパママ応援アプリやＴｗｉｔｔｅｒのほうでも周知させていただきました。今年も同じように、そちらのほうでも周知していく予定です。","voiceIndex":44,"id":"exchange-017"},{"speaker":"松本委員","kind":"質問","question":"ぜひお願いします。2)の令和４年度分の住民税均等割が非課税の子育て世帯という方たちの中で、基準日後に別居や離婚などをしてしまったパターン、昨年の臨時特別給付金と同じような状況になり得る可能性があるのかなと思うのですが、そこのところの対策というのはどのようになっていますでしょうか。","respondent":"飛田子育て応援課長","answer":"実際にその場合のそういう方は、3)に当てはまるのかなと考えております。やはり新型コロナウイルス感染症の影響を受けて、また離婚などで収入が減ってしまったという場合はこちらのほうで救うことはできるのかなと考えております。","voiceIndex":46,"id":"exchange-018"},{"speaker":"松本委員","kind":"質問","question":"救うというのは、どういう仕組みで救えるというお考えでしょうか。","respondent":"飛田子育て応援課長","answer":"相談に来た方に対して、お給料の面で令和２年２月以降の収入が減少してしまったとか、そういうところで何かしら影響があった場合、この基準の範囲以下になってしまった場合には申請をしていただければ、支給の対象になります。","voiceIndex":48,"id":"exchange-019"},{"speaker":"松本委員","kind":"質問・要望","question":"分かりました。そこはあくまで要望で終わります。もう一点、保育所等における補助金のほうなのですけれども、これは補正予算で上がってきたというのはどういうことなのかというのが一つ疑問で、これらは、基本的にもう２０２０年からコロナの問題が出てきているわけで、当初予算で上がらなくて補正予算で上がってきたのはどういう理由なのでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"今回補正予算で上げさせていただいたのは、当初予算を組む段階で、この補助金のところの国のスキームがまだ固まっていなかったということで、その辺りで判断をしまして、それが今年度に入ってから明確に示されたということで、財源も確保できるというところで。","voiceIndex":50,"id":"exchange-020"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"様々ご意見ありましたので、要望になるのですけれども、生活支援特別給付金に関しまして、誤送金、それから漏れがなくというお話がありましたけれども、これはやはりしっかり気を付けていただいて、あった場合にはしっかりと対応していただきたいと考えています。これは要望なのですけれども、何かご意見があればお願いしたいと思います。","respondent":"飛田子育て応援課長","answer":"様々な相談がこちらのほうに来ます。ですので、その方々が安心して生活できるように、こちらのほうも対応していきたいと考えております。","voiceIndex":53,"id":"exchange-021"},{"speaker":"つる委員","kind":"質問","question":"だから、元々の源流はどこから来ているのかなというところの整理になっているので、それは使えないけれども、ましてやこの議案に上がっていない参考というところで先ほど伺わせていただいたところで、その根っこというか大本というか、そこがどこなのかというところであって、今言っていただいたのは予算書に書いてあるので分かります。それが分かるのであれば、教えてください、なければご答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"重ねて、学校給食費の負担軽減の予算等も追加で速やかに具体化するよう求めつつ、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-023"}]},{"id":"topic-02","title":"委員長報告","agenda":"委員長報告","exchanges":[{"speaker":"あくつ委員","kind":"意見","question":"正副でまとめします。以上で、委員長報告についてを終了いたします。本日がこのメンバーによる最後の委員会となりますので、正副委員長よりご挨拶申し上げます。湯澤副委員長からお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-024"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"微力ではありましたが、この１年、皆様とともにあくつ委員長を支えさせていただきながら審議をさせていただきましたことに感謝申し上げます。理事者の皆様におかれましては、本日でこの委員による文教委員会は終わりますけれども、引き続き区民のために、そして未来を担う子どもたちのためにしっかりと区政運営をしていただきたいと考えています。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5066#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":16148,"voices":72}},{"id":"r04-20220527-5","meetingId":"r04-cm05","date":"2022年5月27日","dateIso":"2022-05-27","committee":"総務委員会","time":"午前１１時１０分～午前１１時４６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"説明に入る前に、所管委員会における審査結果","agenda":"説明に入る前に、所管委員会における審査結果","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"事業所あるいは区民への支援を、独自にもっと区がやるべきだと考えております。１年間の給食費は、小学生で大体５万円前後だし、中学生ではたしか６万円を超えるという負担だったと思うのですが、既に重いものになっていると思います。そこで、物価高騰の影響を学校給食費の値上げで対応するべきではないと。そういう補正をなぜ考えなかったのか、まず伺いたいと思います。","respondent":"黒田財政課長","answer":"今、委員からご指摘ありましたようなものにつきましては、国のほうで、コロナ禍における原油価格・物価高騰等総合緊急対策というのを定めまして、様々な対策を取る中で、当然、自治体の役割というのも出てまいりますので、そういった中で、引き続き検討し。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"住民税非課税世帯等臨時特別給付金は、１回きりだと。だから、今回補正予算が組まれたからといって、２回目が出るわけではないというのは伺っておりましたので、１回だけですとお返事はしておいたのですが、今の区民の皆さんの家計の実態から見れば、１回の給付で足りるという状況ではないと思うのです。そうした補正予算は検討されなかったのでしょうか、伺います。この点も伺いたいと思います。","respondent":"黒田財政課長","answer":"どういった形の生活支援がいいかというところは、国の経済対策によるところもありますので、そういった中で引き続き検討して、実施できるところは実施していくという形で進めていきたいと思っているところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"このことに対する要望は強いものがあると思います。そこで、今このタイミングにこそ、国に対して消費税の引下げを区として求めるべきだと考えますが、この点、いかがでしょうか。だから、このタイミングでそれをやるのかという意味で、消費税の減税とともにインボイスの導入の中止を、このタイミングで求めるべきではないかと思うのですけれども、この点はいかがでしょうか。","respondent":"黒田財政課長","answer":"インボイスにつきましても、消費税を適切に税制度として運用していくための制度と認識していますので、中止を求めるということを国にするという考えはございません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"今の区民の家計にしろ、事業者の方の営業にしろ、非常に特別に厳しい実態があり、そういう制度の改善を、消費税、インボイスについて求めていると思うのです。今は、実態の厳しさからして、そういうタイミングではないかと私は非常に思うのですけれども、区としてはそのようにお考えにはなりませんか。この点、伺っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"これはまた委員会と行政とのことになってしまうのですけれども、今回のような補正予算のときには、例えば各委員会終了後に少し時間を空けてもらって、各委員会の状況を確認させてもらうか、あるいは、各委員会の理事者の方にも来ていただいて、委員会の状況とかを知らせていただくように求めたいというのが、まずあるのですけれども、それはいいです。これから質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-005"},{"speaker":"田中委員","kind":"意見","question":"厚生委員会の部分の住民税非課税世帯等に対する臨時特別給付金については、傍聴できたので分かりました。ただ１点、相談窓口等のところの相談ブースについてですが、前回も第二庁舎の３階のところだったと思うのですけれども、そこから中小企業センターに移動したのではなかったかと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、当事者の方たちがすごく相談しにくい場所になっていて、マイナンバーの申請のところ、交付のところといいますか、そこと並んでいる相談窓口で、とても使いづらい、そしてまた、話が全部聞こえてしまうような感じになっていたので、そこは改善を求めたいということで、ここを要望したいのですけれども、何かあればいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"分かります。分かりますけれども、要望と、できれば……。","respondent":"渡辺委員長","answer":"答えられるか、できないかは、議員として踏まえていかないと成り立たないので、配慮はお願いします。","voiceIndex":22,"id":"exchange-008"},{"speaker":"田中委員","kind":"確認","question":"総合審査をする側として、きちんとそういうところも確認をしてから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"なので、周知についてきちんと、ＤＶのところもそうですけれども、必要な人に届くような周知をしてほしいという要望です。それに関して、もし「こういうことをしています」などがあれば、お知らせください。","respondent":"黒田財政課長","answer":"中小企業事業資金融資あっせんも、一般的な広報に加えて、特に商業・ものづくり課では産業の関係団体と連携を取りますので、そういったところを通じて、事業の実施について周知に努めてまいりたいと考えています。","voiceIndex":28,"id":"exchange-010"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですから、これでもたしか自己申請ではなくて、子育ての云々に関しても、国の絡んでいる給付金というのは、役所でもう情報が分かっているわけだから、対象者に送られる。要するに、そういうことでいいのですよね。分からなければ、逆にあまり広く周知をしないで、しっかり届くところに届くような仕組みにしてほしいということを要望したいのですけれども、何か教えてもらえれば。","respondent":"黒田財政課長","answer":"ただ、また給付が受けられるのではないかというふうに思われるというご指摘もありますので、これから令和４年度の事業を実施する中で、事業の周知の中で、一度給付された方は対象にならないといった旨を含めて、誤解のないように事業を進められるように。","voiceIndex":31,"id":"exchange-011"},{"speaker":"渡部委員","kind":"質問","question":"国のほうの問題なので、あれですけれども、例えば子どもの方は、新たなものが行くではないですか。それと混同してしまっている人が地域の人でいるのです。同時期の国のほうからの発表で。ですから、こちらもプッシュ型でいくのであれば、特段問題はないかと思うのですが、一応、そういうことが地域であるということだけお耳に入れします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、「私はどうしてもらえないのか、連絡が来ない」というと、連絡が我々に来るのです。区に、やってくれとは言えません。そういう方が私はたくさんいらっしゃるのではないかと思いますので、その辺についても区で何かお考えがあるのか、国にきちんとそのように申し上げるような対応を考えておられるのかについて、先ほどの消費者物価、企業物価も含めて、支援についても含めて教えてください。","respondent":"黒田財政課長","answer":"住民税非課税世帯等への臨時特別給付金に限らず、こういった福祉的な制度は一定程度、基準を定めて行われるという意味では、必ずどこかで線を引かれるという意味では、もちろんその対応から、対象外となる方がいらっしゃるというところは重々承知しておりますが。","voiceIndex":35,"id":"exchange-013"},{"speaker":"たけうち副委員長","kind":"確認","question":"産業経済費のところで、中小企業の融資あっせんのところですけれども、一応確認ですが、これは国庫補助とか都の財源なく、区の基金を使ってやるということでよろしいでしょうか。","respondent":"黒田財政課長","answer":"この事業につきましては、財政調整基金を、一般財源を原資として実施するという事業です。","voiceIndex":38,"id":"exchange-014"},{"speaker":"たけうち副委員長","kind":"質問","question":"さっき、おくの委員からもあったのですけれども、そのときの答弁で、今、国で補正予算が組まれて、今度６月ぐらいには、さっき言った給食費をもし上げる場合に、それを上げないようなことに区で使えると。それは財源が国とかから出ていないわけですけれども、それを待たずに対応したというのは、ここに一つお考えがあるのかと思います。もしその辺が分かれば教えてください。","respondent":"黒田財政課長","answer":"ご指摘ありました国の臨時交付金につきましては、東京都を通じて各自治体に、各区に交付されますので、これは間もなくです。今、東京都も補正予算を編成しておりますので、そういったところは国の事業出資なども鑑みながら、今後検討してまいりたいと考えております。","voiceIndex":40,"id":"exchange-015"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"そしてまた、さっき行われた文教委員会の中でも、我が会派の委員から要望させていただきましたけれども、今のところ給食費の値上げをするかどうかというお話は出ていませんが、物価が上がってそういう形になったならば、保護者の負担にならないように、そうしたものを活用して、ぜひやっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2232#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":12809,"voices":56}},{"id":"r04-20220527-10","meetingId":"r04-cm05","date":"2022年5月27日","dateIso":"2022-05-27","committee":"議会運営委員会","time":"午後 １時３０分～午後 １時３３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5466#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":1513,"voices":11}},{"id":"r04-20220606-6","meetingId":"r04-cm06","date":"2022年6月6日","dateIso":"2022-06-06","committee":"区民委員会","time":"午後 １時００分～午後 ２時４４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"商業・ものづくり課と地域活動課に関わって、少々お伺いいたします。商業・ものづくり課のほうから。事業者の皆さんも、先が見通せないわけですから、融資だけでは私としては不十分ではないかと思います。この点がいかがでしょうかということをお伺いしたいと思います。これが１点です。この点、いかがでしょうかということをお伺いしたいのが１つです。この点をお伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長、川島地域活動課長","answer":"今後もちょっとどのように変わるか分からない部分がありますので、そこにつきましては、社会の情勢などを見ながら、今後必要な支援は継続したいと考えているところです。あまり軽くても、もしかすると危ないのかもしれませんし、ちょっと現場の声とか地域センターのほうの声もありますし、それから利用者のいろいろな声もあると思いますので、そちらのほうはその部分もちょっと確認しないと、今。","voiceIndex":32,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"荏原第一地域センターのほう、その表示の件にしろ、また見て、いろいろ工夫していただきたいと思います。要望しておきます。要望します。実際、必要にされている声も伺っておりますので、融資で十分とは決して思わないで、より広い視野で見て、直接支援の必要性も視野に入れながら考えていただきたいと思うのですけれども、考えていらっしゃると思うのですが、この点、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"委員のおっしゃるとおり、新規の患者数というのがそれほど、最近は減っているところではありますけれども、過去に比べると、まだ多い状態だというのは認識しています。","voiceIndex":35,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"やはり、現状は考えてないとしても、私としては、融資だけではやっていけないのだと、見通しもない中で、借金をするわけにはいかないという声も伺っておりますので、私の要望としては、直接支援も視野に入れたいろいろな援助の仕方というか支援の仕方があるのだということを視野に入れて、支援を考えていただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-003"},{"speaker":"藤原委員","kind":"質問・要望","question":"私はこの条例制定したということは、とても大事なことだと思っていますし、条例にのっとっていろいろな施策をしていくものだと思っているのですけれども、今日は具体的なことは伺いませんが、課長がこの条例というものをどう考えているかを教えていただけますか。それともう１点。でも例えば人数が１人ですよね。もう１つは予算額が４１７万５,０００円。担当の職員も１人しかいないと。","respondent":"森田生活安全担当課長、中西八潮まちづくり担当課長","answer":"その中で罰則等もありますので、それについては厳格に、また先ほど申しましたように、様々な責務に基づいて、様々な方々がその条例の方向性を求めてつくったものですので、そのようなことになるように進めていくのが。それに当たっては、庁内の様々な部署の横串も刺していきたいと考えておりますので、私が中心となって八潮地区をひとつ盛り上げていきたいと考えているところです。","voiceIndex":38,"id":"exchange-004"},{"speaker":"藤原委員","kind":"確認","question":"八潮、期待しています。初めてできる課なので、いろいろ悩んで、いろいろ苦労することがあると思いますが、八潮がこういうふうになったというのを、すごく私も期待しておりますので、１年間よろしくお願いいたします。課長。今日、改めて確認しましたので、常任委員会で出てこなくても、決特、予特でこれはしっかりやっていこうと、今からエントリーしておきますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-005"},{"speaker":"松本委員","kind":"質問","question":"事務事業概要なので、あまり細かくは言いたくないのですけれども、先ほど空き店舗を活用した支援事業が３年度で終了したということで、この辺りも終了したものはほかのところで吸収というふうな話もありましたが、この空き店舗についての、区としてどう考えられているのかというところを伺えればと思います。お願いします。","respondent":"遠藤商業・ものづくり課長","answer":"空き店舗活用支援事業ということで、まずは９５ページというところで、令和３年度をもって終了とさせていただいたところです。","voiceIndex":43,"id":"exchange-006"},{"speaker":"松本委員","kind":"質問・要望","question":"空き店舗に対する支援というところでは、今のトイレとか入り口というのが、他区では家賃の支援とかもやっているようなところもあるように聞いていまして、こういったところは、現状では検討されていないのか、ぜひ、検討していただきたいと思うのですが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"空き店舗の活用ということで、ほかの区でも様々な事業をやっていることを確認しています。私どもも研究いたしまして、空き店舗を少しでもなくすような形の施策を考えられるよう、今後も研究させていただければと考えています。","voiceIndex":45,"id":"exchange-007"},{"speaker":"塚本委員","kind":"確認","question":"先ほど、八潮のまちづくりの件でご質疑があったのですけれども、昨年度というか、前回の建設委員会で報告があって、当初、都市計画課の所管なのかとそのときは認識をしていたのですけれども、今年度から新しい課ができて、まず所管として、先ほど地域振興部の八潮まちづくり担当が中心となって、横串を刺していくということになりましたけれども、まず所管として。","respondent":"中西八潮まちづくり担当課長","answer":"一応あちらが昨年度、コロナでワークショップ等が開けなかったということで、今年度もまだ続いているというところで認識をしています。","voiceIndex":47,"id":"exchange-008"},{"speaker":"塚本委員","kind":"意見","question":"そういう当事者、八潮の方々、いろいろな方々とこれまで話し合いをしながら、まちづくり協議会とかでしてきたのですけれども、そこら辺の話というのはどういうふうに、いわゆる全庁的ないろいろなところとの関わりの中で、今回、この新設された新しい課が、どういう形でというようなことは、当事者の八潮の方々とはどういう整理になっているのかというのを、もう一度だけ詳しくお話ししていただけますか。","respondent":"中西八潮まちづくり担当課長","answer":"その部分です。確かに地域の方からどちらなのだというご指摘を実際にいただいたこともあります。ただ、ここで私が、八潮地域センター所長も事務取扱で担わせていただいておりますので、その辺りは今現在でも丁寧にお話をしながら、理解をいただくように進めているところです。","voiceIndex":49,"id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2930#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":30844,"voices":73}},{"id":"r04-20220606-7","meetingId":"r04-cm06","date":"2022年6月6日","dateIso":"2022-06-06","committee":"厚生委員会","time":"午後 １時００分～午後 ３時２３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"障害者福祉課から障害者支援課に変わられましたけれども、中身としては変わっていないのか、名前が変わったことで何か特徴みたいなものがあるのか、伺いたいのが１点です。それとぐるっぽですが、１０月から運営事業者が変更になる、その引継ぎが４月からされているということですけれど、前事業者の職員はどれぐらい残られるのか、今の時点で分かっているのでしょうか。","respondent":"松山障害者支援課長、川崎障害者施策推進課長","answer":"２点目の手話についてのご質問です。新たに今年度から行います子ども向けの手話講座ですけれども、夏休みを予定しています。事業者向けの手話出前講座ですけれども、まず、企業等に呼びかけを行いまして、参加を促しています。昨年につきましては、やはりコロナの感染拡大ということで、書面開催とさせていただきました。今年度は、コロナの影響も鑑みながら、対面での開催も検討させていただきたいと考えています。","voiceIndex":26,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"障害福祉計画と障害児福祉計画のところで先ほどもご説明があったのですけれど、１３７ページのところでは、品川区障害者計画が令和５年度までで、第６期品川区障害福祉計画も令和５年度まで、第２期品川区障害児福祉計画も令和５年までという計画なので、３つの計画が、令和６年度から新しい期になるということで、先ほどアンケートやヒアリングを行うということだったのですけれど。","respondent":"川崎障害者施策推進課長","answer":"３つの計画が令和６年度からということになります。は障害福祉計画、そして障害児福祉計画のほうのヒアリング、アンケートを行ってまいります。","voiceIndex":29,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"介護保険の計画策定に向けては、ニーズ調査を行うようにと厚生労働省からも求められると思うのですけれど、令和２年度にもアンケートをやりましたと高齢者福祉課長が答弁されているのですけれど、介護保険のほうも今、そういう計画策定、新たな第九期に向けてアンケート等は動き出しているのか、あわせて伺わせてください。","respondent":"川崎障害者施策推進課長、菅野高齢者福祉課長","answer":"おっしゃるとおり、策定委員会のほうで３つの計画について実施してまいります。私からは、介護保険のニーズ調査につきましてご説明します。前回の第八期に向けてのときも、２０２０年１月から２月に、介護予防・日常生活圏域ニーズ調査を行っております。","voiceIndex":31,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。生活保護のほうで伺いたいのですけれども、世帯数でいうと、令和２年度で４,５４７世帯、令和３年度で４,４６４世帯。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"すみません。生活保護の数がどうなっているかということと、今のこの状況の下での区民の暮らしというか、困窮されている方が多くいらっしゃるのではないかと思うのですけれども、その辺は区としてはどのようにつかまれているでしょうか。","respondent":"櫻木生活福祉課長","answer":"直近の世帯数ですが、６月１日時点で４,３４６世帯です。最近の相談状況ですが、それほど増えてもなく、減ってもなくという形です。","voiceIndex":36,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。暮らし・しごと応援センターですけれど、前回の事務事業概要のとき、本当に困窮されている方が多いので、職員を増やして対応してほしいということもお願いしたのですけれども、その前が４人、それがこの間聞いた時には６人になって、さらに増やしてもらいたいと思っているのですけれど、その職員増の部分ではどうお考えなのか、伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"暮らし・しごと応援センターの人数ですが、いわゆる相談を担当している職員としては、今年度も６名という形です。今後の相談件数もしくは内容等を踏まえながら、関係当局と調整しながら、人数増については検討してまいりたいと思います。","voiceIndex":38,"id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"意見","question":"１３８ページに障害者福祉の重点施策がありまして、3)療育支援体制の充実のところで、連携を強化し、云々のネットワークを構築するとあります。これは、令和３年度にどのような課題があって、それを令和４年度では、この連携についてどのように強化、改善していこうということなのか、重点施策ですので、そこを１つだけお願いします。","respondent":"松山障害者支援課長","answer":"委員お尋ねの１３８ページ、療育支援体制の充実ですけれども、こちらは、区内で１か所の児童発達支援センターである品川児童学園の機能を充実させるとともに、新たに戸越地区の児童発達支援センターの基本計画も、今年度検討することになっております。","voiceIndex":41,"id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問","question":"地域自立支援協議会や現場の声をお聞きになってということですが、私は障害者支援課になり期待をしていて、教育との連携はやはり、こちらがイニシアチブというかリーダーシップをとって、特に就学したときの連携という重要性はあると思うのです。そこについて、一つお願いします。","respondent":"松山障害者支援課長","answer":"現場でどういった工夫ができるのか、お互いの理解を進められるのかというところでは、こつこつと連絡会へ出かけていって、教育委員会のほうの校長会ですとか、保育関係の園長会ですとか、制度の説明をさせていただいたり、地道なところから一歩一歩。","voiceIndex":43,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"期待しておりますので、ぜひ頑張って、事業を進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-009"},{"speaker":"せお委員","kind":"質問・要望","question":"２点お聞かせいただきたいのですけれど、１５０ページの手帳の交付のところで、身体障害者手帳と愛の手帳とあるのですけれど、こちらを両方持っている方の数の把握はされているのか。数は今分からなくてもいいのですけれど、そこの把握はされているかということが１点。","respondent":"松山障害者支援課長","answer":"在宅人工呼吸器使用者への非常用電源の給付状況です。今のところ、私ども障害者支援課で作成しましたご案内チラシを、保健センターと私どもの障害者支援課でご自宅にお持ちして、ご説明すると。","voiceIndex":47,"id":"exchange-010"},{"speaker":"せお委員","kind":"質問・要望","question":"そこは要望です。就学もそうですし、移動支援とかそういったところも、なかなか支援がつながっていかないということが見えますので、その数を把握しているのであれば、そこから見えてくるものだったり、少し考えていってほしいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-011"},{"speaker":"あくつ副委員長","kind":"確認","question":"私から１点だけ伺います。ここについて、今後この稼働はいつ頃なのか、例えば、社会的孤立を防止するとか、断らない相談体制とか、いわゆる伴走型支援とか、よく言われますけれども、今もう既に動いているものがこれだということなのか、それとも、何年何月時点をもって動かしますというお考えなのか、今までも、もしかしたら確認があったかもしれませんが、品川区のお考えを改めて伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"関係するスタッフが集まって、連携して解決に当たるにも、部署によって関わりの濃淡はどうしても出てくるのですけれども、現行の制度では、ピンポイントでここの所管でやれると決められないような課題が多くなってきているので。","voiceIndex":51,"id":"exchange-012"},{"speaker":"あくつ副委員長","kind":"質問","question":"おっしゃることはよく分かりました。相談支援というところが非常にクローズアップされているので、イメージとして、重層的支援体制の窓口ができるということではなくて、職員の皆さんがそういう意識を持たれて、一つのところに相談があれば、ネットワークでつながるようなイメージ、ということでよろしいのでしょうか。","respondent":"寺嶋福祉計画課長","answer":"副委員長がおっしゃったとおりで、専門のここの窓口に連絡してください、ではなく、受け取ったところがあったら今回検討しているメンバーが一堂に集まって、その課題について検討するというのが、品川区で今、目指している形です。","voiceIndex":53,"id":"exchange-013"}]},{"id":"topic-02","title":"事務事業概要を、再度議題に供します。 再度のご案内ですが、この事務事業概要につきましては、例年に倣い、新しい委員で構成される最初の委員会で、各所管の事務","agenda":"事務事業概要を、再度議題に供します。 再度のご案内ですが、この事務事業概要につきましては、例年に倣い、新しい委員で構成される最初の委員会で、各所管の事務","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"保健師のところですけれども、本当に長いことコロナで、先ほど２年半とおっしゃっていましたけれど、それだけの間、本当に保健師の皆さんの懸命な奮闘があったのだと思いますけれども、今年度、保健師を５人採用するとおっしゃっていて、それがこの２ページの職員配置の表でどう反映されているのか、ここで分かるのかどうか、分かれば教えていただきたいと思います。","respondent":"柏木品川保健センター所長、坂野保健予防課長","answer":"私からは、今年度の新規採用職員の配置状況です。新規採用職員は５名おりまして、配置先は、保健予防課に１名、品川保健センター２名、大井保健センター１名、荏原保健センター１名となっています。保健師の残業時間ですが、具体的な数字は、今日は資料がないのでお答えできません。申し訳ありません。","voiceIndex":83,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。保健師のことはありがとうあります。第６波での総括というのは、出していただきたいと思うのですけれど、出される予定はあるのか伺いたいと思います。１２１ページを見ると、倍以上ですね。これは、予防といいますか、そういったことに向けての周知というのは、さらに強めていくことになるのか、これだけ増えているということを見て、区としてはどういう対応をされるのか、伺いたいと思います。","respondent":"坂野保健予防課長","answer":"これは引き続き、ご指摘どおり周知を図っていく必要があると思っていますので、引き続き取り組んでまいりたいと考えております。","voiceIndex":86,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3630#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":37189,"voices":89}},{"id":"r04-20220606-8","meetingId":"r04-cm06","date":"2022年6月6日","dateIso":"2022-06-06","committee":"建設委員会","time":"午後 １時００分～午後 ２時５３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"提案","question":"１つ簡単にお聞きしたいこと、提案といいましょうか、４８ページの公営住宅のところですけれども、公営住宅の応募状況ということで全部の倍率が書かれているのですが、区内の倍率も書ければぜひ書いていただきたいということで、いかがでしょうか。こうしたことで住民の被害をより明確に捉えるために、この測定箇所を増やす必要もあるのではないかと思うのですが、増設の考えはいかがでしょうか。","respondent":"竹田住宅課長、鈴木都市計画課長、多並都市開発課長","answer":"自治体別の倍率を掲載する考えはございません。航空機騒音の区としての測定局の増設についてのお尋ねですが、基本的には運航が開始された２ルートの直下にそれぞれ設けているというところと。そういうまちづくりの継続も含めて、これから進めていくものと理解しているところであります。","voiceIndex":34,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"もう一点だけ、コミュニティバスについて２９ページに出ておりましたけれども、先日区の３か年の総合実施計画が出されたところで、コミュニティバスを実施していくというところで、今大井ルートが試行運行されておりますけれども、試行運行を４年間やった後、私の認識ではほかの２ルートが立証されていくのかなと思っていたのですが。","respondent":"多並都市開発課長、中道まちづくり立体化担当課長、鈴木都市計画課長","answer":"今後につきましても、やはり地域の方と一緒に考えながら、長く持続可能と今いただいたような形で。中間説明会を求めるべきではないかですけれども、区としましては。コミュニティバスにつきましては、３ルートの候補ルート案、１１の指標で導入効果の高い地域３ルートを。","voiceIndex":38,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"２９号線、特定整備路線のところはぜひ最新の情報を得ていただいて、都に求めて情報を掲載していただけたらと思います。本来そういったことも含めたスケジュール感になっていると思うのですが、そこのところを確認させていただきたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"マシンの点検についてですが、当初調査掘進は３月に終わる予定のところ、今現在です。こちらのほうは安全に掘り進めるために、一度マシンを点検したほうがよいという判断があったと聞いてあります。","voiceIndex":43,"id":"exchange-003"},{"speaker":"こんの委員","kind":"質問","question":"１点だけ、参考までに伺いたいと思います。２９ページの公共交通の件で、令和４年度の事業予定の中で、先ほどのご説明で利用者連絡会議を実施しますというご説明をいただいたのですが、いつ頃、またこの利用者という人たち、ここに来る方たちはどのような方たちなのか、その辺を参考までに伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"連絡会のメンバーの方々ですが、地域沿線の町会の方であったり、商売をされている方であったり事業者であったり、そうした方々にお声かけをしてと考えているところですが、その辺の詳細はこれからしっかり検討していきたいです。","voiceIndex":45,"id":"exchange-004"}]},{"id":"topic-02","title":"事務事業概要を再び議題に供します。 進め方でございますが、先ほどと同様に、災害対策担当も含め、防災まちづくり部の事務事業概要","agenda":"事務事業概要を再び議題に供します。 進め方でございますが、先ほどと同様に、災害対策担当も含め、防災まちづくり部の事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"答えられることで答えていただきたいのですが、避難所環境改善を早期にしていくということが重要かと考えています。下水道耐震化事業のところで、この間一定の計画をしていたところは終わって、新たに設計等を行っていくということですけれども、やはりこれも地震対策として早期に実施していくということが必要だと思うのですが、区全体をやっていくというお考えはあるのか。そこを伺いたいと思います。","respondent":"吉岡防災体制整備担当課長、栗原河川下水道課長","answer":"こういったところが進捗状況のひとつのところです。スケジュールに関しましては、被害想定の見直しというところもございましたので、そういった部分で今後の方向性を検討していくというところになろうかと思います。こういうことを背景といたしまして、品川区といたしましても、下水道局から令和４年度は実施設計を受託いたしまして、実施箇所の選定、それから工事の内容等を決めていきたいと思っていまして。","voiceIndex":85,"id":"exchange-005"},{"speaker":"のだて委員","kind":"意見","question":"羽田新ルートが実施されてもう２年が過ぎていますので、住民への被害ですとか、国の検討事項等を含めて、羽田新ルートについて所管事務調査をしていったらいいのではないかと思います。コロナによって住宅困窮になっている方とかもいるというところで、区内の状況等も含めて研究をしていくべきではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-006"},{"speaker":"横山委員","kind":"意見","question":"私の意見ですけれども、まず１点目に自転車活用推進と放置自転車対策、シェアサイクルも数年たって進んできておりますのと、駐輪場の整備につきまして、今通常の自転車と、あとはお子さんを乗せるような大きなものがあったりしますので、そういったところで計画のところを見ていくような段階になるのではないかと思っているところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点、間違っていたらちょっとわからないですが、災害・環境対策特別委員会との仕分けがあるじゃないですか。これは、令和５年度に防災計画の大規模な修正をやるのだけれども、その計画を多分策定するから、今年度は非常に洗い出しをしてくるということで、その報告というのはここでやるのですか。それは災害・環境対策特別委員会ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"意見","question":"そうしたら、まちづくりのマスタープランも改定されると私は理解をしていて、これはここでやるのだろうと思っているけれども、これについて各地域ごとの詳細を、これまでもやっているのだけれども、もう一回それを改めて見直していくということなので、そこはここでもう一回所管事務調査で、しっかり各地域の洗い出し、どういうところが、よく地域によってはインフラが不足しているとか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-009"},{"speaker":"こんの委員","kind":"意見","question":"は皆さんからご意見を受けた自転車とか、しながわ水族館とか、そうしたところも取り上げていければと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":96,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4350#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":32707,"voices":98}},{"id":"r04-20220606-9","meetingId":"r04-cm06","date":"2022年6月6日","dateIso":"2022-06-06","committee":"文教委員会","time":"午後 １時００分～午後 ２時５７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今どきの問題として、２７ページの学校給食のことがありましたけれども、食材費がかなり高騰しているということで、現状、例えば、給食費の値上がり、あるいは食材のカットなど、子どもたちに影響は出ていないのでしょうかということと、もしそういうことがあれば、コロナの給付金を活用して、やはり子どもたちに影響が出ないように措置すべきだと思うのですけれども、いかがか、ということが１つです。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"２点目の給付金を措置すべきではですけれども、物価などの状況を見ながら検討してまいります。マイスクール、または不登校の児童・生徒ですけれども、議会でご質問がある場合は、きちんとお答えしていると思いますので、表記につきましては、検討させていただきたいと思います。","voiceIndex":28,"id":"exchange-001"},{"speaker":"田中委員","kind":"意見","question":"教育目標のところで、４月１日に一部文言修正とあったのですが、多分、３番のレガシーの部分が変わったのかなということと、あと、もしほかにもあればお知らせくださいというのが１点。もう一点は、３０ページの「学校地域連携係」なのですけれども、「英語教育、学校２０２０レガシー等の事業執行」とあるのですが、この「等」というのは、３７ページの３つを指しているのかというところをお知らせください。","respondent":"宮尾庶務課長","answer":"おめくりいただいて、基本方針のところ１番の(1)番のところは、多様性社会を反映いたしまして、外国人、性自認といったテーマを新たに盛り込んだところです。その他につきまして、あとは、細かい文言修正等をさせていただいているです。","voiceIndex":34,"id":"exchange-002"},{"speaker":"渡部委員","kind":"質問","question":"よろしくお願いします。清水台小学校の「さいかち学級」の話を伺って、予算がついて、副島先生が清水台小学校にいて、お辞めになって、たしか昭和大学で准教授か、何かで続けられていると思うのです。取りあえず、副島先生がまだいるから、昭和大学との話合いでこのように続いているのか、あくまでも、もともと清水台小学校に在席されてやっていたではないですか。","respondent":"矢部教育総合支援センター長","answer":"ただ、１点、今、１７階なのですけれども、コロナ対応があって、７階に移転するということは聞いております。そこぐらいで、あとはこのまま続けていきたいと考えています。","voiceIndex":38,"id":"exchange-003"},{"speaker":"渡部委員","kind":"質問・要望","question":"やはり副島先生におんぶにだっこと言ったらおかしな話なのですけれども、このようなことをやっているのが世の中にそんなにないですし、現に副島先生が清水台小学校にいる頃、マスコミなどで取り上げられたり、最近、テレビに登場する様子はないのかもしれないですけれども、後でも続けられるような仕組みというのは整えていっていただきたいなというところだけ要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"そのガイドラインはあるのか。それぞれについて、少し伺いたいなということが１つです。例えば、認可外保育施設への指導監督等なのですけれども、結構これは大変な業務なのではないかと思うのですが、事業部全体で増員を考えているなど、どのように検討しているのか、検討していないのかということを伺いたいなと思っています。実際には、求職活動を休止してしまっている人などは除かれているわけです。","respondent":"初貝保育教育運営担当課長、中元保育支援課長、廣田子ども育成課長、長谷川児童相談所移管担当課長、立木保育課長","answer":"区立の保育園に関しては、ガイドラインはお示ししていないところなのですけれども、国から随時、コロナの対策に関しまして、その対策。私どもの所管の私立保育園等におきましても同様でございまして、厚生労働省から、先般５月２５日にも第１５報ということで。児童センター・すまいるスクールの対応ですけれども、すまいるスクールにつきましては、学校内にある施設ということから。事務処理体制の検討を進めていく中で、今後、業務量を基に必要な予算や人員について、子ども未来部だけではなく。","voiceIndex":81,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"数の供給についてはめどが立ってきたというご説明もありましたけれども、実態は、先ほど申し上げましたように、求める人で求職活動を停止している人や、徒歩３０分圏内の保育園を希望に入れなかったということで、待機児童から外されている人、あと、認可外に通っているのだけれども、補助を受けているから待機児童ではありませんとなった人など、数の供給のめどが立っているのかということでは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"今、英語のスピーキングテストの問題があるではないですか。今年から始まるということで、その懸念として、塾に通っている子たちはスピーキングテストのことも学べるけれども、そうでない子たちとの格差が生まれてしまうという懸念がある中で、この学習支援事業の中では、その対応がされているのかというところを少し確認したいなと思いました。","respondent":"立木保育課長、染谷子ども家庭支援センター長、飛田子育て応援課長","answer":"実は、昨年度も２名行っておりましたが、内部の事務の扱い方で、今年、ここに表現されているような形に変わりまして、今年は載せさせていただいたです。こちらを１１月に改めて実施した関係で、通常、年度末の時点ですと、全て居住実態を把握できている状況になるのですけれども。学習教材も、各自が学校で行っている教材を基にして行っておりますので。","voiceIndex":89,"id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5068#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":37831,"voices":101}},{"id":"r04-20220606-5","meetingId":"r04-cm06","date":"2022年6月6日","dateIso":"2022-06-06","committee":"総務委員会","time":"午後 １時００分～午後 ３時１８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"新型コロナウイルス感染症対応地方創生臨時交付金について伺いたいのですけれども、これは区のホームページでも、令和２年度の臨時交付金の活用事業一覧ということで、令和３年１０月２１日に令和２年度分が公表されているのです。具体的に、決定額と事業充当額が令和２年度分は出ているのですが、令和３年度分は幾らなのか、また令和４年度分はどうなるのか、その点についても伺いたいと思います。","respondent":"黒田財政課長","answer":"令和３年度につきましても、先日出納閉鎖がございまして、計数も固まりましたので、しかるべき時期に公表の準備を進めてまいりたいと考えています。","voiceIndex":46,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"令和３年度分の交付決定額と事業充当額というのも、多分出ていると思うのですけれども、その額が分かったら教えていただきたいのと、今は結構テレビでも臨時交付金のことについて、各自治体の使い方というので様々取り上げられている部分があると思うのですけれども、区としてどういう計画をつくっていくのか、どういう観点で計画がつくられていくのか、その点を伺いたいのです。","respondent":"黒田財政課長","answer":"ただ、額が、先ほど申し上げたように、それほど物すごく大きな金額ということではありませんので、区の事業の中で効果的に使えるようにということで、区民視点、事業者視点を含めて取り組んでまいりたいと考えています。","voiceIndex":48,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところでは、区民の実態を、直接区民と接している自治体なので、国保医療年金課とか、いろいろな課もそうだと思うのですけれども、深刻な相談を受けていると思いますので、そういうところとも連携を取りながら、本当に困った方に交付金が渡るような形での計画の検討というのを、ぜひしていただきたいということで、これは要望させていただきたいと思います。","respondent":"黒田財政課長","answer":"基準財政需要額の基本的な考え方ですが、これは２３区の場合、２３区が等しく行うべき事業の経費については、基準財政需要額として算定するというところがありますが、一方で、１年間に入ってくる税収というのは決まっておりますので、そこについては見込みを立てて。","voiceIndex":50,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"生活保護の場合、品川区は家賃が高いので、例えば隣の区のほうが家賃が安いので、区を超えて行きたいといっても、そのようなことは原則認められないということになっていると思うのですけれども、生活保護の２５％が区の直接の負担になって、生活保護受給者が増えると、区の負担が増えるというところから、そういうこともあるのかなという思いがしていたのですけれども、その辺のところは都区財政調整制度で。","respondent":"鈴木（真）委員長","answer":"都区財政調整制度の算定で出ますか。急にあれなので、調べてもらうということで、今日はすぐに答えが出しにくいところもあると思うので、改めてお答えをお願いできればと思います。","voiceIndex":52,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"企画部の役割の件等、３つほどお願いしたいのですが。推進ということなのですけれども、当然、調整を図る役とはなっているのですが、具体的に部が主体になってくるのか、企画部というのはどういう役割をするところなのでしょうかというのが、まず１点。それから、コロナ禍とか防災という有事の際に、どこが発進、機動力になるのでしょうか。","respondent":"佐藤（憲）企画調整課長、佐藤（聡）計画担当課長","answer":"３点目の防災、有事の際の対応に関しましては、企画というより危機管理の部門がありますので、総務課と防災課のほうでその辺は担っているです。昨年度、令和３年度、総合実施計画をつくる中で、人口推計ですとか、総合戦略との調整というところで、コンサルタントを使ってやったところでございまして、経費については５８０万円余ということで執行しております。","voiceIndex":56,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"企画部の権限がよく分からないのです。そうすると、あくまでも各部のほうで進め方についても、ある程度自己評価をしながら進めていくのか、庁舎内でのチェック機能というのは企画部にあるべきなのではないかと思うのですが、その辺の実態はどうなっているか、教えてください。コンサルタントの外部の方々の活用というところは、どういう使い方をしているのかなと思うのですけれども、いかがですか。","respondent":"佐藤（憲）企画調整課長、佐藤（聡）計画担当課長","answer":"既存の課題に関しましては、所管と情報共有し、企画部の視点でどういう方向性がベストなのかというのを検討するというところです。私からは、コンサルタントの使い方というところかと考えております。昨年度の総合実施計画もそうなのですけれども、大体、行政として方向性を決めるときの議論の材料になるものを集めてもらうというところが一つかと思います。","voiceIndex":59,"id":"exchange-006"}]},{"id":"topic-02","title":"に戻りまして、幹部職員紹介","agenda":"に戻りまして、幹部職員紹介","exchanges":[{"speaker":"西本委員","kind":"確認","question":"幾つか確認をさせてください。人事関係です。定数なのですけれども、最近どういう動向になっていますか。多分、保育課とかも、かなり増やしたケースがあると思うのですけれども、今どういう状況か、数年間の動向が分かれば教えてください。最近はどのぐらいいるのですか。３点目は、再任用職員なのですけれども、その制度が始まって、これをどう運用していくのか。","respondent":"崎村人事課長","answer":"今後につきましては、地方公務員法等の改正がございまして、定年年齢が６５歳に引き上げられるといったところで、再任用制度についても少し見直しが行われる予定ですので、そういったところを各職員にしっかりと周知して、６５歳までの働き方という部分については。","voiceIndex":98,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"中身にまでは入っていきませんけれども、実態は分かりました。今後、地方公務員制度が変わっていって、６５歳定年になっていくときの、これも大分進んでいて、あと数年の先という形が目の前に差しかかっていると思うのですけれども、その準備等々は、庁内では検討が既に始まっているのか、その辺の状況だけ教えてください。","respondent":"崎村人事課長","answer":"我々管理職の部分については、役職定年制というものも導入される予定ですので、そういった制度について、国や都の動向なども踏まえながら、現在検討しています。","voiceIndex":100,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今の職員体制のことで、さらに追加でお伺いしたいのですが、職員定数の、合計の、総職員数というのは、令和４年度の段階で何人なのかというのを教えていただきたいと思います。それで、会計年度任用職員の方の配置というのは、どういうところに配置していくという考えがあるのか、その点についても伺いたいと思います。","respondent":"崎村人事課長","answer":"今年度についても今、計算をしているところですけれども、ほとんど変わらない状況です。会計年度任用職員の配置の考え方というところと、数字のところですけれども、令和３年度と令和４年度は、大体１,３００名ほどの会計年度任用職員を任用して配置をしています。","voiceIndex":102,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"正規の職員の補助ということなのですけれども、例えば、暮らし・しごと応援センターの部署は、１人以外のところが、多分全員が会計年度任用職員なのです。会計年度任用職員というのは１年ごとなので、賃金を上げて、もう少しモチベーションを上げられるような仕組みというのはできないものなのか、それは制度としてどういう状況になっているのかも含めて、教えていただけたらと思っています。","respondent":"崎村人事課長","answer":"我々常勤職員というのは、入区しますと初任給という形があって、年々昇給していく形になるかと思うのですけれども、そういう形で、例えば、最低ではないのですが、低く報酬額を設定して、引き続き来年度も続けられる方については昇給するという考え方も。","voiceIndex":104,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それは制度の仕組みとして、そういうことはできないということなのか、考え方として、そういうことなのかという辺りを教えていただきたいのですけれども。しかも、そんなに高額な評価という感じで私は思っていないのですが、制度そのものがどうなっているのか、そういうことでできないものなのか、その辺の評価というのも必要なのではないかと思うのですけれども、そこの考え方を改めて伺いたいと思います。","respondent":"崎村人事課長","answer":"制度としてというところでお答えをすれば、制度として昇給制度はできますという答えになります。ただ、考え方としては、先ほどお話をさせていただいたように、職の専門性、必要性に応じた報酬額を設定して、品川区では支払うです。","voiceIndex":106,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"専門職というのは、いろいろなところで正規で働いていると思うのですけれども、そういう中で、品川区が専門職の方を会計年度任用職員という形で採用されているということですので、それは制度として、賃金を上げられないということではないということなので、ぜひその辺は今後に向けて検討していただいて、きちんと評価をしていただけたらと思いますし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-012"},{"speaker":"吉田委員","kind":"確認","question":"何点か伺いたいと思うのですけれども、最初に、総務課の総務係で、私立学校に関することとありますが、中身を見ると、全部合わせて１０校に関すること、１０校の限定的といいますか、そういうものなのでしょうか。それから、その中の調査というのが気になるのですけれども、どういう内容なのか、不勉強で申し訳ありませんが、伺いたいと思います。それからもう一つは、文書管理事務のほうです。","respondent":"古巻総務課長、崎村人事課長","answer":"私立学校に関することですけれども、そちらに専修学校、各種学校で、９校と１校と記載させていただいていますが、区内の専修学校・各種学校に関する事務を、東京都の条例に基づいて担っているという形ですので。採用に関する事務というところで、委員のお話にありましたけれども、各所管でどのぐらいの人数が必要かという部分の業務につきましては。","voiceIndex":109,"id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"それからもう一つ、人権啓発課のことも続いて伺います。人権啓発についても、しながわ人権のひろばについての小中学校の児童・生徒による人権標語・ポスター展を実施というところで、指導課と教育総合支援センターとの連携があるのですけれども、そこは連携はあるのですねというのが、１つ確認なのです。前向きに、ぜひそう考えていただきたいということで質問なのですけれども、いかがでしょうか。","respondent":"古巻総務課長、加島人権啓発課長","answer":"文書管理に関してですけれども、委員からご指摘のあったとおり、一貫性というのは非常に重要なことだと考えていますので、しっかり適正に文書が保存され、保管され、運用されているといった状況につきましては。私どもはこれからも、主にこちらの市民科の教科書を担当しております教育総合支援センターと密に話し合える連携を取りまして、様々な区内の人々の権利が守られていくよう、取組をしていきたいと考えております。","voiceIndex":112,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"文書についてはよく分かりました。ぜひそのようにお願いしたいと思います。人権啓発ですけれども、今もお答えの中に市民科というのが出てきましたが、いろいろ質問すると、それは市民科の中でやっておりますという感じなのですが、子どもの権利ということを大人が理解するためには、学校教育の中ではできないと思いますので、ぜひその辺のことを今後検討していただけたらと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-015"},{"speaker":"つる副委員長","kind":"確認","question":"古くは２００４年の質疑で、それ以来なくて、２００４年度に確認ができているのですけれども、総務部の概要の１ページの中にある、「企画部とともに区行政執行のためのサービススタッフ機能を受け持っている」というので、具体的にどういうことかということを教えていただければと思います。サービススタッフ、それからサービススタッフ機能ということを教えてください。","respondent":"古巻総務課長","answer":"「企画部とともに」ということで、全庁的に連携をしていかなければいけないものに関しまして、企画部と総務部で連携というのはあれですけれども、それぞれ区役所としての行政機能をしっかり執行できる、例えばいろいろな部門へのバックアップとか。","voiceIndex":117,"id":"exchange-016"},{"speaker":"つる副委員長","kind":"意見","question":"それがまさにここの、どの部門にも属さない事象というところでの対応だったりするのかなと思ったときに、サービススタッフという立ち位置が、職員にとって当然ありがたい存在だと思うのですけれども、具体的にどういうものなのかというところが、今のご答弁の中では、「私はそのように捉えている」となってしまうと、いろいろな捉え方が、逆にまた無尽蔵に出てくるのかなと思ったのですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":119,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これを見ると、８,４００世帯も非課税になっていくのかなという思いがしたのですが、実際に８,４００世帯が非課税になるということなのか、この数字と、厚生委員会で先日話があった、８,４００世帯が新たに非課税になるというところとの整合性がどうなのかという思いがしているのですけれども、その点を教えていただきたい。","respondent":"提坂税務課長","answer":"あくまでもこちらの資料は非課税者ということで、非課税世帯の細かい数字というのは、私どもは把握していませんけれども、同じ世帯の中にも非課税者が複数いる場合とか、１人の場合とか、いろいろなパターンがあると思うのですが、そういうことで精査した結果。","voiceIndex":121,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"分からないですね。非課税世帯となると、多分、全員が非課税という世帯なので、より厳しくなると思っていたのですけれども、それがこの数字と本当に合っているのかなという思いがしたので、お聞きしたのですが、税務課と厚生委員会のところの推計値の出し方の違いなのかどうなのか、よく分かりませんが、ここでは税務課ということで、以上で分からないままで結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-019"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"湯澤委員","kind":"質問・要望","question":"３点ほどありまして、１つは行政評価について。こちらは先ほども申し上げましたけれども、行政のニーズというのはかなり変化・進化をしていると思っておりまして、そういったことに対応する新しい部署を新設したり、また既存の課の中でも、新しい知識や技術といったものも求められているかと思いますので、人材育成について調査をしていただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"最近区民からいろいろ相談を受けるのですが、民間企業、とりわけ大手企業において、新しい人材を採用するときに、様々な結果として、採用したら、なかなかうまく会社に順応しないような人が本当に増えているという話を、人事の方から何件かお聞きしたのですが、品川区も民間の人を採用しているのですが、企業であろうと、自治体であろうと、人はどんな人が支えてくれるかということは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"今日、事務事業概要を伺ったばかりなので、もう少しじっくりと検討したいという思いはあるのですが、私は、ジェンダーギャップ指数もすごく低いという状況になっている中で、男女共同参画のところは入れていただきたいと。具体的にこういうことというのは、もう少し検討して提案させていただきたいと思うのですが、今日の今日、決めるというわけではないということでいいのですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-022"},{"speaker":"西本委員","kind":"意見","question":"男女共同参画について、これは男女共同参画という言葉がいいのかどうかというのに疑問があって、今のご時世、男女というので済まされるのかというので、中身は先ほどの重要な内容で、ジェンダーとかいろいろ入っているのですけれども、項目として、男女共同参画という言葉でいいのかというのが疑問なのです。もっと広い意味で取り組むべき内容かもしれないなというのは、私も感じたところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":134,"id":"exchange-023"},{"speaker":"つる副委員長","kind":"質問・要望","question":"人材関係のところは、例年この総務委員会で取り上げられていて、今日は項目の洗い出しなので、細かいことはあれですが、先ほど須貝委員からありましたけれども、採用時における区が求める人材像ですとか、当然、採用されてからの育成というところで、まさにそれが人材育成だと思うのですが、よくどの企業だとか事業体でもそうなのですけれども、特に区行政にあっては、職員となった場合には。","respondent":"鈴木（真）委員長","answer":"今後、再開のお知らせがあった暁には、改めて皆様にご案内いたしたいと考えておりますので、ご承知おきください。以上で、その他を終了いたします。以上で、本日の予定は全て終了いたしました。","voiceIndex":135,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2234#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":41054,"voices":136}},{"id":"r04-20220607-14","meetingId":"r04-cm06","date":"2022年6月7日","dateIso":"2022-06-07","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時３９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"新庁舎整備に向けた検討状況について伺いたいのですが、２番のところに、この間行ってきた策定委員会の中身が書かれているのですが、第１０回のところでパブリックコメント結果というのがありますけれども、このパブリックコメントはいつ頃行うのかというのを教えていただきたいのと、区民に対してパブリックコメントを行うに当たって、区民への説明会をぜひとも開いていただきたいと思うのです。","respondent":"山下新庁舎整備課長","answer":"３点ご質問いただいたかと思います。１点目のパブリックコメントの実施予定につきましては、７月の第９回策定委員会を経まして、８月頃にパブリックコメントを実施することで予定をしているところです。","voiceIndex":40,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"それと、既に令和３年度に会議体を設けて、様々な体制確認も行いながら、課題の洗い出しを行ったということであるのですけれども、この会議体というのは３つの部署が集まった会議体なのか、その会議体の体制と、どれぐらいの会議が行われてきたのか、また洗い出しを行ったということですけれども、この中身はきちんとまとめられたものがあるのかどうか、その点についても伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"本日は組織体制というところで、企画でこういった形の資料をお出ししてご説明をさせていただいておりまして、ちょっとお答えできないこともあるのですが、まず、手挙げ方式かというところは手挙げ方式で、例えば。","voiceIndex":42,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"分かりました。この地域包括支援センターが、品川区は地域に作られていないのですけれども、地域包括支援センターを地域に作るべきだということで私たちはずっと提案してきているのですけれども、その検討というのは、企画とかが関わるということがあるのでしょうか。","respondent":"佐藤企画調整課長","answer":"地域包括支援センターに関するご質問ですが、そちらは所管で検討し、これまでご答弁していると思うのですけれども、所管で判断をして、考えているところで、企画として入って何かというところは行っておりません。","voiceIndex":44,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問","question":"それを全て把握してやっていくというのも、今民間企業とかでそういうアプリを作って、区と連携してそこへ飛んでいくというようなシステムがあったりすると、そういうのをぱっと入れている区もたくさん出てきているところがあるとなると、区の職員の方の負担を軽減する、あとそのほうがかえっていいというのがあったりすると、そういうのを積極的に取り入れていくというのは、どこでやるのか、所管でやるのか。","respondent":"河西情報戦略担当課長","answer":"我々もそちらを把握しておりますが、委員がおっしゃったように、これからシステムでも対応が必要になってまいります。","voiceIndex":48,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"ぜひそういうことでよろしくお願いします。今の一緒にやっていくのはいいですけれども、必ずお金の部分というのがあるじゃないですか。そうすると、「待とう」みたいな話になるから、あと民間の部分も、１社とやっていいのかみたいなことにもなるではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-005"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"新庁舎についてですけれども、いよいよ基本計画という段階に来ていますけれども、改めてつい最近建て替えた庁舎の視察とかを組み込んでいただけたら、今までも視察は委員会で行ったり、私たちも会派で行ったりはしているのですけれども、漠然とこれから庁舎を作るよというときと、またいろいろ具体的に検討がされてきたときとでは、また見方も違うかなと思ったりしていて、そういう視点で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6130#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":12663,"voices":55}}]);
